(function initApiBase() {
  try {
    var custom = localStorage.getItem('API_BASE');
    if (custom) {
      API_BASE = custom;
      return;
    }
    var loc = window.location;
    if (loc.protocol === 'file:') {
      API_BASE = 'http://127.0.0.1:8000';
      return;
    }
    console.info('[api] API_BASE=', API_BASE || '(same-origin)');
  } catch (e) {}
})();

