async function startAssessment(taskId) {
  var body = { task_id: Number(taskId) };
  var ctx = moduleState.cycleTaskContext;
  if (ctx.active) {
    body.score_branch = ctx.branch || 'practice';
    body.cycle_day_index = ctx.dayIndex || null;
  }
  var res = await apiFetch('/api/assessment/start', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
  return res && res.data ? res.data : {};
}

