function digitalHumanPrefsStorageKey() {
  var uid = String(localStorage.getItem('userId') || localStorage.getItem('username') || 'anonymous').trim() || 'anonymous';
  return DIGITAL_HUMAN_PREFS_STORAGE_KEY + ':' + uid;
}

function normalizeDigitalHumanSystemSettings(raw) {
  var obj = raw && typeof raw === 'object' ? raw : {};
  var provider = String(obj.tts_provider || '').trim().toLowerCase();
  if (provider !== 'browser' && provider !== 'minimax') provider = 'minimax';
  return {
    enabled: obj.enabled !== false,
    tts_provider: provider,
    minimax_configured: obj.minimax_configured !== false,
    loaded: !!obj.loaded,
    loading: !!obj.loading,
    saving: !!obj.saving,
    error: String(obj.error || '').trim(),
  };
}

function normalizeDigitalHumanPreferences(raw) {
  var obj = raw && typeof raw === 'object' ? raw : {};
  var scenes = obj.scenes && typeof obj.scenes === 'object' ? obj.scenes : {};
  var legacyPractice = scenes.practice;
  return {
    voice_muted: obj.voice_muted === true,
    auto_voice_enabled: obj.auto_voice_enabled !== false,
    scenes: {
      practice_score: scenes.practice_score !== undefined ? scenes.practice_score !== false : legacyPractice !== false,
      practice_turn_feedback: scenes.practice_turn_feedback !== false,
      assistant: scenes.assistant !== false,
      knowledge_qa: scenes.knowledge_qa !== false,
    },
    mouse_follow: obj.mouse_follow !== false,
    drag_rotate: obj.drag_rotate !== false,
    idle_hint: obj.idle_hint !== false,
    emotion_bubble: obj.emotion_bubble !== false,
    micro_expression: obj.micro_expression !== false,
    page_greeting: obj.page_greeting !== false,
    minimax_voice_id: (function() {
      var vid = String(obj.minimax_voice_id || '').trim();
      if (!vid) return '';
      var valid = MINIMAX_VOICE_OPTIONS.some(function(v) { return v.id === vid; });
      return valid ? vid : '';
    })(),
  };
}

var DIGITAL_HUMAN_INTERACTION_PREF_KEYS = [
  'mouse_follow',
  'drag_rotate',
  'idle_hint',
  'emotion_bubble',
  'micro_expression',
  'page_greeting',
];

var MINIMAX_VOICE_OPTIONS = [
  { id: 'female-tianmei', label: '甜美', desc: '温柔亲切' },
  { id: 'female-chengshu', label: '成熟', desc: '沉稳大方' },
  { id: 'female-shaonv', label: '少女', desc: '清新活泼' },
  { id: 'female-yujie', label: '御姐', desc: '优雅知性' },
  { id: 'Chinese (Mandarin)_Cute_Spirit', label: '可爱', desc: '萌系甜美' },
  { id: 'Chinese (Mandarin)_Soft_Girl', label: '温柔', desc: '轻柔细腻' },
  { id: 'Chinese (Mandarin)_News_Anchor', label: '主持人', desc: '新闻女声' },
  { id: 'danya_xuejie', label: '淡雅', desc: '古典优雅' },
  { id: 'wumei_yujie', label: '妩媚', desc: '妩媚御姐' },
  { id: 'diadia_xuemei', label: '学妹', desc: '嗲嗲学妹' },
  { id: 'qiaopi_mengmei', label: '俏皮', desc: '俏皮萌妹' },
  { id: 'tianxin_xiaoling', label: '甜心', desc: '甜心小玲' },
];

function normalizeDigitalHumanContext(raw) {
  var obj = raw && typeof raw === 'object' ? raw : {};
  return {
    focus_source: String(obj.focus_source || '').trim(),
    focus_dimension: String(obj.focus_dimension || '').trim(),
    mentor_sentence: String(obj.mentor_sentence || '').trim(),
    coach_tip: String(obj.coach_tip || '').trim(),
    knowledge_patch: String(obj.knowledge_patch || '').trim(),
    module_code: String(obj.module_code || '').trim(),
    scene_code: String(obj.scene_code || '').trim(),
    difficulty_level: String(obj.difficulty_level || '').trim(),
    knowledge_question: String(obj.knowledge_question || '').trim(),
    assistant_scene_input: String(obj.assistant_scene_input || '').trim(),
    practice_turn_feedback_summary: String(obj.practice_turn_feedback_summary || '').trim(),
    practice_turn_feedback_voice_advice: String(obj.practice_turn_feedback_voice_advice || '').trim(),
    practice_score_mentor_sentence: String(obj.practice_score_mentor_sentence || '').trim(),
    updated_at: String(obj.updated_at || '').trim(),
  };
}

function loadDigitalHumanContextFromStorage() {
  try {
    var raw = sessionStorage.getItem(digitalHumanContextStorageKey());
    if (!raw) return normalizeDigitalHumanContext(null);
    return normalizeDigitalHumanContext(JSON.parse(raw));
  } catch (e) {
    return normalizeDigitalHumanContext(null);
  }
}

function loadDigitalHumanPreferencesFromStorage() {
  try {
    var raw = localStorage.getItem(digitalHumanPrefsStorageKey());
    if (!raw) raw = localStorage.getItem(LEGACY_DIGITAL_HUMAN_PREFS_STORAGE_KEY);
    if (!raw) return normalizeDigitalHumanPreferences(null);
    return normalizeDigitalHumanPreferences(JSON.parse(raw));
  } catch (e) {
    return normalizeDigitalHumanPreferences(null);
  }
}

function saveDigitalHumanContextToStorage() {
  try {
    sessionStorage.setItem(
      digitalHumanContextStorageKey(),
      JSON.stringify(normalizeDigitalHumanContext(moduleState.digitalHumanContext || {}))
    );
  } catch (e) {}
}

function saveDigitalHumanPreferencesToStorage() {
  try {
    localStorage.setItem(
      digitalHumanPrefsStorageKey(),
      JSON.stringify(normalizeDigitalHumanPreferences(moduleState.digitalHumanPreferences || {}))
    );
  } catch (e) {}
}

function getDigitalHumanContext() {
  moduleState.digitalHumanContext = normalizeDigitalHumanContext(moduleState.digitalHumanContext);
  return moduleState.digitalHumanContext;
}

function getDigitalHumanSystemSettingsState() {
  if (!moduleState.systemSettings) moduleState.systemSettings = {};
  moduleState.systemSettings.digitalHuman = normalizeDigitalHumanSystemSettings(moduleState.systemSettings.digitalHuman);
  return moduleState.systemSettings.digitalHuman;
}

function setDigitalHumanSystemSettingsState(patch) {
  var next = Object.assign({}, getDigitalHumanSystemSettingsState(), patch || {});
  moduleState.systemSettings.digitalHuman = normalizeDigitalHumanSystemSettings(next);
  return moduleState.systemSettings.digitalHuman;
}

function syncDigitalHumanSystemSettingsDraft() {
  if (!moduleState.systemSettings) moduleState.systemSettings = {};
  var state = getDigitalHumanSystemSettingsState();
  moduleState.systemSettings.digitalHumanDraft = {
    enabled: !!state.enabled,
    tts_provider: String(state.tts_provider || 'minimax').trim() || 'minimax',
  };
  return moduleState.systemSettings.digitalHumanDraft;
}

function getDigitalHumanSystemSettingsDraft() {
  if (!moduleState.systemSettings) moduleState.systemSettings = {};
  var draft = moduleState.systemSettings.digitalHumanDraft;
  if (!draft || typeof draft !== 'object') return syncDigitalHumanSystemSettingsDraft();
  var provider = String(draft.tts_provider || '').trim().toLowerCase();
  if (provider !== 'browser' && provider !== 'minimax') provider = 'minimax';
  moduleState.systemSettings.digitalHumanDraft = {
    enabled: draft.enabled !== false,
    tts_provider: provider,
  };
  return moduleState.systemSettings.digitalHumanDraft;
}

function setDigitalHumanSystemSettingsDraft(patch) {
  var current = getDigitalHumanSystemSettingsDraft();
  var next = {
    enabled: patch && patch.enabled !== undefined ? !!patch.enabled : current.enabled,
    tts_provider: String(
      patch && patch.tts_provider !== undefined ? patch.tts_provider : current.tts_provider
    ).trim().toLowerCase(),
  };
  if (next.tts_provider !== 'browser' && next.tts_provider !== 'minimax') next.tts_provider = 'minimax';
  moduleState.systemSettings.digitalHumanDraft = next;
  return next;
}

async function fetchDigitalHumanSystemSettings(options) {
  options = options || {};
  var state = getDigitalHumanSystemSettingsState();
  if (state.loading && !options.force) return state;
  setDigitalHumanSystemSettingsState({ loading: true, error: '' });
  try {
    var res = await apiFetch('/api/system-settings/digital-human', { method: 'GET' });
    var next = normalizeDigitalHumanSystemSettings(Object.assign({}, res && res.data ? res.data : {}, {
      loaded: true,
      loading: false,
      saving: false,
      error: '',
    }));
    moduleState.systemSettings.digitalHuman = next;
    syncDigitalHumanSystemSettingsDraft();
    if (!next.enabled && typeof destroyDigitalHuman === 'function') destroyDigitalHuman();
    return next;
  } catch (e) {
    var fallback = normalizeDigitalHumanSystemSettings(Object.assign({}, state, {
      loaded: true,
      loading: false,
      saving: false,
      error: String(e && e.message || '').trim(),
    }));
    moduleState.systemSettings.digitalHuman = fallback;
    syncDigitalHumanSystemSettingsDraft();
    return fallback;
  }
}

async function ensureDigitalHumanSystemSettingsLoaded(options) {
  var state = getDigitalHumanSystemSettingsState();
  if (state.loaded && !(options && options.force)) return state;
  return fetchDigitalHumanSystemSettings(options);
}

function isDigitalHumanSystemEnabled() {
  return !!getDigitalHumanSystemSettingsState().enabled;
}

function getDigitalHumanTtsProvider() {
  return String(getDigitalHumanSystemSettingsState().tts_provider || 'minimax').trim().toLowerCase() || 'minimax';
}

function getDigitalHumanPreferences() {
  var currentKey = digitalHumanPrefsStorageKey();
  if (moduleState.digitalHumanPreferencesStorageKey && moduleState.digitalHumanPreferencesStorageKey !== currentKey) {
    moduleState.digitalHumanPreferences = loadDigitalHumanPreferencesFromStorage();
  }
  moduleState.digitalHumanPreferencesStorageKey = currentKey;
  moduleState.digitalHumanPreferences = normalizeDigitalHumanPreferences(moduleState.digitalHumanPreferences);
  return moduleState.digitalHumanPreferences;
}

function notifyDigitalHumanPreferenceSync() {
  if (typeof window !== 'undefined' && typeof window.digitalHumanSyncPreferences === 'function') {
    try {
      window.digitalHumanSyncPreferences();
    } catch (e) {}
  }
}

function setDigitalHumanContext(patch) {
  var next = Object.assign({}, getDigitalHumanContext(), patch || {});
  next.updated_at = new Date().toISOString();
  moduleState.digitalHumanContext = normalizeDigitalHumanContext(next);
  saveDigitalHumanContextToStorage();
  return moduleState.digitalHumanContext;
}

function setDigitalHumanPreferences(patch) {
  var current = getDigitalHumanPreferences();
  var nextRaw = {
    voice_muted: patch && patch.voice_muted !== undefined ? patch.voice_muted : current.voice_muted,
    auto_voice_enabled: patch && patch.auto_voice_enabled !== undefined ? patch.auto_voice_enabled : current.auto_voice_enabled,
    scenes: Object.assign({}, current.scenes, patch && patch.scenes || {}),
    minimax_voice_id: patch && patch.minimax_voice_id !== undefined ? patch.minimax_voice_id : current.minimax_voice_id,
  };
  DIGITAL_HUMAN_INTERACTION_PREF_KEYS.forEach(function (key) {
    nextRaw[key] = patch && patch[key] !== undefined ? patch[key] : current[key];
  });
  var next = normalizeDigitalHumanPreferences(nextRaw);
  moduleState.digitalHumanPreferences = next;
  moduleState.digitalHumanPreferencesStorageKey = digitalHumanPrefsStorageKey();
  saveDigitalHumanPreferencesToStorage();
  notifyDigitalHumanPreferenceSync();
  return next;
}

function shouldAutoPlayDigitalHumanVoice(scene) {
  var prefs = getDigitalHumanPreferences();
  if (!prefs.auto_voice_enabled) return false;
  if (scene === 'practice' || scene === 'practice_score') return !!prefs.scenes.practice_score;
  if (scene === 'practice_turn_feedback') return !!prefs.scenes.practice_turn_feedback;
  if (scene === 'assistant') return !!prefs.scenes.assistant;
  if (scene === 'knowledge_qa') return !!prefs.scenes.knowledge_qa;
  return true;
}

function digitalHumanWeakQuestion(focusDimension) {
  var focus = String(focusDimension || '').trim();
  if (!focus) return '帮我补一下最近最容易失分的知识点。';
  return '帮我补一下“' + focus + '”最容易说错的关键点。';
}

function buildDigitalHumanHomeDirectorPayload() {
  var ctx = getDigitalHumanContext();
  if (!ctx.updated_at) return null;
  var ts = Date.parse(ctx.updated_at);
  if (!isFinite(ts) || (Date.now() - ts) > 7 * 24 * 60 * 60 * 1000) return null;

  if (ctx.focus_source === 'practice' && ctx.focus_dimension) {
    return {
      eyebrow: '数字人接力',
      title: '今天先补“' + ctx.focus_dimension + '”',
      desc: '你最近陪练里这块最容易失分，先补清关键点，再回到陪练里收口一轮。',
      actionLabel: '去知识补漏',
      actionPage: 'knowledge_qa',
      actionQuestion: ctx.knowledge_question || digitalHumanWeakQuestion(ctx.focus_dimension),
      actionModuleCode: ctx.module_code || '',
      actionSceneCode: ctx.scene_code || '',
      actionDifficulty: ctx.difficulty_level || 'standard',
      chips: ['来源：智能陪练', ctx.focus_dimension],
      briefText: '你今天先补' + ctx.focus_dimension + '，因为最近陪练里这块最容易失分；做完后我再带你回到陪练里收口一次。'
    };
  }

  if (ctx.focus_source === 'assistant' && ctx.coach_tip) {
    return {
      eyebrow: '数字人接力',
      title: '今天先复盘现场话术',
      desc: '你最近现场应答里有一条高频提醒，先吃透这句提示，再回到在岗助手里试一轮。',
      actionLabel: '去在岗助手',
      actionPage: 'on_duty_assistant',
      actionAssistantInput: ctx.assistant_scene_input || '顾客对珠宝价值存在疑虑',
      chips: ['来源：在岗助手', '话术收口'],
      briefText: '你今天先复盘一条现场话术提醒，因为这类回应最容易影响顾客信任；做完后我再带你试一轮真实应答。'
    };
  }

  if (ctx.focus_source === 'knowledge_qa' && (ctx.knowledge_patch || ctx.focus_dimension)) {
    return {
      eyebrow: '数字人接力',
      title: '今天先把知识点讲顺',
      desc: '你最近刚补过一个关键知识点，建议现在回到陪练，把它真正说出口。',
      actionLabel: '去智能陪练',
      actionPage: 'practical_training',
      actionModuleCode: ctx.module_code || '',
      actionSceneCode: ctx.scene_code || '',
      actionDifficulty: ctx.difficulty_level || 'standard',
      chips: ['来源：知识问答', ctx.focus_dimension || '知识补漏'],
      briefText: '你今天先把刚补过的知识点讲顺，因为知道和会说是两回事；做完后我再帮你看一轮表达是否稳。'
    };
  }

  return null;
}

function applyHomeFocusActionPrefill(focus) {
  var payload = focus && typeof focus === 'object' ? focus : {};
  var page = String(payload.actionPage || '').trim();
  if (page === 'practical_training') {
    if (payload.actionModuleCode) moduleState.practice.module_code = String(payload.actionModuleCode).trim();
    if (payload.actionSceneCode) moduleState.practice.scene_code = String(payload.actionSceneCode).trim();
    if (payload.actionDifficulty) moduleState.practice.difficulty_level = String(payload.actionDifficulty).trim();
  } else if (page === 'knowledge_qa') {
    if (payload.actionQuestion) moduleState.knowledgeQa.question = String(payload.actionQuestion).trim();
  } else if (page === 'on_duty_assistant') {
    if (payload.actionAssistantInput) moduleState.assistant.scene_input = String(payload.actionAssistantInput).trim();
  }
}

function resolveAssistantDigitalHumanSpeech(assistantState) {
  var state = assistantState && typeof assistantState === 'object' ? assistantState : (moduleState.assistant || {});
  var reply = state.replyResult && typeof state.replyResult === 'object' ? state.replyResult : {};
  var latestTurnFeedback = state.latestTurnFeedback && typeof state.latestTurnFeedback === 'object'
    ? state.latestTurnFeedback
    : null;
  var replyTurnFeedback = reply.turn_feedback && typeof reply.turn_feedback === 'object'
    ? reply.turn_feedback
    : null;
  return String(
    state.lastDigitalHumanSpeech ||
    (latestTurnFeedback ? latestTurnFeedback.voice_advice : '') ||
    (replyTurnFeedback ? replyTurnFeedback.voice_advice : '') ||
    reply.voice_advice ||
    reply.coach_tip ||
    ''
  ).trim();
}

function digitalHumanGetPageSpeechText(pageId) {
  var page = String(pageId || '').trim();
  if (page === 'on_duty_assistant') {
    return resolveAssistantDigitalHumanSpeech();
  }
  if (page === 'knowledge_qa') {
    return String((moduleState.knowledgeQa && moduleState.knowledgeQa.lastDigitalHumanSpeech) || '').trim();
  }
  if (page === 'practical_training') {
    return resolvePracticePageSpeechText();
  }
  if (page === 'assessment') {
    var assessmentSession = getSelectedAssessmentSession(false) || ensureAssessmentState();
    var assessmentCoach = normalizeAssessmentCoach(assessmentSession && assessmentSession.coach);
    if (assessmentCoach.hint_text) return String(assessmentCoach.hint_text || '').trim();
    if (assessmentSession && assessmentSession.resultData) {
      return String(buildAssessmentResultDebrief(assessmentSession.resultData).hint_text || '').trim();
    }
  }
  return '';
}

function homeBiTrainingActivityRate(evidence) {
  var source = evidence || {};
  var total = Number(source.total_employees || 0);
  var active = Number(source.monthly_active || 0);
  if (!(total > 0) || !isFinite(active)) return null;
  var rate = (active / total) * 100;
  return Math.max(0, Math.min(100, Math.round(rate * 10) / 10));
}

function buildManagementHomeBiConclusion(data) {
  var payload = data || {};
  var headline = payload.headline || {};
  var evidence = payload.evidence || {};
  var riskSnapshot = payload.risk_snapshot || {};
  var highRiskCount = Number(riskSnapshot.high_risk_count != null ? riskSnapshot.high_risk_count : headline.high_risk_count || 0);
  var taskCompletionRate = Number(headline.task_completion_rate);
  var activityRate = homeBiTrainingActivityRate(evidence);
  if (highRiskCount > 0 && isFinite(taskCompletionRate) && taskCompletionRate < 85) {
    return '当前存在风险点，优先处理高风险人员并补足任务完成率';
  }
  if (highRiskCount > 0) {
    return '当前存在风险点，优先核查高风险人员与最新风险快照';
  }
  if (isFinite(activityRate) && activityRate < 60) {
    return '当前风险可控，但训练活跃度偏低';
  }
  if (isFinite(taskCompletionRate) && taskCompletionRate < 85) {
    return '当前整体稳定，优先提升任务完成率';
  }
  return '当前整体稳定，优先关注训练完成率与风险快照';
}

function buildHomeHeroSubtitle() {
  var role = normalizeRole(localStorage.getItem('role') || '');
  if (role === 'admin' || role === 'store_manager') {
    var state = homeBiState();
    if (state && state.data) {
      return buildManagementHomeBiConclusion(state.data);
    }
    return '当前整体稳定，优先关注训练完成率与风险快照';
  }
  return '先处理今日任务，再跟进训练进度和最近学习变化';
}

async function renderHomeFocusCard(containerEl) {
  if (!containerEl) return;

  containerEl.innerHTML =
    '<div class="home-lx-focus-card home-lx-focus-card--loading">' +
      '<div class="home-lx-focus-card__content">' +
        '<div class="home-lx-focus-card__eyebrow">今日概览</div>' +
        '<h2 class="home-lx-focus-card__title">正在整理今日优先事项...</h2>' +
        '<p class="home-lx-focus-card__desc">稍后会显示当前最值得先处理的动作</p>' +
      '</div>' +
    '</div>';

  var role = normalizeRole(localStorage.getItem('role') || '');
  var directorFocus = (role === 'admin' || role === 'store_manager') ? null : buildDigitalHumanHomeDirectorPayload();
  if (directorFocus) {
    containerEl.innerHTML =
      '<div class="home-lx-focus-card">' +
        '<div class="home-lx-focus-card__content">' +
          '<div class="home-lx-focus-card__eyebrow">' + escapeHtml(directorFocus.eyebrow) + '</div>' +
          '<h2 class="home-lx-focus-card__title">' + escapeHtml(directorFocus.title) + '</h2>' +
          '<p class="home-lx-focus-card__desc">' + escapeHtml(directorFocus.desc) + '</p>' +
          '<div class="home-lx-focus-card__chips">' +
            directorFocus.chips.map(function (chip) {
              return '<span class="home-lx-focus-card__chip">' + escapeHtml(chip) + '</span>';
            }).join('') +
          '</div>' +
        '</div>' +
        '<div class="home-lx-focus-card__actions">' +
          '<button type="button" class="home-lx-button home-lx-button--primary"' +
            ' data-home-focus-page="' + escapeHtml(directorFocus.actionPage || '') + '"' +
            ' data-home-focus-question="' + escapeHtml(directorFocus.actionQuestion || '') + '"' +
            ' data-home-focus-assistant-input="' + escapeHtml(directorFocus.actionAssistantInput || '') + '"' +
            ' data-home-focus-module-code="' + escapeHtml(directorFocus.actionModuleCode || '') + '"' +
            ' data-home-focus-scene-code="' + escapeHtml(directorFocus.actionSceneCode || '') + '"' +
            ' data-home-focus-difficulty="' + escapeHtml(directorFocus.actionDifficulty || '') + '">' +
            escapeHtml(directorFocus.actionLabel) +
          '</button>' +
        '</div>' +
      '</div>';
    var directorBtn = containerEl.querySelector('[data-home-focus-page]');
    if (directorBtn) {
      directorBtn.addEventListener('click', function () {
        var focus = {
          actionPage: String(this.getAttribute('data-home-focus-page') || '').trim(),
          actionQuestion: String(this.getAttribute('data-home-focus-question') || '').trim(),
          actionAssistantInput: String(this.getAttribute('data-home-focus-assistant-input') || '').trim(),
          actionModuleCode: String(this.getAttribute('data-home-focus-module-code') || '').trim(),
          actionSceneCode: String(this.getAttribute('data-home-focus-scene-code') || '').trim(),
          actionDifficulty: String(this.getAttribute('data-home-focus-difficulty') || '').trim(),
        };
        applyHomeFocusActionPrefill(focus);
        if (focus.actionPage) navigateTo(focus.actionPage);
      });
    }
    return;
  }
  var cycleId = localStorage.getItem('training_cycle_id') || '';
  var taskGroups = normalizeMyTaskGroups(null);
  var growthOverview = null;
  var cycleProgress = null;

  try {
    taskGroups = await fetchMyTasks();
  } catch (e) {}

  if (role === 'trainee') {
    try {
      var growthRes = await apiFetch('/api/growth/overview', { method: 'GET' });
      growthOverview = growthRes && growthRes.data ? growthRes.data : null;
    } catch (e) {}

    if (cycleId) {
      try {
        var cycleRes = await apiFetch('/api/training-cycle/progress', { method: 'GET' });
        cycleProgress = cycleRes && Number(cycleRes.code) === 200 ? (cycleRes.data || null) : null;
      } catch (e) {}
    }
  }

  var pendingTasks = flattenPendingTaskGroups(taskGroups);
  var focus = {
    eyebrow: '今日概览',
    title: role === 'admin' || role === 'store_manager' ? '今天先看什么' : '今天先做什么',
    desc: role === 'admin' || role === 'store_manager'
      ? '优先查看结果和任务，再决定今天的训练投入'
      : '当前没有待处理考试，可以继续训练并回看最近学习趋势',
    actionLabel: role === 'admin' || role === 'store_manager' ? '查看结果' : '查看成长计划',
    actionPage: role === 'admin' || role === 'store_manager' ? 'competition' : 'growth_plan',
    chips: role === 'admin' || role === 'store_manager'
      ? ['结果', '任务']
      : ['训练', '进度']
  };

  if (pendingTasks.length) {
    var hasRetakeTask = Array.isArray(taskGroups.retake) && taskGroups.retake.length > 0;
    var priorityTask = hasRetakeTask ? taskGroups.retake[0] : pendingTasks[0];
    focus = {
      eyebrow: '今日概览',
      title: '优先处理事项',
      desc: hasRetakeTask
        ? ('当前有 ' + pendingTasks.length + ' 项考试任务，其中包含补考，建议先处理补考，其余任务统一在下方查看')
        : ('当前有 ' + pendingTasks.length + ' 项考试任务，建议按顺序完成，再回看下方状态与趋势'),
      actionLabel: hasRetakeTask ? '处理首项补考' : '处理首项待办',
      actionPage: 'assessment',
      actionTaskId: priorityTask && priorityTask.id != null ? String(priorityTask.id) : '',
      chips: [
        '待办 ' + pendingTasks.length + ' 项',
        hasRetakeTask ? '补考优先' : '按顺序处理'
      ]
    };
  } else if (growthOverview && growthOverview.has_plan && growthOverview.replan_due) {
    var planCycleDays = Number((growthOverview.plan_meta && growthOverview.plan_meta.plan_cycle_days) || (growthOverview.plan && growthOverview.plan.plan_cycle_days) || 0);
    focus = {
      eyebrow: '今日概览',
      title: '计划需要更新',
      desc: '成长计划已到 ' + planCycleDays + ' 天更新节点，建议今天完成新一轮计划生成并继续训练',
      actionLabel: '更新计划',
      actionPage: 'growth_plan',
      chips: ['成长计划', '今日可更新']
    };
  } else if (cycleProgress && cycleProgress.cycle) {
    var cycle = cycleProgress.cycle;
    var pct = Number(cycleProgress.overall_progress || 0);
    var dayTitles = ['基础学习', '技能练习', '强化训练', '综合检验', '进阶训练', '深度强化', '最终冲刺'];
    var dayTitle = dayTitles[Number(cycle.current_day || 0) - 1] || ('Day ' + cycle.current_day);
    focus = {
      eyebrow: '今日概览',
      title: '训练继续推进',
      desc: '当前训练进度 ' + pct + '%，今日阶段为“' + dayTitle + '”，建议先完成训练，再回看结果与趋势',
      actionLabel: '继续训练',
      actionPage: 'growth_plan',
      chips: ['第 ' + cycle.current_day + ' 天', '进度 ' + pct + '%']
    };
  }

  containerEl.innerHTML =
    '<div class="home-lx-focus-card">' +
      '<div class="home-lx-focus-card__content">' +
        '<div class="home-lx-focus-card__eyebrow">' + escapeHtml(focus.eyebrow) + '</div>' +
        '<h2 class="home-lx-focus-card__title">' + escapeHtml(focus.title) + '</h2>' +
        '<p class="home-lx-focus-card__desc">' + escapeHtml(focus.desc) + '</p>' +
        '<div class="home-lx-focus-card__chips">' +
          focus.chips.map(function (chip) {
            return '<span class="home-lx-focus-card__chip">' + escapeHtml(chip) + '</span>';
          }).join('') +
        '</div>' +
      '</div>' +
      '<div class="home-lx-focus-card__actions">' +
        '<button type="button" class="home-lx-button home-lx-button--primary" data-home-focus-page="' + escapeHtml(focus.actionPage) + '" data-home-focus-task-id="' + escapeHtml(focus.actionTaskId || '') + '">' + escapeHtml(focus.actionLabel) + '</button>' +
      '</div>' +
    '</div>';

  var focusBtn = containerEl.querySelector('[data-home-focus-page]');
  if (focusBtn) {
    focusBtn.addEventListener('click', function () {
      var page = String(this.getAttribute('data-home-focus-page') || '').trim();
      var taskId = String(this.getAttribute('data-home-focus-task-id') || '').trim();
      applyHomeFocusActionPrefill({
        actionPage: page,
        actionQuestion: String(this.getAttribute('data-home-focus-question') || '').trim(),
        actionAssistantInput: String(this.getAttribute('data-home-focus-assistant-input') || '').trim(),
        actionModuleCode: String(this.getAttribute('data-home-focus-module-code') || '').trim(),
        actionSceneCode: String(this.getAttribute('data-home-focus-scene-code') || '').trim(),
        actionDifficulty: String(this.getAttribute('data-home-focus-difficulty') || '').trim(),
      });
      if (page === 'assessment' && taskId) {
        selectAssessmentTask(taskId);
      }
      if (page) navigateTo(page);
    });
  }
}

function syncHomeStatusAuxGrid() {
  var grid = document.querySelector('.home-lx-workflow-grid__secondary');
  if (!grid) return;
  var trainingEl = document.getElementById('home-training-cycle');
  var replanEl = document.getElementById('home-growth-replan');
  var latestResultEl = document.getElementById('home-latest-result');
  var hasTraining = !!(trainingEl && String(trainingEl.innerHTML || '').trim());
  var hasReplan = !!(replanEl && String(replanEl.innerHTML || '').trim());
  var hasLatestResult = !!(latestResultEl && String(latestResultEl.innerHTML || '').trim());
  grid.style.display = hasTraining || hasReplan || hasLatestResult ? 'grid' : 'none';
}

async function renderHomeTrainingCycleCard(containerEl) {
  if (!containerEl) return;
  var role = localStorage.getItem('role') || '';
  var cycleId = localStorage.getItem('training_cycle_id') || '';
  if (role !== 'trainee' || !cycleId) {
    containerEl.innerHTML = '';
    return;
  }
  try {
    var j = await apiFetch('/api/training-cycle/progress');
    if (!j || Number(j.code) !== 200 || !j.data || !j.data.cycle) {
      containerEl.innerHTML = '';
      return;
    }
    var data = j.data;
    var cycle = data.cycle;
    var pct = data.overall_progress || 0;
    var dayTitles = ['基础学习','技能练习','强化训练','综合检验','进阶训练','深度强化','最终冲刺'];
    var dayTitle = dayTitles[cycle.current_day - 1] || ('Day ' + cycle.current_day);

    var html = '<div class="home-lx-note-card home-lx-note-card--accent">';
    html += '<div class="home-lx-note-card__head">';
    html += '<div>';
    html += '<p class="home-lx-note-card__eyebrow">训练进度</p>';
    html += '<h3 class="home-lx-note-card__title">第 ' + cycle.current_day + ' 天 / 共 ' + cycle.total_days + ' 天</h3>';
    html += '</div>';
    html += '<button class="home-lx-button home-lx-button--soft" onclick="navigateTo(\'growth_plan\')">继续</button>';
    html += '</div>';
    html += '<p class="home-lx-note-card__desc">当前处于' + escapeHtml(dayTitle) + '，整体进度 ' + escapeHtml(String(pct)) + '%</p>';
    html += '<div class="home-lx-progress">';
    html += '<div class="home-lx-progress__bar" style="width:' + pct + '%"></div>';
    html += '</div>';
    html += '</div>';
    containerEl.innerHTML = html;
  } catch (e) {
    containerEl.innerHTML = '';
  }
}

async function renderHomeGrowthReplanCard(containerEl) {
  if (!containerEl) return;
  var role = normalizeRole(localStorage.getItem('role') || '');
  if (role !== 'trainee') {
    containerEl.innerHTML = '';
    return;
  }
  try {
    var res = await apiFetch('/api/growth/overview', { method: 'GET' });
    var data = res && res.data ? res.data : null;
    if (!data || !data.has_plan) {
      containerEl.innerHTML = '';
      return;
    }
    var planCycleDays = Number((data.plan_meta && data.plan_meta.plan_cycle_days) || (data.plan && data.plan.plan_cycle_days) || 0);
    var daysUntilReplan = Number(data.days_until_replan || 0);
    var replanDue = !!data.replan_due;
    var badgeClass = replanDue
      ? 'home-lx-note-card__status home-lx-note-card__status--ready'
      : 'home-lx-note-card__status home-lx-note-card__status--waiting';
    var badgeText = replanDue ? '今日可更新' : ('剩余 ' + daysUntilReplan + ' 天');
    var title = replanDue ? '成长计划更新' : '成长计划倒计时';
    var desc = replanDue
      ? ('当前已到 ' + planCycleDays + ' 天更新节点，可以重新生成成长计划并继续下一轮训练')
      : ('当前为 ' + planCycleDays + ' 天更新周期，到期后可重新生成成长计划并继续下一轮训练');
    var actionLabel = replanDue ? '立即更新' : '查看计划';

    containerEl.innerHTML =
      '<div class="home-lx-note-card">' +
        '<div class="home-lx-note-card__head">' +
          '<div>' +
            '<div class="' + badgeClass + '">' + escapeHtml(badgeText) + '</div>' +
            '<h3 class="home-lx-note-card__title home-lx-note-card__title--spaced">' + escapeHtml(title) + '</h3>' +
          '</div>' +
          '<button type="button" class="home-lx-button home-lx-button--secondary" onclick="navigateTo(\'growth_plan\')">' + escapeHtml(actionLabel) + '</button>' +
        '</div>' +
        '<p class="home-lx-note-card__desc">' + escapeHtml(desc) + '</p>' +
      '</div>';
  } catch (e) {
    containerEl.innerHTML = '';
  }
}

async function renderHomeTodoList(containerElement) {
  if (!containerElement) return;
  moduleState.homeTodo = moduleState.homeTodo || {};

  function formatTaskDeadline(value) {
    if (!value) return '未设置截止时间';
    var date = new Date(value);
    if (isNaN(date.getTime())) return escapeHtml(String(value));
    try {
      return new Intl.DateTimeFormat('zh-CN', {
        year: 'numeric',
        month: '2-digit',
        day: '2-digit',
        hour: '2-digit',
        minute: '2-digit',
      }).format(date);
    } catch (e) {
      return escapeHtml(String(value));
    }
  }

  function buildTaskCard(task, index, userStatus) {
    var taskName = escapeHtml(task && task.task_name ? task.task_name : '未命名任务');
    var deadline = formatTaskDeadline(task && task.deadline);
    var passScore = Number(task && task.pass_score != null ? task.pass_score : 0).toFixed(1);
    var taskId = escapeHtml(String(task && task.id != null ? task.id : ''));
    var isRetake = userStatus === 'retake';
    var statusClass = isRetake
      ? 'home-lx-task-card__status home-lx-task-card__status--retake'
      : 'home-lx-task-card__status home-lx-task-card__status--todo';
    var statusLabel = isRetake ? '待补考' : '待考试';
    var actionText = isRetake ? '立即补考' : '立即去考试';
    var actionClass = isRetake
      ? 'home-lx-button home-lx-button--warning'
      : 'home-lx-button home-lx-button--primary';
    var failTagHtml = isRetake
      ? '<span class="home-lx-task-card__tag home-lx-task-card__tag--danger">未通过</span>'
      : '';

    return (
      '<div class="home-lx-task-card ' + (isRetake ? 'home-lx-task-card--retake' : '') + '">' +
        '<div class="home-lx-task-card__layout">' +
          '<div class="home-lx-task-card__body">' +
            '<div class="home-lx-task-card__badges">' +
              '<span class="' + statusClass + '">' + statusLabel + '</span>' +
              failTagHtml +
              '<span class="home-lx-task-card__order">#' + escapeHtml(String(index + 1)) + '</span>' +
            '</div>' +
            '<h4 class="home-lx-task-card__title">' + taskName + '</h4>' +
            '<div class="home-lx-task-card__meta">' +
              '<span class="home-lx-task-card__meta-pill">截止时间：' + deadline + '</span>' +
              '<span class="home-lx-task-card__meta-pill">及格分：' + escapeHtml(passScore) + '</span>' +
            '</div>' +
          '</div>' +
          '<div class="home-lx-task-card__actions">' +
            '<button type="button" class="' + actionClass + '" data-task-exam-btn data-task-id="' + taskId + '">' +
              actionText +
            '</button>' +
          '</div>' +
        '</div>' +
      '</div>'
    );
  }

  function buildCompletedCard(task, index) {
    var taskName = escapeHtml(task && task.task_name ? task.task_name : '未命名任务');
    var deadline = formatTaskDeadline(task && task.deadline);
    var passScore = Number(task && task.pass_score != null ? task.pass_score : 0).toFixed(1);

    return (
      '<div class="home-lx-task-card home-lx-task-card--completed">' +
        '<div class="home-lx-task-card__layout">' +
          '<div class="home-lx-task-card__body">' +
            '<div class="home-lx-task-card__badges">' +
              '<span class="home-lx-task-card__status home-lx-task-card__status--done">已完成</span>' +
              '<span class="home-lx-task-card__order">#' + escapeHtml(String(index + 1)) + '</span>' +
            '</div>' +
            '<h4 class="home-lx-task-card__title">' + taskName + '</h4>' +
            '<div class="home-lx-task-card__meta">' +
              '<span class="home-lx-task-card__meta-pill">截止时间：' + deadline + '</span>' +
              '<span class="home-lx-task-card__meta-pill">及格分：' + escapeHtml(passScore) + '</span>' +
            '</div>' +
          '</div>' +
          '<div class="home-lx-task-card__actions">' +
            '<button type="button" disabled class="home-lx-button home-lx-button--disabled">' +
              '已通关' +
            '</button>' +
          '</div>' +
        '</div>' +
      '</div>'
    );
  }

  containerElement.innerHTML =
    '<div class="home-lx-todo-card">' +
      '<div class="home-lx-todo-card__head">' +
        '<div>' +
          '<div class="home-lx-todo-card__eyebrow">待办</div>' +
          '<h3 class="home-lx-todo-card__title">考试任务</h3>' +
        '</div>' +
        '<div data-home-todo-status class="home-lx-status home-lx-status--idle">加载中</div>' +
      '</div>' +
      '<div class="home-lx-todo-card__body" data-home-todo-body></div>' +
    '</div>';

  var bodyEl = containerElement.querySelector('[data-home-todo-body]');
  var statusEl = containerElement.querySelector('[data-home-todo-status]');
  if (!bodyEl) return;

  bodyEl.innerHTML =
    '<div class="home-lx-empty-block">正在加载待办任务...</div>';

  var taskGroups = await fetchMyTasks();
  var todoTasks = taskGroups.todo || [];
  var retakeTasks = taskGroups.retake || [];
  var completedTasks = taskGroups.completed || [];
  var pendingTasks = todoTasks.concat(retakeTasks);

  if (statusEl) {
    if (pendingTasks.length) {
      statusEl.textContent = '待办 ' + pendingTasks.length + ' 项';
      statusEl.className = 'home-lx-status home-lx-status--pending';
    } else if (completedTasks.length) {
      statusEl.textContent = '暂无待办';
      statusEl.className = 'home-lx-status home-lx-status--done';
    } else {
      statusEl.textContent = '暂无考试';
      statusEl.className = 'home-lx-status home-lx-status--idle';
    }
  }

  if (!pendingTasks.length && !completedTasks.length) {
    bodyEl.innerHTML = '<div class="home-lx-empty-block">当前没有待办事项，首页会在有考试或训练动作时自动更新</div>';
    return;
  }

  var priorityTask = retakeTasks[0] || todoTasks[0] || completedTasks[0] || null;
  var summaryCountText = pendingTasks.length
    ? ('待办 ' + pendingTasks.length + ' 项')
    : (completedTasks.length ? '待办已清空' : '暂无考试');
  var summaryLeadText = priorityTask && priorityTask.task_name
    ? String(priorityTask.task_name)
    : (pendingTasks.length ? '当前有新的考试任务' : '当前没有待办考试');
  var summaryMetaText = pendingTasks.length
    ? (
      retakeTasks.length
        ? ('含 ' + retakeTasks.length + ' 项补考，建议优先处理')
        : ('最近截止 ' + formatTaskDeadline(priorityTask && priorityTask.deadline))
    )
    : (completedTasks.length ? ('最近已完成 ' + completedTasks.length + ' 项考试') : '等待系统同步考试任务');
  var summaryToneClass = pendingTasks.length
    ? (retakeTasks.length ? ' home-lx-todo-fold__signal--danger' : ' home-lx-todo-fold__signal--active')
    : ' home-lx-todo-fold__signal--calm';
  var shouldOpen = typeof moduleState.homeTodo.expanded === 'boolean'
    ? moduleState.homeTodo.expanded
    : pendingTasks.length === 1;
  var completedPreview = completedTasks.slice(0, 2);
  var cardsHtml = '';
  cardsHtml +=
    '<details class="home-lx-todo-fold"' + (shouldOpen ? ' open' : '') + '>' +
      '<summary class="home-lx-todo-fold__summary">' +
        '<div class="home-lx-todo-fold__main">' +
          '<div class="home-lx-todo-fold__signal' + summaryToneClass + '">' +
            '<span class="home-lx-todo-fold__dot"></span>' +
            '<span>' + escapeHtml(summaryCountText) + '</span>' +
          '</div>' +
          '<div class="home-lx-todo-fold__copy">' +
            '<div class="home-lx-todo-fold__lead">' + escapeHtml(summaryLeadText) + '</div>' +
            '<div class="home-lx-todo-fold__meta">' + escapeHtml(summaryMetaText) + '</div>' +
          '</div>' +
        '</div>' +
        '<span class="home-lx-todo-fold__chevron" aria-hidden="true"></span>' +
      '</summary>' +
      '<div class="home-lx-todo-fold__panel">';

  if (pendingTasks.length) {
    cardsHtml += '<div class="home-lx-task-list">';
    cardsHtml += todoTasks.map(function (task, index) {
      return buildTaskCard(task, index, 'todo');
    }).join('');
    cardsHtml += retakeTasks.map(function (task, index) {
      return buildTaskCard(task, todoTasks.length + index, 'retake');
    }).join('');
    cardsHtml += '</div>';
  } else {
    cardsHtml +=
      '<div class="home-lx-empty-block home-lx-empty-block--soft">' +
        '<div class="home-lx-empty-block__title">当前没有待考试或待补考任务</div>' +
        '<div class="home-lx-empty-block__meta">已完成记录已收纳在下方轻区块</div>' +
      '</div>';
  }

  if (completedTasks.length) {
    cardsHtml +=
      '<section class="home-lx-todo-secondary">' +
        '<div class="home-lx-todo-secondary__head">' +
          '<div class="home-lx-todo-secondary__title">最近完成</div>' +
          '<div class="home-lx-todo-secondary__count">' + escapeHtml(String(completedTasks.length)) + ' 项</div>' +
        '</div>' +
        '<div class="home-lx-task-list home-lx-task-list--completed">' +
          completedPreview.map(function (task, index) {
            return buildCompletedCard(task, index);
          }).join('') +
        '</div>' +
        (completedTasks.length > completedPreview.length
          ? '<div class="home-lx-todo-secondary__hint">仅展示最近 ' + escapeHtml(String(completedPreview.length)) + ' 项</div>'
          : '') +
      '</section>';
  }

  cardsHtml +=
      '</div>' +
    '</details>';

  bodyEl.innerHTML = cardsHtml;

  var foldEl = bodyEl.querySelector('.home-lx-todo-fold');
  if (foldEl) {
    foldEl.addEventListener('toggle', function () {
      moduleState.homeTodo.expanded = foldEl.open;
    });
  }

  bodyEl.querySelectorAll('[data-task-exam-btn]').forEach(function (btn) {
    btn.addEventListener('click', function () {
      var taskId = String(this.getAttribute('data-task-id') || '').trim();
      selectAssessmentTask(taskId);
      navigateTo('assessment');
    });
  });
}

function renderHomeDashboardEntry(containerElement) {
  if (!containerElement) return;
  containerElement.innerHTML =
    '<button type="button" id="home-dashboard-entry-btn" class="home-lx-result-card">' +
      '<div class="home-lx-result-card__layout">' +
        '<div class="home-lx-result-card__body">' +
          '<div class="home-lx-result-card__eyebrow">结果</div>' +
          '<h3 class="home-lx-result-card__title">奖金与门店月榜</h3>' +
          '<p class="home-lx-result-card__desc">查看竞赛总分、资格状态和月榜结果，快速判断训练是否转化为门店表现</p>' +
          '<div class="home-lx-result-card__tags">' +
            '<span class="home-lx-result-card__tag">奖金</span>' +
            '<span class="home-lx-result-card__tag">月榜</span>' +
          '</div>' +
        '</div>' +
        '<span class="home-lx-button home-lx-button--secondary">进入</span>' +
      '</div>' +
    '</button>';

  var entryBtn = document.getElementById('home-dashboard-entry-btn');
  if (entryBtn) {
    entryBtn.addEventListener('click', function () {
      navigateTo('competition');
    });
  }
}

function homeBiState() {
  moduleState.homeBi = moduleState.homeBi || {};
  if (typeof moduleState.homeBi.selectedStoreId !== 'string') moduleState.homeBi.selectedStoreId = '';
  if (!Object.prototype.hasOwnProperty.call(moduleState.homeBi, 'data')) moduleState.homeBi.data = null;
  if (typeof moduleState.homeBi.error !== 'string') moduleState.homeBi.error = '';
  if (typeof moduleState.homeBi.loading !== 'boolean') moduleState.homeBi.loading = false;
  return moduleState.homeBi;
}

function homeBiFormatNumber(value) {
  var num = Number(value);
  if (!isFinite(num)) return '--';
  if (Math.abs(num) >= 10000) return (num / 10000).toFixed(1) + 'w';
  return String(Math.round(num * 10) / 10).replace(/\.0$/, '');
}

function homeBiFormatPercent(value) {
  var num = Number(value);
  if (!isFinite(num)) return '--';
  return (Math.round(num * 10) / 10).toFixed(1).replace(/\.0$/, '') + '%';
}

function homeBiFormatScore(value) {
  var num = Number(value);
  if (!isFinite(num)) return '--';
  return (Math.round(num * 10) / 10).toFixed(1).replace(/\.0$/, '');
}

function homeBiDisplayValue(value, emptyText) {
  var text = String(value == null ? '' : value).trim();
  if (!text || text === '--') return emptyText || '待同步';
  return text;
}

function homeBiFormatDateTime(value) {
  if (!value) return '刚刚更新';
  var date = new Date(value);
  if (isNaN(date.getTime())) return String(value);
  try {
    return new Intl.DateTimeFormat('zh-CN', {
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
    }).format(date);
  } catch (e) {
    return String(value);
  }
}

function homeBiRiskToneClass(highRiskCount) {
  var count = Number(highRiskCount || 0);
  if (count > 0) return 'home-bi-status home-bi-status--warn';
  return 'home-bi-status home-bi-status--ok';
}

function homeBiRankBadge(rank) {
  var num = Number(rank || 0);
  if (!num) return '--';
  return num < 10 ? ('0' + num) : String(num);
}

function renderHomeBiNotice(key, loadingText) {
  var loading = requestLoading(key);
  var err = requestError(key);
  if (loading) {
    return '<div class="home-bi-inline-note" role="status">' +
      '<span class="demo-spinner" aria-hidden="true"></span>' +
      '<span>' + escapeHtml(loadingText || '数据同步中…') + '</span>' +
    '</div>';
  }
  if (err) {
    return '<div class="home-bi-inline-note home-bi-inline-note--error" role="status">' +
      '<span class="home-bi-inline-note__text" title="' + escapeHtml(err) + '">首页数据暂未同步，已降级显示当前视图</span>' +
      '<button type="button" class="home-bi-inline-note__action" onclick="loadManagementHomeBi(true)">重试</button>' +
    '</div>';
  }
  return '';
}

function renderHomeBiSparkline(containerEl, weeklyTrend) {
  if (!containerEl) return;
  var points = Array.isArray(weeklyTrend) ? weeklyTrend : [];
  if (!points.length) {
    containerEl.innerHTML = '<div class="home-bi-empty">近 7 天暂无训练记录</div>';
    return;
  }
  var maxVal = 0;
  for (var i = 0; i < points.length; i++) {
    maxVal = Math.max(maxVal, Number(points[i] && points[i].count || 0));
  }
  maxVal = Math.max(maxVal, 1);
  var bars = '';
  for (var j = 0; j < points.length; j++) {
    var item = points[j] || {};
    var count = Number(item.count || 0);
    var height = Math.max(10, Math.round((count / maxVal) * 100));
    bars += '<div class="home-bi-spark__item">' +
      '<div class="home-bi-spark__bar-wrap"><span class="home-bi-spark__bar" style="height:' + escapeHtml(String(height)) + '%"></span></div>' +
      '<div class="home-bi-spark__label">' + escapeHtml(String(item.day || '')) + '</div>' +
      '<div class="home-bi-spark__value">' + escapeHtml(homeBiFormatNumber(count)) + '</div>' +
    '</div>';
  }
  containerEl.innerHTML = '<div class="home-bi-spark">' + bars + '</div>';
}

async function renderHomeEmployeeLatestResultCard(containerEl) {
  if (!containerEl) return;
  containerEl.innerHTML =
    '<div class="home-lx-note-card">' +
      '<div class="home-lx-note-card__head">' +
        '<div>' +
          '<p class="home-lx-note-card__eyebrow">最近结果</p>' +
          '<h3 class="home-lx-note-card__title">正在同步最近考试结果</h3>' +
        '</div>' +
      '</div>' +
      '<p class="home-lx-note-card__desc">稍后会显示最近一次考试的状态与成绩</p>' +
    '</div>';
  try {
    var items = await fetchAssessmentHistory();
    var latest = Array.isArray(items) && items.length ? items[0] : null;
    if (!latest) {
      containerEl.innerHTML =
        '<div class="home-lx-note-card">' +
          '<div class="home-lx-note-card__head">' +
            '<div>' +
              '<p class="home-lx-note-card__eyebrow">最近结果</p>' +
              '<h3 class="home-lx-note-card__title">还没有考试记录</h3>' +
            '</div>' +
            '<button type="button" class="home-lx-button home-lx-button--secondary" onclick="navigateTo(\'assessment\')">查看考试</button>' +
          '</div>' +
          '<p class="home-lx-note-card__desc">当有考试完成后，首页会自动显示最近一次结果摘要</p>' +
        '</div>';
      return;
    }
    var passed = Number(latest.is_pass || 0) === 1;
    var scoreVisible = latest.is_score_visible_to_user !== false && latest.score != null;
    var badgeClass = passed ? 'home-lx-note-card__status home-lx-note-card__status--ready' : 'home-lx-note-card__status home-lx-task-card__status--retake';
    var badgeText = passed ? '已通过' : '待复盘';
    var scoreText = scoreVisible ? (homeBiFormatScore(latest.score) + ' 分') : '成绩待公布';
    containerEl.innerHTML =
      '<div class="home-lx-note-card">' +
        '<div class="home-lx-note-card__head">' +
          '<div>' +
            '<div class="' + badgeClass + '">' + escapeHtml(badgeText) + '</div>' +
            '<h3 class="home-lx-note-card__title home-lx-note-card__title--spaced">' + escapeHtml(String(latest.task_name || '未命名考试')) + '</h3>' +
          '</div>' +
          '<button type="button" class="home-lx-button home-lx-button--secondary" onclick="navigateTo(\'assessment\')">查看记录</button>' +
        '</div>' +
        '<p class="home-lx-note-card__desc">最近一次结果：' + escapeHtml(scoreText) + ' · 完成于 ' + escapeHtml(examCenterFormatDateTime(latest.finished_at)) + '</p>' +
      '</div>';
  } catch (e) {
    containerEl.innerHTML =
      '<div class="home-lx-note-card">' +
        '<div class="home-lx-note-card__head">' +
          '<div>' +
            '<p class="home-lx-note-card__eyebrow">最近结果</p>' +
            '<h3 class="home-lx-note-card__title">结果同步失败</h3>' +
          '</div>' +
        '</div>' +
        '<p class="home-lx-note-card__desc">考试历史暂时不可用，请稍后重试</p>' +
      '</div>';
  }
}

