function createTaskPaperQuestion(type, index) {
  var seq = Number(index || 0) + 1;
  var baseId = 'q' + seq + '_' + Date.now();
  if (type === 'single') {
    return {
      id: baseId,
      type: 'single',
      title: '新单选题',
      score: 10,
      options: [
        { value: 'A', label: '选项 A' },
        { value: 'B', label: '选项 B' },
        { value: 'C', label: '选项 C' },
        { value: 'D', label: '选项 D' }
      ],
      answer: 'A'
    };
  }
  if (type === 'multiple') {
    return {
      id: baseId,
      type: 'multiple',
      title: '新多选题',
      score: 15,
      options: [
        { value: 'A', label: '选项 A' },
        { value: 'B', label: '选项 B' },
        { value: 'C', label: '选项 C' },
        { value: 'D', label: '选项 D' }
      ],
      answer: ['A', 'B']
    };
  }
  if (type === 'judge') {
    return {
      id: baseId,
      type: 'judge',
      title: '新判断题',
      score: 10,
      options: [
        { value: 'T', label: '正确' },
        { value: 'F', label: '错误' }
      ],
      answer: 'T'
    };
  }
  if (type === 'short') {
    return {
      id: baseId,
      type: 'short',
      title: '新简答题',
      score: 15,
      keywords: ['需求', '价值'],
      placeholder: '简答...'
    };
  }
  return {
    id: baseId,
    type: 'essay',
    title: '新大题',
    score: 25,
    keywords: ['需求', '预算', '价值'],
    placeholder: '请输入完整作答...'
  };
}

function taskPaperTypeLabel(type) {
  var normalized = String(type || '').trim();
  if (normalized === 'single') return '单选题';
  if (normalized === 'multiple') return '多选题';
  if (normalized === 'judge') return '判断题';
  if (normalized === 'short') return '简答题';
  if (normalized === 'essay') return '大题';
  return '题目';
}

function ensureTaskPaperEditorState(rawConfigText) {
  var state = moduleState.taskCenter = moduleState.taskCenter || {};
  if (state.paperEditor) return state.paperEditor;
  var seed = String(rawConfigText || '').trim();
  if (seed) {
    try {
      var parsed = JSON.parse(seed);
      if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
        state.paperEditor = parsed;
      } else if (Array.isArray(parsed)) {
        state.paperEditor = { exam_title: '考试试卷', instructions: '', questions: parsed };
      }
    } catch (error) {}
  }
  if (!state.paperEditor) {
    state.paperEditor = getDefaultTaskPaperConfigObject();
  }
  if (!Array.isArray(state.paperEditor.questions)) state.paperEditor.questions = [];
  return state.paperEditor;
}

function syncTaskPaperEditorTextarea() {
  var textarea = document.getElementById('task-paper-config-input');
  var editor = ensureTaskPaperEditorState();
  if (textarea) {
    textarea.value = JSON.stringify(editor, null, 2);
  }
}

function renderTaskPaperEditor() {
  var wrap = document.getElementById('task-paper-editor');
  if (!wrap) return;
  var editor = ensureTaskPaperEditorState();
  var questions = Array.isArray(editor.questions) ? editor.questions : [];

  function renderQuestionCard(q, index) {
    var questionId = escapeHtml(String(q && q.id || ('q' + (index + 1))));
    var type = String(q && q.type || 'single');
    var title = escapeHtml(String(q && q.title || ''));
    var score = escapeHtml(String(Number(q && q.score != null ? q.score : 10)));
    var options = Array.isArray(q && q.options) ? q.options : [];
    var answerText = Array.isArray(q && q.answer) ? q.answer.join(', ') : String(q && q.answer || '');
    var keywordsText = Array.isArray(q && q.keywords) ? q.keywords.join(', ') : '';
    var placeholderText = escapeHtml(String(q && q.placeholder || ''));
    var optionBlock = '';

    if (type === 'single' || type === 'multiple' || type === 'judge') {
      optionBlock =
        '<div class="mt-4 grid gap-3 md:grid-cols-2">' +
          options.map(function (opt, optIndex) {
            return '<label class="block">' +
              '<span class="mb-2 block text-xs font-medium text-slate-500">选项 ' + escapeHtml(String(opt && opt.value || String.fromCharCode(65 + optIndex))) + '</span>' +
              '<input type="text" data-paper-option="' + escapeHtml(String(optIndex)) + '" data-paper-index="' + escapeHtml(String(index)) + '" value="' + escapeHtml(String(opt && opt.label || '')) + '" class="w-full rounded-xl border border-slate-200 bg-white px-3 py-2.5 text-sm text-slate-900 outline-none transition focus:border-slate-400 focus:ring-4 focus:ring-slate-100" />' +
            '</label>';
          }).join('') +
        '</div>' +
        '<label class="mt-4 block">' +
          '<span class="mb-2 block text-xs font-medium text-slate-500">标准答案</span>' +
          '<input type="text" data-paper-field="answer" data-paper-index="' + escapeHtml(String(index)) + '" value="' + escapeHtml(answerText) + '" placeholder="' + (type === 'multiple' ? '如：A, C' : '如：A') + '" class="w-full rounded-xl border border-slate-200 bg-white px-3 py-2.5 text-sm text-slate-900 outline-none transition focus:border-slate-400 focus:ring-4 focus:ring-slate-100" />' +
        '</label>';
    } else {
      optionBlock =
        '<label class="mt-4 block">' +
          '<span class="mb-2 block text-xs font-medium text-slate-500">关键词</span>' +
          '<input type="text" data-paper-field="keywords" data-paper-index="' + escapeHtml(String(index)) + '" value="' + escapeHtml(keywordsText) + '" placeholder="多个关键词用逗号分隔" class="w-full rounded-xl border border-slate-200 bg-white px-3 py-2.5 text-sm text-slate-900 outline-none transition focus:border-slate-400 focus:ring-4 focus:ring-slate-100" />' +
        '</label>' +
        '<label class="mt-4 block">' +
          '<span class="mb-2 block text-xs font-medium text-slate-500">作答占位提示</span>' +
          '<textarea data-paper-field="placeholder" data-paper-index="' + escapeHtml(String(index)) + '" rows="3" class="w-full rounded-xl border border-slate-200 bg-white px-3 py-2.5 text-sm leading-6 text-slate-900 outline-none transition focus:border-slate-400 focus:ring-4 focus:ring-slate-100">' + placeholderText + '</textarea>' +
        '</label>';
    }

    return (
      '<div class="rounded-[22px] border border-slate-200 bg-white p-4 shadow-[0_8px_22px_rgba(15,23,42,0.03)]">' +
        '<div class="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">' +
          '<div class="flex items-center gap-2">' +
            '<span class="inline-flex rounded-full border border-slate-200 bg-slate-50 px-3 py-1 text-[11px] font-semibold text-slate-500">' + escapeHtml(taskPaperTypeLabel(type)) + '</span>' +
            '<span class="text-xs text-slate-400">题目 ' + escapeHtml(String(index + 1)) + '</span>' +
            '<span class="text-xs text-slate-400">ID: ' + questionId + '</span>' +
          '</div>' +
          '<button type="button" data-paper-remove="' + escapeHtml(String(index)) + '" class="inline-flex items-center justify-center rounded-xl border border-slate-200 bg-white px-3 py-2 text-xs font-semibold text-slate-600 transition hover:border-slate-300 hover:bg-slate-50">删除题目</button>' +
        '</div>' +
        '<div class="mt-4 grid gap-3 md:grid-cols-[minmax(0,1fr)_128px]">' +
          '<label class="block">' +
            '<span class="mb-2 block text-xs font-medium text-slate-500">题干</span>' +
            '<input type="text" data-paper-field="title" data-paper-index="' + escapeHtml(String(index)) + '" value="' + title + '" class="w-full rounded-xl border border-slate-200 bg-white px-3 py-2.5 text-sm text-slate-900 outline-none transition focus:border-slate-400 focus:ring-4 focus:ring-slate-100" />' +
          '</label>' +
          '<label class="block">' +
            '<span class="mb-2 block text-xs font-medium text-slate-500">分值</span>' +
            '<input type="number" min="1" step="1" data-paper-field="score" data-paper-index="' + escapeHtml(String(index)) + '" value="' + score + '" class="w-full rounded-xl border border-slate-200 bg-white px-3 py-2.5 text-sm text-slate-900 outline-none transition focus:border-slate-400 focus:ring-4 focus:ring-slate-100" />' +
          '</label>' +
        '</div>' +
        optionBlock +
      '</div>'
    );
  }

  wrap.innerHTML =
    '<div class="rounded-[22px] border border-slate-200 bg-white p-4">' +
      '<div class="grid gap-4 md:grid-cols-2">' +
        '<label class="block">' +
          '<span class="mb-2 block text-sm font-medium text-slate-700">试卷标题</span>' +
          '<input type="text" id="task-paper-exam-title" value="' + escapeHtml(String(editor.exam_title || '')) + '" class="w-full rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm text-slate-900 outline-none transition focus:border-slate-400 focus:ring-4 focus:ring-slate-100" />' +
        '</label>' +
        '<label class="block">' +
          '<span class="mb-2 block text-sm font-medium text-slate-700">考试说明</span>' +
          '<input type="text" id="task-paper-exam-instructions" value="' + escapeHtml(String(editor.instructions || '')) + '" class="w-full rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm text-slate-900 outline-none transition focus:border-slate-400 focus:ring-4 focus:ring-slate-100" />' +
        '</label>' +
      '</div>' +
      '<div class="mt-4 flex flex-wrap gap-2">' +
        '<button type="button" data-paper-add="single" class="inline-flex items-center justify-center rounded-xl border border-slate-200 bg-white px-3 py-2 text-xs font-semibold text-slate-700 transition hover:border-slate-300 hover:bg-slate-50">+ 单选题</button>' +
        '<button type="button" data-paper-add="multiple" class="inline-flex items-center justify-center rounded-xl border border-slate-200 bg-white px-3 py-2 text-xs font-semibold text-slate-700 transition hover:border-slate-300 hover:bg-slate-50">+ 多选题</button>' +
        '<button type="button" data-paper-add="judge" class="inline-flex items-center justify-center rounded-xl border border-slate-200 bg-white px-3 py-2 text-xs font-semibold text-slate-700 transition hover:border-slate-300 hover:bg-slate-50">+ 判断题</button>' +
        '<button type="button" data-paper-add="short" class="inline-flex items-center justify-center rounded-xl border border-slate-200 bg-white px-3 py-2 text-xs font-semibold text-slate-700 transition hover:border-slate-300 hover:bg-slate-50">+ 简答题</button>' +
        '<button type="button" data-paper-add="essay" class="inline-flex items-center justify-center rounded-xl border border-slate-200 bg-white px-3 py-2 text-xs font-semibold text-slate-700 transition hover:border-slate-300 hover:bg-slate-50">+ 大题</button>' +
      '</div>' +
    '</div>' +
    '<div class="mt-4 space-y-4">' + questions.map(renderQuestionCard).join('') + '</div>';

  var titleInput = document.getElementById('task-paper-exam-title');
  var instructionsInput = document.getElementById('task-paper-exam-instructions');
  if (titleInput) {
    titleInput.addEventListener('input', function () {
      ensureTaskPaperEditorState().exam_title = this.value;
      syncTaskPaperEditorTextarea();
    });
  }
  if (instructionsInput) {
    instructionsInput.addEventListener('input', function () {
      ensureTaskPaperEditorState().instructions = this.value;
      syncTaskPaperEditorTextarea();
    });
  }

  wrap.querySelectorAll('[data-paper-add]').forEach(function (btn) {
    btn.addEventListener('click', function () {
      var type = String(this.getAttribute('data-paper-add') || 'single');
      var current = ensureTaskPaperEditorState();
      current.questions.push(createTaskPaperQuestion(type, current.questions.length));
      syncTaskPaperEditorTextarea();
      renderTaskPaperEditor();
    });
  });
  wrap.querySelectorAll('[data-paper-remove]').forEach(function (btn) {
    btn.addEventListener('click', function () {
      var index = Number(this.getAttribute('data-paper-remove'));
      var current = ensureTaskPaperEditorState();
      current.questions.splice(index, 1);
      syncTaskPaperEditorTextarea();
      renderTaskPaperEditor();
    });
  });
  wrap.querySelectorAll('[data-paper-field]').forEach(function (input) {
    input.addEventListener('input', function () {
      var index = Number(this.getAttribute('data-paper-index'));
      var field = String(this.getAttribute('data-paper-field') || '');
      var current = ensureTaskPaperEditorState();
      var q = current.questions[index];
      if (!q) return;
      if (field === 'score') {
        q[field] = Number(this.value || 0);
      } else if (field === 'keywords') {
        q[field] = String(this.value || '').split(',').map(function (item) { return item.trim(); }).filter(Boolean);
      } else if (field === 'answer' && q.type === 'multiple') {
        q[field] = String(this.value || '').split(',').map(function (item) { return item.trim(); }).filter(Boolean);
      } else {
        q[field] = this.value;
      }
      syncTaskPaperEditorTextarea();
    });
  });
  wrap.querySelectorAll('[data-paper-option]').forEach(function (input) {
    input.addEventListener('input', function () {
      var index = Number(this.getAttribute('data-paper-index'));
      var optionIndex = Number(this.getAttribute('data-paper-option'));
      var current = ensureTaskPaperEditorState();
      var q = current.questions[index];
      if (!q || !Array.isArray(q.options) || !q.options[optionIndex]) return;
      q.options[optionIndex].label = this.value;
      syncTaskPaperEditorTextarea();
    });
  });

  syncTaskPaperEditorTextarea();
}

async function renderTaskListPage(container) {
  if (!container) return;

  var currentStatus = String((moduleState.taskCenter && moduleState.taskCenter.status) || 'all');
  var statusOptions = [
    { value: 'all', label: '全部任务' },
    { value: 'published', label: '已发布' },
    { value: 'draft', label: '草稿' },
    { value: 'archived', label: '已归档' },
  ];

  function taskFilterLabel(status) {
    var matched = statusOptions.find(function (item) { return item.value === status; });
    return matched ? matched.label : '全部任务';
  }

  function taskFilterButtonClass(active, loading) {
    var base = 'task-list-filter-btn inline-flex items-center gap-2 rounded-full border px-4 py-2 text-sm font-medium transition';
    if (active) {
      return base + ' border-slate-900 bg-slate-900 text-white shadow-[0_10px_24px_rgba(15,23,42,0.18)]';
    }
    if (loading) {
      return base + ' border-slate-300 bg-slate-100 text-slate-500';
    }
    return base + ' border-slate-200 bg-white text-slate-600 hover:border-slate-300 hover:bg-slate-50';
  }

  function renderTaskFilterButton(item, selectedStatus, loading) {
    var active = item.value === selectedStatus;
    return '<button type="button" class="' + taskFilterButtonClass(active, loading && active) + '" data-status="' + escapeHtml(item.value) + '" aria-pressed="' + (active ? 'true' : 'false') + '">' +
      '<span class="task-list-filter-dot h-2 w-2 rounded-full ' + (active ? 'bg-white' : 'bg-slate-300') + '"></span>' +
      '<span>' + escapeHtml(item.label) + '</span>' +
    '</button>';
  }

  function formatTaskTime(value) {
    if (!value) return '--';
    var date = new Date(value);
    if (isNaN(date.getTime())) return String(value);
    try {
      return new Intl.DateTimeFormat('zh-CN', {
        year: 'numeric',
        month: '2-digit',
        day: '2-digit',
        hour: '2-digit',
        minute: '2-digit',
      }).format(date);
    } catch (e) {
      return String(value);
    }
  }

  function statusPill(status) {
    var key = String(status || '').trim().toLowerCase();
    if (key === 'published' || key === 'active') return '<span class="task-list-status-pill task-list-status-pill--published inline-flex items-center rounded-full border border-emerald-200 bg-emerald-50 px-3 py-1 text-xs font-medium text-emerald-700">已发布</span>';
    if (key === 'draft') return '<span class="task-list-status-pill task-list-status-pill--draft inline-flex items-center rounded-full border border-slate-200 bg-slate-50 px-3 py-1 text-xs font-medium text-slate-500">草稿</span>';
    if (key === 'archived' || key === 'closed') return '<span class="task-list-status-pill task-list-status-pill--archived inline-flex items-center rounded-full border border-slate-200 bg-white px-3 py-1 text-xs font-medium text-slate-500">已归档</span>';
    return '<span class="task-list-status-pill task-list-status-pill--default inline-flex items-center rounded-full border border-slate-200 bg-slate-50 px-3 py-1 text-xs font-medium text-slate-500">' + escapeHtml(status || '未知') + '</span>';
  }

  function renderTaskArchiveButton(item) {
    var taskId = Number(item && item.id || 0);
    var status = String((item && (item.publish_status || item.status)) || '').trim().toLowerCase();
    var archivingTaskId = Number((moduleState.taskCenter && moduleState.taskCenter.archivingTaskId) || 0);
    var archiving = taskId > 0 && archivingTaskId === taskId;
    if (status === 'archived' || status === 'closed') {
      return '<button type="button" disabled class="task-list-action-btn task-list-action-btn--disabled inline-flex min-h-[40px] items-center justify-center rounded-2xl border border-slate-200 bg-slate-100 px-4 py-2 text-sm font-semibold text-slate-400 cursor-not-allowed">已归档</button>';
    }
    return '<button type="button" class="task-list-action-btn task-list-action-btn--archive inline-flex min-h-[40px] items-center justify-center rounded-2xl border border-amber-200 bg-amber-50 px-4 py-2 text-sm font-semibold text-amber-700 transition hover:border-amber-300 hover:bg-amber-100 disabled:cursor-not-allowed disabled:opacity-60" data-task-archive="' + escapeHtml(String(taskId)) + '" data-task-name="' + escapeHtml(item && item.task_name ? item.task_name : '该任务') + '"' + (archiving ? ' disabled' : '') + '>' + (archiving ? '归档中...' : '归档考试') + '</button>';
  }

  function renderTaskRetakeButton(item) {
    var taskId = Number(item && item.id || 0);
    var status = String((item && (item.publish_status || item.status)) || '').trim().toLowerCase();
    var retakingTaskId = Number((moduleState.taskCenter && moduleState.taskCenter.retakingTaskId) || 0);
    var retaking = taskId > 0 && retakingTaskId === taskId;
    if (status !== 'archived' && status !== 'closed') return '';
    return '<button type="button" class="task-list-action-btn task-list-action-btn--retake inline-flex min-h-[40px] items-center justify-center rounded-2xl border border-blue-200 bg-blue-50 px-4 py-2 text-sm font-semibold text-blue-700 transition hover:border-blue-300 hover:bg-blue-100 disabled:cursor-not-allowed disabled:opacity-60" data-task-retake="' + escapeHtml(String(taskId)) + '" data-task-name="' + escapeHtml(item && item.task_name ? item.task_name : '该任务') + '"' + (retaking ? ' disabled' : '') + '>' + (retaking ? '重发中...' : '重新发布重考') + '</button>';
  }

  function renderTaskDeleteButton(item) {
    var taskId = Number(item && item.id || 0);
    var status = String((item && (item.publish_status || item.status)) || '').trim().toLowerCase();
    var deletingTaskId = Number((moduleState.taskCenter && moduleState.taskCenter.deletingTaskId) || 0);
    var deleting = taskId > 0 && deletingTaskId === taskId;
    if (status !== 'archived' && status !== 'closed') return '';
    return '<button type="button" class="task-list-action-btn task-list-action-btn--delete inline-flex min-h-[40px] items-center justify-center rounded-2xl border border-red-200 bg-red-50 px-4 py-2 text-sm font-semibold text-red-700 transition hover:border-red-300 hover:bg-red-100 disabled:cursor-not-allowed disabled:opacity-60" data-task-delete="' + escapeHtml(String(taskId)) + '" data-task-name="' + escapeHtml(item && item.task_name ? item.task_name : '该任务') + '"' + (deleting ? ' disabled' : '') + '>' + (deleting ? '删除中...' : '彻底删除') + '</button>';
  }

  container.innerHTML =
    '<div class="task-list-viewport">' +
      '<header class="app-page-header app-page-header--split">' +
        '<div>' +
          '<h1 class="app-page-title">考试任务管理</h1>' +
        '</div>' +
        '<div class="app-page-actions sm:justify-end">' +
          '<button type="button" id="task-list-refresh-btn" class="task-list-toolbar-btn task-list-toolbar-btn--secondary inline-flex min-h-[42px] items-center justify-center rounded-2xl border border-slate-200 bg-white px-4 py-2.5 text-sm font-semibold text-slate-700 transition hover:border-slate-300 hover:bg-slate-50 sm:w-auto">刷新列表</button>' +
          '<button type="button" id="task-list-create-btn" class="task-list-toolbar-btn task-list-toolbar-btn--primary inline-flex min-h-[42px] items-center justify-center rounded-2xl bg-slate-900 px-4 py-2.5 text-sm font-semibold text-white shadow-[0_12px_30px_rgba(15,23,42,0.16)] transition hover:bg-slate-800 sm:w-auto">新建考试任务</button>' +
        '</div>' +
      '</header>' +
      '<section class="app-page-panel">' +
        '<div class="task-list-fixed-area px-6 py-6 lg:px-8">' +
          '<div class="flex flex-wrap gap-2" id="task-list-filter-bar">' +
            statusOptions.map(function (item) {
              return renderTaskFilterButton(item, currentStatus, false);
            }).join('') +
          '</div>' +
          '<div id="task-list-summary" class="mt-5 grid gap-4 sm:grid-cols-3"></div>' +
        '</div>' +
        '<div id="task-list-body" class="task-list-scroll-area px-6 lg:px-8 pb-6"></div>' +
      '</section>' +
    '</div>';

  var bodyEl = document.getElementById('task-list-body');
  var summaryEl = document.getElementById('task-list-summary');
  var filterBarEl = document.getElementById('task-list-filter-bar');

  function bindTaskListActionButtons() {
    if (!bodyEl) return;
    bodyEl.querySelectorAll('[data-task-archive]').forEach(function (btn) {
      btn.addEventListener('click', function () {
        var taskId = Number(this.getAttribute('data-task-archive') || 0);
        var taskName = String(this.getAttribute('data-task-name') || '该任务');
        archiveTask(taskId, taskName);
      });
    });
    bodyEl.querySelectorAll('[data-task-retake]').forEach(function (btn) {
      btn.addEventListener('click', function () {
        var taskId = Number(this.getAttribute('data-task-retake') || 0);
        var taskName = String(this.getAttribute('data-task-name') || '该任务');
        retakeTask(taskId, taskName);
      });
    });
    bodyEl.querySelectorAll('[data-task-delete]').forEach(function (btn) {
      btn.addEventListener('click', function () {
        var taskId = Number(this.getAttribute('data-task-delete') || 0);
        var taskName = String(this.getAttribute('data-task-name') || '该任务');
        deleteTask(taskId, taskName);
      });
    });
  }

  async function archiveTask(taskId, taskName) {
    if (!taskId) return;
    var confirmed = window.confirm('确认归档“' + taskName + '”？归档后员工端将不再把它作为进行中的考试任务展示');
    if (!confirmed) return;

    moduleState.taskCenter = Object.assign({}, moduleState.taskCenter, { archivingTaskId: taskId });
    try {
      await archiveManageTask(taskId);
      showToast('考试任务已归档', 'ok');
      var nextStatus = String((moduleState.taskCenter && moduleState.taskCenter.status) || 'all');
      if (nextStatus === 'published') {
        nextStatus = 'all';
      }
      await loadTaskList(nextStatus);
    } catch (error) {
      alert((error && error.message) ? error.message : '归档失败');
    } finally {
      moduleState.taskCenter = Object.assign({}, moduleState.taskCenter, { archivingTaskId: 0 });
    }
  }

  function closeTaskActionModal() {
    var modal = document.getElementById('task-action-modal');
    if (modal) modal.classList.add('hidden');
  }
  window.closeTaskActionModal = closeTaskActionModal;

  function ensureTaskActionModal() {
    if (document.getElementById('task-action-modal')) return;
    var modal = document.createElement('div');
    modal.id = 'task-action-modal';
    modal.className = 'fixed inset-0 z-[999] hidden flex items-center justify-center bg-black/30 p-4 backdrop-blur-sm';
    modal.addEventListener('click', function (e) { if (e.target === modal) closeTaskActionModal(); });
    modal.innerHTML =
      '<div class="relative w-full max-w-sm bg-white rounded-2xl shadow-xl overflow-hidden">' +
      '<div class="p-6 text-center">' +
      '<div id="task-action-icon" class="mx-auto w-12 h-12 rounded-full flex items-center justify-center mb-4"></div>' +
      '<h3 id="task-action-title" class="text-lg font-semibold text-gray-800 mb-2"></h3>' +
      '<p id="task-action-msg" class="text-sm text-gray-500 mb-6"></p>' +
      '<div class="flex gap-3">' +
      '<button type="button" id="task-action-cancel-btn" class="flex-1 px-5 py-2.5 rounded-xl text-sm font-medium text-gray-600 bg-gray-100 transition-all duration-200 hover:bg-gray-200 active:scale-[0.98]">取消</button>' +
      '<button type="button" id="task-action-confirm-btn" class="flex-1 px-5 py-2.5 rounded-xl text-sm font-semibold text-white transition-all duration-200 hover:brightness-105 active:scale-[0.98]">确认</button>' +
      '</div>' +
      '</div>' +
      '</div>';
    document.body.appendChild(modal);
    document.getElementById('task-action-cancel-btn').addEventListener('click', closeTaskActionModal);
  }

  function showTaskActionModal(title, message, confirmText, color, onConfirm) {
    ensureTaskActionModal();
    var modal = document.getElementById('task-action-modal');
    var iconEl = document.getElementById('task-action-icon');
    var titleEl = document.getElementById('task-action-title');
    var msgEl = document.getElementById('task-action-msg');
    var confirmBtn = document.getElementById('task-action-confirm-btn');
    if (titleEl) titleEl.textContent = title;
    if (msgEl) msgEl.textContent = message;
    if (confirmBtn) confirmBtn.textContent = confirmText;
    if (color === 'red') {
      if (iconEl) { iconEl.className = 'mx-auto w-12 h-12 rounded-full bg-red-100 flex items-center justify-center mb-4'; iconEl.innerHTML = '<svg class="w-6 h-6 text-red-600" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>'; }
      if (confirmBtn) { confirmBtn.className = 'flex-1 px-5 py-2.5 rounded-xl text-sm font-semibold text-white bg-red-600 transition-all duration-200 hover:brightness-105 active:scale-[0.98]'; }
    } else {
      if (iconEl) { iconEl.className = 'mx-auto w-12 h-12 rounded-full bg-blue-100 flex items-center justify-center mb-4'; iconEl.innerHTML = '<svg class="w-6 h-6 text-blue-600" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"/></svg>'; }
      if (confirmBtn) { confirmBtn.className = 'flex-1 px-5 py-2.5 rounded-xl text-sm font-semibold text-white bg-blue-600 transition-all duration-200 hover:brightness-105 active:scale-[0.98]'; }
    }
    if (confirmBtn) confirmBtn.onclick = onConfirm;
    modal.classList.remove('hidden');
  }

  async function retakeTask(taskId, taskName) {
    if (!taskId) return;
    ensureTaskActionModal();
    showTaskActionModal(
      '重新发布重考',
      '确认将”' + taskName + '”重新发布为重考吗？系统会清空这张历史试卷已有的员工答卷记录，并让员工端重新看到待考试卷',
      '确认发布',
      'blue',
      async function () {
        closeTaskActionModal();
        moduleState.taskCenter = Object.assign({}, moduleState.taskCenter, { retakingTaskId: taskId });
        try {
          var result = await retakeManageTask(taskId);
          var deletedCount = Number(result && result.deleted_record_count || 0);
          showToast('已重新发布重考，已清空 ' + deletedCount + ' 条历史答卷', 'ok');
          await loadTaskList('published');
        } catch (error) {
          showToast((error && error.message) ? error.message : '重新发布重考失败', 'error');
        } finally {
          moduleState.taskCenter = Object.assign({}, moduleState.taskCenter, { retakingTaskId: 0 });
        }
      }
    );
  }

  async function deleteTask(taskId, taskName) {
    if (!taskId) return;
    ensureTaskActionModal();
    showTaskActionModal(
      '彻底删除试卷',
      '确认彻底删除历史试卷”' + taskName + '”？该操作不可撤销，并会同步删除员工端对应的考试历史记录',
      '确认删除',
      'red',
      async function () {
        closeTaskActionModal();
        moduleState.taskCenter = Object.assign({}, moduleState.taskCenter, { deletingTaskId: taskId });
        try {
          var result = await deleteManageTask(taskId);
          var deletedCount = Number(result && result.deleted_record_count || 0);
          showToast('历史试卷已删除，同时清理 ' + deletedCount + ' 条员工记录', 'ok');
          await loadTaskList((moduleState.taskCenter && moduleState.taskCenter.status) || 'all');
        } catch (error) {
          showToast((error && error.message) ? error.message : '删除失败', 'error');
        } finally {
          moduleState.taskCenter = Object.assign({}, moduleState.taskCenter, { deletingTaskId: 0 });
        }
      }
    );
  }

  function syncTaskListFilterButtons(selectedStatus, loading) {
    if (!filterBarEl) return;
    filterBarEl.innerHTML = statusOptions.map(function (item) {
      return renderTaskFilterButton(item, selectedStatus, loading);
    }).join('');
    filterBarEl.querySelectorAll('.task-list-filter-btn').forEach(function (btn) {
      btn.addEventListener('click', function () {
        loadTaskList(String(this.getAttribute('data-status') || 'all'));
      });
    });
  }

  async function loadTaskList(status) {
    var selectedStatus = String(status || 'all');
    moduleState.taskCenter = Object.assign({}, moduleState.taskCenter, { status: selectedStatus });
    syncTaskListFilterButtons(selectedStatus, true);
    if (bodyEl) {
      bodyEl.innerHTML = '<div class="task-list-loading-state rounded-[28px] border border-dashed border-slate-200 bg-slate-50/80 px-6 py-10 text-center text-sm text-slate-500">正在加载任务列表...</div>';
    }

    try {
      var items = await fetchManageTasks(selectedStatus);
      var total = items.length;
      var activeCount = items.filter(function (item) { return String((item && (item.publish_status || item.status)) || '').toLowerCase() === 'published'; }).length;
      var closedCount = items.filter(function (item) { return String((item && (item.publish_status || item.status)) || '').toLowerCase() === 'archived'; }).length;

      if (summaryEl) {
        summaryEl.innerHTML =
          '<div class="task-list-summary-card rounded-[24px] border border-slate-200 bg-white px-5 py-5 shadow-[0_10px_30px_rgba(15,23,42,0.04)]"><div class="ios-eyebrow">筛选结果</div><div class="task-list-summary-value mt-3 ios-stat-value text-slate-900">' + escapeHtml(String(total)) + '</div><div class="mt-2 ios-inline-note">当前查看：' + escapeHtml(taskFilterLabel(selectedStatus)) + '</div></div>' +
          '<div class="task-list-summary-card rounded-[24px] border border-slate-200 bg-white px-5 py-5 shadow-[0_10px_30px_rgba(15,23,42,0.04)]"><div class="ios-eyebrow">已发布</div><div class="task-list-summary-value mt-3 ios-stat-value text-slate-900">' + escapeHtml(String(activeCount)) + '</div><div class="mt-2 ios-inline-note">进行中的正式考试</div></div>' +
          '<div class="task-list-summary-card rounded-[24px] border border-slate-200 bg-white px-5 py-5 shadow-[0_10px_30px_rgba(15,23,42,0.04)]"><div class="task-list-summary-label ios-eyebrow">已归档</div><div class="task-list-summary-value mt-3 ios-stat-value text-slate-900">' + escapeHtml(String(closedCount)) + '</div><div class="mt-2 ios-inline-note">已归档任务</div></div>';
      }

      if (!items.length) {
        if (bodyEl) {
          bodyEl.innerHTML = renderEmptyState('任务');
        }
        return;
      }

      if (bodyEl) {
        bodyEl.innerHTML =
          '<div class="task-list-stack space-y-4">' +
            items.map(function (item) {
              return '' +
                '<article class="task-list-card rounded-[28px] border border-slate-200 bg-white p-5 shadow-[0_10px_30px_rgba(15,23,42,0.04)]">' +
                  '<div class="flex flex-col gap-4 lg:flex-row lg:items-start lg:justify-between">' +
                    '<div class="min-w-0">' +
                      '<div class="flex flex-wrap items-center gap-2">' +
                        statusPill(item && (item.publish_status || item.status)) +
                        '<span class="task-list-meta-pill rounded-full border border-slate-200 bg-slate-50 px-3 py-1 text-xs font-medium text-slate-500">' + escapeHtml(examCenterTypeLabel(item && (item.exam_mode || item.task_type))) + '</span>' +
                        ((item && item.module_code) ? '<span class="task-list-meta-pill rounded-full border border-slate-200 bg-slate-50 px-3 py-1 text-xs font-medium text-slate-500">' + escapeHtml(practiceModuleLabel(item.module_code)) + '</span>' : '') +
                      '</div>' +
                      '<h3 class="task-list-card-title mt-3 text-[22px] font-semibold tracking-[-0.03em] text-slate-900">' + escapeHtml(item && item.task_name ? item.task_name : '未命名任务') + '</h3>' +
                      '<p class="task-list-card-desc mt-2 text-sm leading-7 text-slate-600">' + escapeHtml(item && item.task_desc ? item.task_desc : '暂无描述') + '</p>' +
                    '</div>' +
                    '<div class="task-list-owner-card shrink-0 rounded-[22px] border border-slate-200 bg-slate-50 px-4 py-3">' +
                      '<div class="task-list-label ios-eyebrow">发布人</div>' +
                      '<div class="task-list-value mt-2 text-sm font-semibold text-slate-900">' + escapeHtml(String(item && (item.publisher_name || item.publisher_id) || '--')) + '</div>' +
                      ((item && item.publisher_name && item.publisher_id && item.publisher_name !== item.publisher_id) ? '<div class="task-list-owner-subtext mt-1 text-xs text-slate-500">' + escapeHtml(String(item.publisher_id)) + '</div>' : '') +
                    '</div>' +
                  '</div>' +
                  '<div class="mt-5 grid gap-3 md:grid-cols-4">' +
                    '<div class="task-list-stat-card rounded-2xl border border-slate-200 bg-slate-50 px-4 py-4"><div class="task-list-label text-xs text-slate-400">下发范围</div><div class="task-list-value mt-2 text-sm font-semibold text-slate-900">' + escapeHtml(String(item && (item.target_summary || item.target_scope) || '--')) + '</div></div>' +
                    '<div class="task-list-stat-card rounded-2xl border border-slate-200 bg-slate-50 px-4 py-4"><div class="task-list-label text-xs text-slate-400">及格线</div><div class="task-list-value mt-2 text-sm font-semibold text-slate-900">' + escapeHtml(String(Number(item && item.pass_score != null ? item.pass_score : 0).toFixed(1))) + ' 分</div></div>' +
                    '<div class="task-list-stat-card rounded-2xl border border-slate-200 bg-slate-50 px-4 py-4"><div class="task-list-label text-xs text-slate-400">时长 / 成绩</div><div class="task-list-value mt-2 text-sm font-semibold text-slate-900">' + escapeHtml(String(item && item.duration_minutes || 60)) + ' 分钟 / ' + escapeHtml(isHiddenScoreVisibility(item && item.score_visibility) ? '员工不可见' : '员工可见') + '</div></div>' +
                    '<div class="task-list-stat-card rounded-2xl border border-slate-200 bg-slate-50 px-4 py-4"><div class="task-list-label text-xs text-slate-400">截止 / 完成</div><div class="task-list-value mt-2 text-sm font-semibold leading-6 text-slate-900">' + escapeHtml(formatTaskTime(item && item.deadline)) + '<br>' + escapeHtml(String(item && item.completed_count != null ? item.completed_count : 0)) + ' / ' + escapeHtml(String(item && item.target_count != null ? item.target_count : 0)) + '</div></div>' +
                  '</div>' +
                  '<div class="task-list-footer mt-5 flex flex-col gap-3 border-t border-slate-100 pt-4 sm:flex-row sm:items-center sm:justify-between">' +
                    '<div class="task-list-timestamps text-xs leading-6 text-slate-500">发布时间：' + escapeHtml(formatTaskTime(item && item.published_at)) + '　创建时间：' + escapeHtml(formatTaskTime(item && item.created_at)) + '</div>' +
                    '<div class="flex flex-wrap items-center gap-2">' +
                      renderTaskRetakeButton(item) +
                      renderTaskArchiveButton(item) +
                      renderTaskDeleteButton(item) +
                    '</div>' +
                  '</div>' +
                '</article>';
            }).join('') +
          '</div>';
        bindTaskListActionButtons();
      }
    } catch (error) {
      if (summaryEl) summaryEl.innerHTML = '';
      if (bodyEl) {
        bodyEl.innerHTML = '<div class="rounded-[28px] border border-slate-200 bg-white px-6 py-12 text-center shadow-[0_10px_30px_rgba(15,23,42,0.04)]"><div class="text-base font-semibold text-slate-900">任务列表加载失败</div><p class="mt-2 text-sm leading-7 text-slate-500">' + escapeHtml((error && error.message) ? error.message : '请稍后重试') + '</p></div>';
      }
    }

    syncTaskListFilterButtons(selectedStatus, false);
  }

  var refreshBtn = document.getElementById('task-list-refresh-btn');
  var createBtn = document.getElementById('task-list-create-btn');
  if (refreshBtn) {
    refreshBtn.addEventListener('click', function () {
      loadTaskList((moduleState.taskCenter && moduleState.taskCenter.status) || 'all');
    });
  }
  if (createBtn) {
    createBtn.addEventListener('click', function () {
      navigateTo('task_publish');
    });
  }
  syncTaskListFilterButtons(currentStatus, false);
  loadTaskList(currentStatus);
}

function profileInitial(name, username) {
  var s = String(name || username || 'U').trim();
  return s ? s.charAt(0).toUpperCase() : 'U';
}

function normalizeRole(role) {
  var r = String(role || '').trim().toLowerCase();
  if (r === 'leader') return 'store_manager';
  if (r === 'senior') return 'senior_consultant';
  if (r === 'newbie') return 'trainee';
  return r || 'trainee';
}

function isAdminRole(role) {
  return normalizeRole(role) === 'admin';
}

function isManagementRole(role) {
  var normalized = normalizeRole(role);
  return normalized === 'admin' || normalized === 'store_manager';
}

const PAGE_ROLE_ACCESS = {
  quick_query: ['admin', 'store_manager'],
  talent_dashboard: ['admin', 'store_manager'],
  task_list: ['admin', 'store_manager'],
  task_publish: ['admin', 'store_manager'],
  training_manage: ['admin', 'store_manager'],
  personnel_manage: ['admin', 'store_manager'],
  store_manage: ['admin', 'store_manager'],
  knowledge_manage: ['admin'],
  digital_human_settings: ['admin'],
  system_settings: ['admin'],
  system_logs: ['admin'],
  audit_logs: ['admin'],
};

function getCurrentRole() {
  return normalizeRole(localStorage.getItem('role') || '');
}

function canAccessPage(page) {
  var role = getCurrentRole();
  var allowedRoles = PAGE_ROLE_ACCESS[page];
  if (allowedRoles && allowedRoles.length && allowedRoles.indexOf(role) === -1) return false;
  // 管理层可访问其权限内页面；普通员工可访问所有非管理页面
  if (isManagementRole(role)) return true;
  // 普通员工（trainee/senior_consultant）可访问所有非管理页面
  return true;
}

function getAccountDisplayName() {
  var username = localStorage.getItem('username') || '';
  var displayName = localStorage.getItem('displayName') || username || '用户';
  var s = String(displayName).trim();
  return s || '用户';
}

function getBeijingHour() {
  try {
    var dtf = new Intl.DateTimeFormat('zh-CN', {
      timeZone: 'Asia/Shanghai',
      hour: 'numeric',
      hour12: false,
    });
    var parts = dtf.formatToParts(new Date());
    for (var i = 0; i < parts.length; i++) {
      if (parts[i].type === 'hour') {
        return parseInt(parts[i].value, 10);
      }
    }
  } catch (e) {}
  return new Date().getHours();
}

function getTimeGreetingForHour(h) {
  if (h >= 5 && h < 12) return '早上好';
  if (h >= 12 && h < 14) return '中午好';
  if (h >= 14 && h < 18) return '下午好';
  if (h >= 18 && h < 23) return '晚上好';
  return '夜深了';
}

function buildHomeHeroTitle() {
  return getTimeGreetingForHour(getBeijingHour()) + '，' + getAccountDisplayName();
}

function getBeijingTimeShort() {
  try {
    var dtf = new Intl.DateTimeFormat('zh-CN', {
      timeZone: 'Asia/Shanghai',
      hour: '2-digit',
      minute: '2-digit',
      hour12: false,
    });
    var parts = dtf.formatToParts(new Date());
    var h = '', m = '';
    for (var i = 0; i < parts.length; i++) {
      if (parts[i].type === 'hour') h = parts[i].value;
      if (parts[i].type === 'minute') m = parts[i].value;
    }
    return h + ':' + m;
  } catch (e) {
    return '--:--';
  }
}

function getBeijingWeekday() {
  try {
    var dtf = new Intl.DateTimeFormat('zh-CN', {
      timeZone: 'Asia/Shanghai',
      weekday: 'long',
    });
    return dtf.format(new Date());
  } catch (e) {
    return '';
  }
}

function refreshHomeHeroTitle() {
  var el = document.getElementById('home-hero-title');
  if (el) el.textContent = buildHomeHeroTitle();
}

function refreshHomeHeroSubtitle() {
  var el = document.getElementById('home-hero-desc');
  if (el) el.textContent = buildHomeHeroSubtitle();
}

function syncProfileWidget() {
  var username = localStorage.getItem('username') || '';
  var displayName = localStorage.getItem('displayName') || username || '用户';
  var role = normalizeRole(localStorage.getItem('role') || '');
  var roleLabel = ROLE_LABELS[role] || role || '用户';
  var ch = profileInitial(displayName, username);

  var elName = document.getElementById('profile-widget-name');
  var elSub = document.getElementById('profile-widget-sub');
  var elAv = document.getElementById('avatar-letter');
  var modalAv = document.getElementById('acc-modal-avatar');
  if (elName) elName.textContent = displayName;
  if (elSub) elSub.textContent = roleLabel;
  if (elAv) elAv.textContent = ch;
  if (modalAv) modalAv.textContent = ch;
  refreshHomeHeroTitle();
}

function showLogin() {
  closeFloatingRouteOverlays();
  if (window.AgentO && typeof window.AgentO.destroyAgentActivityPanel === 'function') {
    window.AgentO.destroyAgentActivityPanel();
  }
  document.getElementById('view-login').classList.remove('hidden');
  document.getElementById('view-dashboard').classList.add('hidden');
  sidebarMobileOpen = false;
  document.body.classList.remove('sidebar-mobile-open', 'sidebar-rail-mode');
  var panel = document.getElementById('login-demo-panel');
  if (panel && panel.parentElement) panel.parentElement.removeChild(panel);
  // Mount digital human on login page
  var _dhPages = (typeof window._DH_ENABLED_PAGES !== 'undefined') ? window._DH_ENABLED_PAGES : [];
  if (_dhPages.indexOf('login') >= 0 && typeof window.isDigitalHumanSystemEnabled === 'function' && window.isDigitalHumanSystemEnabled()) {
    if (typeof mountDigitalHuman === 'function') {
      if (typeof digitalHumanSetActivePage === 'function') digitalHumanSetActivePage('login');
      mountDigitalHuman();
    }
  }
}

function mountAgentActivityPanelIfAvailable() {
  if (!window.AgentO || typeof window.AgentO.mountAgentActivityPanel !== 'function') return;
  window.AgentO.mountAgentActivityPanel({
    baseUrl: API_BASE || '',
    tokenProvider: function () {
      return localStorage.getItem('token') || '';
    },
  });
}

function showDashboard() {
  document.getElementById('view-login').classList.add('hidden');
  document.getElementById('view-dashboard').classList.remove('hidden');
  syncProfileWidget();
  renderMenu();
  applySidebarCollapsedState(loadSidebarCollapsedPreference());
  applyResolvedTheme();
  bindSystemThemeWatcher();
  mountAgentActivityPanelIfAvailable();
  // New trainee accounts now enter the growth plan page directly.
  var role = localStorage.getItem('role') || '';
  var onboardingDone = localStorage.getItem('onboarding_completed');
  if (role === 'trainee' && onboardingDone !== 'true') {
    navigateTo('growth_plan');
    return;
  }
  // Check force_redirect_page from onboarding status
  if (role === 'trainee' && onboardingDone === 'true') {
    try {
      apiFetch('/api/onboarding/status').then(function(json) {
        if ((json.code === 200 || json.code === 0) && json.data) {
          var d = json.data;
          var s = moduleState.growth;
          localStorage.setItem('onboarding_completed', String(!!d.onboarding_completed));
          localStorage.setItem('training_cycle_id', d.cycle_id || '');
          localStorage.setItem('current_cycle_day', String(d.current_day || 0));
          s.currentStageNo = Number(d.current_stage_no || 0);
          s.currentStageName = String(d.current_stage_name || '');
          s.stageStatus = String(d.stage_status || '');
          s.moduleUnlocks = d.module_unlocks || null;
          s.forceRedirectPage = String(d.force_redirect_page || '');
          s.onboardingStatusLoaded = true;
          if (d.force_redirect_page === 'growth_plan') {
            navigateTo('growth_plan');
          }
        }
      }).catch(function() {});
    } catch(e) {}
  }
  navigateTo(getInitialDashboardPage());
}

function dropCurrentRouteHash() {
  try {
    var path = window.location.pathname || '/frontend/';
    var search = window.location.search || '';
    if (window.history && window.history.replaceState) {
      window.history.replaceState(null, '', path + search);
    }
  } catch (e) {}
}

async function login(ev) {
  if (ev) ev.preventDefault();
  var user = document.getElementById('login-user');
  var pass = document.getElementById('login-pass');
  var err = document.getElementById('login-error');
  var btn = document.getElementById('login-btn');
  if (err) {
    err.classList.add('hidden');
    err.textContent = '';
  }
  if (btn) {
    btn.classList.add('btn-loading');
    btn.disabled = true;
  }
  try {
    var payload = {
      username: user ? user.value.trim() : '',
      password: pass ? pass.value : '',
    };
    var j = await apiFetch('/api/login', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
      skipAuth: true,
    });
    if (!j || Number(j.code) !== 200) {
      throw new Error((j && (j.message || j.detail)) || '登录失败');
    }
    var data = j.data || {};
    var token = data.access_token || data.token || '';
    if (!token) {
      throw new Error('登录失败：服务端未返回凭证');
    }
    resetSessionUiState();
    dropCurrentRouteHash();
    localStorage.setItem('token', token);
    localStorage.setItem('username', data.username || payload.username || '');
    localStorage.setItem('displayName', data.display_name || data.username || payload.username || '');
    localStorage.setItem('role', normalizeRole(data.role || 'trainee'));
    localStorage.setItem('userId', data.user_id || '');
    localStorage.setItem('employeeNo', data.employee_no || dashboardEmployeeNo(data.user_id || ''));
    localStorage.setItem('store_id', data.store_id || '');
    localStorage.setItem('store_name', data.store_name || data.store_id || '');
    localStorage.setItem('first_login', String(!!data.first_login));
    localStorage.setItem('onboarding_completed', String(!!data.onboarding_completed));
    localStorage.setItem('training_cycle_id', data.training_cycle_id || '');
    localStorage.setItem('current_cycle_day', String(data.current_cycle_day || 0));
    if (typeof digitalHumanLoginSuccess === 'function') digitalHumanLoginSuccess();
    showDashboard();
  } catch (e) {
    if (typeof digitalHumanLoginFail === 'function') digitalHumanLoginFail();
    if (err) {
      err.textContent = e.message || '登录失败';
      err.classList.remove('hidden');
    }
  } finally {
    if (btn) {
      btn.classList.remove('btn-loading');
      btn.disabled = false;
    }
  }
}

function logout() {
  resetSessionUiState();
  if (window.AgentO && typeof window.AgentO.destroyAgentActivityPanel === 'function') {
    window.AgentO.destroyAgentActivityPanel();
  }
  localStorage.removeItem('token');
  localStorage.removeItem('username');
  localStorage.removeItem('displayName');
  localStorage.removeItem('role');
  localStorage.removeItem('userId');
  localStorage.removeItem('employeeNo');
  localStorage.removeItem('store_id');
  localStorage.removeItem('store_name');
  localStorage.removeItem('first_login');
  localStorage.removeItem('onboarding_completed');
  localStorage.removeItem('training_cycle_id');
  localStorage.removeItem('current_cycle_day');
  try {
    sessionStorage.removeItem(assistantStorageKey());
    sessionStorage.removeItem(quickQueryStorageKey());
    sessionStorage.removeItem(knowledgeQaStorageKey());
    sessionStorage.removeItem(PRACTICE_STATE_KEY);
    sessionStorage.removeItem(ASSESSMENT_STATE_KEY);
    sessionStorage.removeItem(digitalHumanContextStorageKey());
  } catch (e) {}
  closeProfilePopover();
  closeModal();
  closeEditModal();
  closeStoresModal();
  closeAccountModal();
  showLogin();
}

async function checkAuth() {
  var raw = localStorage.getItem('token');
  var token = (raw || '').trim();
  if (!token || token === 'undefined' || token === 'null') {
    if (raw) localStorage.removeItem('token');
    showLogin();
    return;
  }
  try {
    var j = await apiFetch('/api/me');
    if (!j || j.code !== 200) {
      logout();
      return;
    }
    var data = j.data || {};
    if (data.store_id !== undefined) localStorage.setItem('store_id', data.store_id || '');
    if (data.store_name !== undefined) localStorage.setItem('store_name', data.store_name || data.store_id || '');
    if (data.user_id !== undefined) localStorage.setItem('userId', data.user_id || '');
    if (data.display_name !== undefined) localStorage.setItem('displayName', data.display_name || localStorage.getItem('displayName') || '');
    if (data.employee_no !== undefined || data.user_id !== undefined) localStorage.setItem('employeeNo', data.employee_no || dashboardEmployeeNo(data.user_id || localStorage.getItem('userId') || ''));
    if (data.onboarding_completed !== undefined) localStorage.setItem('onboarding_completed', String(!!data.onboarding_completed));
    if (data.training_cycle_id !== undefined) localStorage.setItem('training_cycle_id', data.training_cycle_id || '');
    if (data.current_cycle_day !== undefined) localStorage.setItem('current_cycle_day', String(data.current_cycle_day || 0));
    showDashboard();
  } catch (e) {
    var msg = String((e && e.message) || '');
    if (msg.indexOf('无法连接后端服务') !== -1) {
      showDashboard();
      return;
    }
    showLogin();
  }
}

var sidebarAccordionState = {};
var sidebarDesktopCollapsed = false;
var sidebarMobileOpen = false;
var sidebarRailFlyoutSectionId = '';

function sidebarIconSvg(iconKey) {
  return SIDEBAR_ICON_SVGS[iconKey] || SIDEBAR_ICON_SVGS.system;
}

function isSidebarMobileViewport() {
  return window.innerWidth < 1024;
}

function getVisibleSidebarSections() {
  var sections = [];
  for (var i = 0; i < SIDEBAR_SECTIONS.length; i++) {
    var section = SIDEBAR_SECTIONS[i];
    var visibleItems = section.items.filter(function (page) {
      return canAccessPage(page);
    });
    if (!visibleItems.length) continue;
    sections.push({
      id: section.id,
      title: section.title,
      zone: section.zone,
      icon: section.icon,
      items: visibleItems,
    });
  }
  return sections;
}

function menuGroupByPage(page) {
  if (!canAccessPage(page)) return '';
  var sections = getVisibleSidebarSections();
  for (var i = 0; i < sections.length; i++) {
    if (sections[i].items.indexOf(page) !== -1) return sections[i].id;
  }
  return '';
}

function initSidebarAccordionState() {
  var sections = getVisibleSidebarSections();
  for (var i = 0; i < sections.length; i++) {
    var id = sections[i].id;
    if (typeof sidebarAccordionState[id] !== 'boolean') {
      sidebarAccordionState[id] = false;
    }
  }
}

function syncSidebarToggleButtons() {
  var mobile = isSidebarMobileViewport();
  var collapsed = !mobile && sidebarDesktopCollapsed;
  var mobileTrigger = document.getElementById('sidebar-mobile-trigger');
  var collapseBtn = document.getElementById('sidebar-collapse-btn');
  if (mobileTrigger) {
    mobileTrigger.setAttribute('aria-expanded', mobile && sidebarMobileOpen ? 'true' : 'false');
    mobileTrigger.setAttribute('aria-label', mobile && sidebarMobileOpen ? '关闭导航' : '打开导航');
  }
  if (collapseBtn) {
    collapseBtn.setAttribute('aria-expanded', mobile ? (sidebarMobileOpen ? 'true' : 'false') : (!collapsed ? 'true' : 'false'));
    collapseBtn.setAttribute('aria-label', mobile ? '关闭导航' : (collapsed ? '展开导航' : '收起导航'));
  }
}

function syncSidebarSectionAccessibility(sectionEl) {
  if (!sectionEl) return;
  var panel = sectionEl.querySelector('.sidebar-menu-section-panel');
  if (!panel) return;
  var sidebar = document.getElementById('sidebar');
  var isRail = !!sidebar && sidebar.dataset.collapsed === 'true' && !isSidebarMobileViewport();
  var isOpen = isRail
    ? sectionEl.classList.contains('sidebar-menu-section--rail-open')
    : sectionEl.classList.contains('expanded');
  panel.setAttribute('aria-hidden', isOpen ? 'false' : 'true');
  var links = panel.querySelectorAll('.sidebar-menu-link[data-page]');
  links.forEach(function (link) {
    if (isOpen) link.removeAttribute('tabindex');
    else link.tabIndex = -1;
  });
}

function syncAllSidebarSectionAccessibility() {
  var sections = document.querySelectorAll('.sidebar-menu-section[data-section-id]');
  sections.forEach(syncSidebarSectionAccessibility);
}

function setSidebarRailFlyout(sectionId) {
  sidebarRailFlyoutSectionId = sectionId || '';
  var sections = document.querySelectorAll('.sidebar-menu-section[data-section-id]');
  sections.forEach(function (sectionEl) {
    var on = !!sidebarRailFlyoutSectionId && sectionEl.getAttribute('data-section-id') === sidebarRailFlyoutSectionId;
    sectionEl.classList.toggle('sidebar-menu-section--rail-open', on);
    var toggle = sectionEl.querySelector('.sidebar-menu-section-toggle');
    if (toggle && document.getElementById('sidebar') && document.getElementById('sidebar').dataset.collapsed === 'true') {
      toggle.setAttribute('aria-expanded', on ? 'true' : 'false');
    }
    syncSidebarSectionAccessibility(sectionEl);
  });
  if (sidebarRailFlyoutSectionId) {
    positionSidebarRailFlyout(sidebarRailFlyoutSectionId);
  }
}

function closeSidebarRailFlyout() {
  setSidebarRailFlyout('');
}

function setSidebarGroupExpanded(groupId, expanded) {
  sidebarAccordionState[groupId] = !!expanded;
  var group = document.querySelector('.sidebar-menu-section[data-section-id="' + groupId + '"]');
  if (!group) return;
  group.classList.toggle('expanded', !!expanded);
  var toggle = group.querySelector('.sidebar-menu-section-toggle');
  if (toggle && (!document.getElementById('sidebar') || document.getElementById('sidebar').dataset.collapsed !== 'true')) {
    toggle.setAttribute('aria-expanded', expanded ? 'true' : 'false');
  }
  syncSidebarSectionAccessibility(group);
}

function collapseOtherSidebarGroups(activeGroupId) {
  var sections = getVisibleSidebarSections();
  for (var i = 0; i < sections.length; i++) {
    var gid = sections[i].id;
    if (gid !== activeGroupId) setSidebarGroupExpanded(gid, false);
  }
}

function sidebarToggleSection(sectionId) {
  var sidebar = document.getElementById('sidebar');
  if (!sidebar) return;
  if (sidebar.dataset.collapsed === 'true' && !isSidebarMobileViewport()) {
    setSidebarRailFlyout(sidebarRailFlyoutSectionId === sectionId ? '' : sectionId);
    return;
  }
  var willExpand = !sidebarAccordionState[sectionId];
  if (willExpand) collapseOtherSidebarGroups(sectionId);
  setSidebarGroupExpanded(sectionId, willExpand);
}

function setSidebarMobileOpen(open) {
  sidebarMobileOpen = !!open;
  if (!sidebarMobileOpen) {
    closeSidebarRailFlyout();
  }
  syncSidebarLayoutState();
  if (!sidebarMobileOpen) {
    var mobileTrigger = document.getElementById('sidebar-mobile-trigger');
    if (mobileTrigger) {
      setTimeout(function () {
        try { mobileTrigger.focus(); } catch (e) {}
      }, 0);
    }
  }
}

function closeSidebarMobile(ev) {
  if (ev) ev.stopPropagation();
  if (!isSidebarMobileViewport()) return;
  setSidebarMobileOpen(false);
}

function positionSidebarRailFlyout(sectionId) {
  var sidebar = document.getElementById('sidebar');
  if (!sidebar || sidebar.dataset.collapsed !== 'true' || !sectionId) return;
  var sectionEl = document.querySelector('.sidebar-menu-section[data-section-id="' + sectionId + '"]');
  var panel = sectionEl && sectionEl.querySelector('.sidebar-menu-section-panel');
  if (!sectionEl || !panel) return;
  var sectionRect = sectionEl.getBoundingClientRect();
  var sidebarRect = sidebar.getBoundingClientRect();
  var viewportHeight = window.innerHeight || document.documentElement.clientHeight || 0;
  var panelHeight = panel.offsetHeight || 0;
  var top = sectionRect.top;
  if (viewportHeight && panelHeight) {
    top = Math.min(top, Math.max(16, viewportHeight - panelHeight - 16));
  }
  top = Math.max(16, top);
  panel.style.top = Math.round(top) + 'px';
  panel.style.left = Math.round(sidebarRect.right + 14) + 'px';
}

function syncSidebarLayoutState() {
  var sidebar = document.getElementById('sidebar');
  if (!sidebar) return;
  var mobile = isSidebarMobileViewport();
  if (!mobile) {
    sidebarMobileOpen = false;
  }
  sidebar.dataset.collapsed = !mobile && sidebarDesktopCollapsed ? 'true' : 'false';
  sidebar.dataset.mobileOpen = mobile && sidebarMobileOpen ? 'true' : 'false';
  sidebar.dataset.viewport = mobile ? 'mobile' : 'desktop';
  document.body.classList.toggle('sidebar-mobile-open', mobile && sidebarMobileOpen);
  document.body.classList.toggle('sidebar-rail-mode', !mobile && sidebarDesktopCollapsed);
  if (mobile || !sidebarDesktopCollapsed) {
    closeSidebarRailFlyout();
  } else {
    setSidebarRailFlyout(sidebarRailFlyoutSectionId);
  }
  syncSidebarToggleButtons();
  syncAllSidebarSectionAccessibility();
}

function renderMenu() {
  var nav = document.getElementById('sidebar-menu');
  if (!nav) return;
  initSidebarAccordionState();
  var sections = getVisibleSidebarSections();
  var html = '';
  var adminDividerRendered = false;
  var activeSectionId = menuGroupByPage(currentPage || '');
  html += '<div class="sidebar-menu-shell">';
  html +=
    '<button type="button" class="sidebar-menu-home' +
    (currentPage === SIDEBAR_HOME_PAGE ? ' is-active' : '') +
    '" data-page="' +
    SIDEBAR_HOME_PAGE +
    '" onclick="navigateTo(\'' +
    SIDEBAR_HOME_PAGE +
    '\')" aria-label="工作台">' +
    '<span class="sidebar-menu-home__icon">' +
    sidebarIconSvg('home') +
    '</span>' +
    '<span class="sidebar-menu-home__text">工作台</span>' +
    '</button>';
  for (var i = 0; i < sections.length; i++) {
    var section = sections[i];
    var sectionId = section.id;
    var panelId = 'sidebar-panel-' + sectionId;
    if (section.zone === 'admin' && !adminDividerRendered) {
      html += '<div class="sidebar-menu-divider" role="separator"><span class="sidebar-menu-divider__label">管理后台</span></div>';
      adminDividerRendered = true;
    }
    var expanded = !!sidebarAccordionState[sectionId];
    var railOpen = sidebarRailFlyoutSectionId === sectionId;
    var isActiveSection = activeSectionId === sectionId;
    var sectionClasses = ['sidebar-menu-section'];
    if (expanded) sectionClasses.push('expanded');
    if (railOpen) sectionClasses.push('sidebar-menu-section--rail-open');
    if (isActiveSection) sectionClasses.push('sidebar-menu-section--active');
    html += '<section class="' + sectionClasses.join(' ') + '" data-section-id="' + escapeHtml(sectionId) + '">';
    html +=
      '<button type="button" class="sidebar-menu-section-toggle" onclick="sidebarToggleSection(\'' +
      escapeJs(sectionId) +
      '\')" aria-expanded="' +
      (expanded ? 'true' : 'false') +
      '" aria-controls="' +
      escapeHtml(panelId) +
      '" aria-label="' +
      escapeHtml(section.title) +
      '">' +
      '<span class="sidebar-menu-section-toggle__icon">' +
      sidebarIconSvg(section.icon) +
      '</span>' +
      '<span class="sidebar-menu-section-toggle__body">' +
      '<span class="sidebar-menu-section-toggle__title">' +
      escapeHtml(section.title) +
      '</span>' +
      '</span>' +
      '<span class="sidebar-menu-section-toggle__chevron" aria-hidden="true">' +
      '<svg viewBox="0 0 20 20" fill="none"><path d="M5.5 7.5L10 12L14.5 7.5" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round"/></svg>' +
      '</span>' +
      '</button>';
    html += '<div id="' + escapeHtml(panelId) + '" class="sidebar-menu-section-panel"><div class="sidebar-menu-section-panel-inner">';
    html += '<div class="sidebar-menu-section-panel-head">' + escapeHtml(section.title) + '</div>';
    for (var j = 0; j < section.items.length; j++) {
      var key = section.items[j];
      html +=
        '<button type="button" class="sidebar-menu-link' +
        (currentPage === key ? ' is-active' : '') +
        '" data-page="' +
        escapeHtml(key) +
        '" onclick="navigateTo(\'' +
        escapeJs(key) +
        '\')">' +
        '<span class="sidebar-menu-link__label">' +
        escapeHtml(MENU_LABELS[key] || key) +
        '</span>' +
        '</button>';
    }
    html += '</div></div></section>';
  }
  html += '</div>';
  nav.innerHTML = html;
  syncSidebarLayoutState();
}

function setActiveMenu(key) {
  var nodes = document.querySelectorAll('.sidebar-menu-home[data-page], .sidebar-menu-link[data-page]');
  nodes.forEach(function (el) {
    el.classList.toggle('is-active', el.getAttribute('data-page') === key);
  });
  var groupId = menuGroupByPage(key);
  var sections = document.querySelectorAll('.sidebar-menu-section[data-section-id]');
  sections.forEach(function (sectionEl) {
    sectionEl.classList.toggle('sidebar-menu-section--active', !!groupId && sectionEl.getAttribute('data-section-id') === groupId);
  });
  closeSidebarRailFlyout();
  if (!groupId) {
    collapseOtherSidebarGroups('');
    return;
  }
  collapseOtherSidebarGroups(groupId);
  setSidebarGroupExpanded(groupId, true);
}

const SIDEBAR_COLLAPSED_KEY = 'sidebar_collapsed_v1';

function loadSidebarCollapsedPreference() {
  var v = localStorage.getItem(SIDEBAR_COLLAPSED_KEY);
  if (v === '1') return true;
  if (v === '0') return false;
  return window.innerWidth >= 1024 && window.innerWidth < 1280;
}

function applySidebarCollapsedState(collapsed) {
  sidebarDesktopCollapsed = !!collapsed;
  if (!sidebarDesktopCollapsed) {
    closeSidebarRailFlyout();
  }
  syncSidebarLayoutState();
}

function toggleSidebarCollapsed(ev) {
  if (ev) ev.stopPropagation();
  if (isSidebarMobileViewport()) {
    setSidebarMobileOpen(!sidebarMobileOpen);
    return;
  }
  var next = !sidebarDesktopCollapsed;
  localStorage.setItem(SIDEBAR_COLLAPSED_KEY, next ? '1' : '0');
  applySidebarCollapsedState(next);
}

