var ASSESSMENT_STATE_KEY = 'assessment_state_v1';

function clearAssessmentStateFromStorage() {
  try {
    sessionStorage.removeItem(ASSESSMENT_STATE_KEY);
  } catch (e) {}
}

function saveAssessmentStateToStorage() {
  try {
    var state = ensureAssessmentState();
    syncAssessmentStateFromSelectedSession(state);
    if (!state.recordId || state.finished) {
      clearAssessmentStateFromStorage();
      return;
    }
    var sessionByTaskId = {};
    Object.keys(state.sessionByTaskId || {}).forEach(function (taskId) {
      var session = normalizeAssessmentSession(state.sessionByTaskId[taskId]);
      if (!session.recordId || session.finished) return;
      sessionByTaskId[taskId] = {
        recordId: String(session.recordId || ''),
        conversationId: String(session.conversationId || ''),
        messages: Array.isArray(session.messages) ? session.messages.map(function (item) {
          return {
            role: String(item && item.role || 'system'),
            content: String(item && item.content || ''),
          };
        }) : [],
        coach: normalizeAssessmentCoach(session.coach),
        lastCoachAt: Number(session.lastCoachAt || 0),
        lastCoachSignature: String(session.lastCoachSignature || '').trim(),
        interactionPhase: String(session.interactionPhase || '').trim(),
        currentTaskMeta: session.currentTaskMeta && typeof session.currentTaskMeta === 'object'
          ? session.currentTaskMeta
          : null,
        expiresAt: session.expiresAt || '',
        durationMinutes: Number(session.durationMinutes || 0),
        examMode: session.examMode || '',
        scoreVisibility: session.scoreVisibility || '',
        paperDraftAnswers: session.paperDraftAnswers && typeof session.paperDraftAnswers === 'object'
          ? session.paperDraftAnswers
          : {},
      };
    });
    var serial = {
      ownerUserId: String(localStorage.getItem('userId') || ''),
      selectedTaskId: String(state.selectedTaskId || state.currentTaskId || ''),
      currentTaskId: String(state.currentTaskId || ''),
      recordId: String(state.recordId || ''),
      conversationId: String(state.conversationId || ''),
      messages: Array.isArray(state.messages) ? state.messages.map(function (item) {
        return {
          role: String(item && item.role || 'system'),
          content: String(item && item.content || ''),
        };
      }) : [],
      coach: normalizeAssessmentCoach(state.coach),
      lastCoachAt: Number(state.lastCoachAt || 0),
      lastCoachSignature: String(state.lastCoachSignature || '').trim(),
      interactionPhase: String(state.interactionPhase || '').trim(),
      currentTab: state.currentTab || 'current',
      currentTaskMeta: state.currentTaskMeta && typeof state.currentTaskMeta === 'object'
        ? state.currentTaskMeta
        : null,
      expiresAt: state.expiresAt || '',
      durationMinutes: Number(state.durationMinutes || 0),
      examMode: state.examMode || '',
      scoreVisibility: state.scoreVisibility || '',
      assessmentSummaryCollapsed: state.assessmentSummaryCollapsed !== false,
      paperDraftAnswers: state.paperDraftAnswers && typeof state.paperDraftAnswers === 'object'
        ? state.paperDraftAnswers
        : {},
      sessionByTaskId: sessionByTaskId,
    };
    sessionStorage.setItem(ASSESSMENT_STATE_KEY, JSON.stringify(serial));
  } catch (e) {}
}

function loadAssessmentStateFromStorage() {
  try {
    var raw = sessionStorage.getItem(ASSESSMENT_STATE_KEY);
    if (!raw) return;
    var obj = JSON.parse(raw);
    if (!obj || typeof obj !== 'object') return;
    var currentUserId = String(localStorage.getItem('userId') || '');
    var ownerUserId = String(obj.ownerUserId || '');
    if (ownerUserId && currentUserId && ownerUserId !== currentUserId) {
      clearAssessmentStateFromStorage();
      return;
    }
    if (!obj.recordId || obj.finished) {
      clearAssessmentStateFromStorage();
      return;
    }
    var selectedTaskId = String(obj.selectedTaskId || obj.currentTaskId || '').trim();
    var sessionByTaskId = {};
    if (obj.sessionByTaskId && typeof obj.sessionByTaskId === 'object') {
      Object.keys(obj.sessionByTaskId).forEach(function (taskId) {
        sessionByTaskId[taskId] = normalizeAssessmentSession(obj.sessionByTaskId[taskId]);
      });
    }
    if (selectedTaskId && !sessionByTaskId[selectedTaskId]) {
      sessionByTaskId[selectedTaskId] = normalizeAssessmentSession({
        recordId: String(obj.recordId || ''),
        conversationId: String(obj.conversationId || ''),
        messages: Array.isArray(obj.messages) ? obj.messages : [],
        coach: normalizeAssessmentCoach(obj.coach),
        lastCoachAt: Number(obj.lastCoachAt || 0),
        lastCoachSignature: String(obj.lastCoachSignature || '').trim(),
        interactionPhase: String(obj.interactionPhase || '').trim(),
        currentTaskMeta: obj.currentTaskMeta && typeof obj.currentTaskMeta === 'object' ? obj.currentTaskMeta : null,
        expiresAt: obj.expiresAt || '',
        durationMinutes: Number(obj.durationMinutes || 0),
        examMode: obj.examMode || '',
        scoreVisibility: obj.scoreVisibility || '',
        paperDraftAnswers: obj.paperDraftAnswers && typeof obj.paperDraftAnswers === 'object' ? obj.paperDraftAnswers : {},
      });
    }
    moduleState.assessment = Object.assign({}, moduleState.assessment, {
      selectedTaskId: selectedTaskId,
      currentTaskId: selectedTaskId,
      recordId: String(obj.recordId || ''),
      conversationId: String(obj.conversationId || ''),
      messages: Array.isArray(obj.messages) ? obj.messages : [],
      coach: normalizeAssessmentCoach(obj.coach),
      lastCoachAt: Number(obj.lastCoachAt || 0),
      lastCoachSignature: String(obj.lastCoachSignature || '').trim(),
      interactionPhase: String(obj.interactionPhase || '').trim(),
      currentTab: obj.currentTab || 'current',
      currentTaskMeta: obj.currentTaskMeta && typeof obj.currentTaskMeta === 'object' ? obj.currentTaskMeta : null,
      expiresAt: obj.expiresAt || '',
      durationMinutes: Number(obj.durationMinutes || 0),
      examMode: obj.examMode || '',
      scoreVisibility: obj.scoreVisibility || '',
      assessmentSummaryCollapsed: obj.assessmentSummaryCollapsed !== false,
      paperDraftAnswers: obj.paperDraftAnswers && typeof obj.paperDraftAnswers === 'object' ? obj.paperDraftAnswers : {},
      sessionByTaskId: sessionByTaskId,
      starting: false,
      sending: false,
      finishing: false,
      finished: false,
      resultData: null,
    });
    syncAssessmentStateFromSelectedSession(moduleState.assessment);
  } catch (e) {}
}

