var INITIAL_MODULE_STATE = JSON.parse(JSON.stringify(moduleState));
var INITIAL_REQUEST_STATE = JSON.parse(JSON.stringify(requestState));

function cloneInitialState(value) {
  return JSON.parse(JSON.stringify(value || {}));
}

function resetSessionUiState() {
  moduleState = cloneInitialState(INITIAL_MODULE_STATE);
  requestState = cloneInitialState(INITIAL_REQUEST_STATE);
  currentPage = '';
  sidebarAccordionState = {};
  sidebarMobileOpen = false;
  sidebarRailFlyoutSectionId = '';
  try {
    sessionStorage.removeItem(PRACTICE_STATE_KEY);
    sessionStorage.removeItem(ASSESSMENT_STATE_KEY);
  } catch (e) {}
}

function setRequestLoading(key, loading) {
  if (!requestState[key]) return;
  requestState[key].loading = !!loading;
}

function setRequestError(key, errorText) {
  if (!requestState[key]) return;
  requestState[key].error = String(errorText || '').trim();
}

function clearRequestError(key) {
  if (!requestState[key]) return;
  requestState[key].error = '';
}

function requestLoading(key) {
  return !!(requestState[key] && requestState[key].loading);
}

function requestError(key) {
  return (requestState[key] && requestState[key].error) ? requestState[key].error : '';
}

function buttonDisabledAttrByState(state) {
  return state ? ' disabled aria-busy="true"' : '';
}

function buttonLabelByState(state, idleText, loadingText) {
  return state ? loadingText : idleText;
}

function renderRequestBanner(key, loadingText) {
  var loading = requestLoading(key);
  var err = requestError(key);
  if (loading) {
    return '<div class="demo-banner demo-banner-loading">' +
      '<span class="demo-spinner" aria-hidden="true"></span>' +
      '<span>' + escapeHtml(loadingText || '处理中…') + '</span>' +
    '</div>';
  }
  if (err) {
    return '<div class="demo-banner demo-banner-error">' +
      '<div class="flex-1 min-w-0">' +
        '<p class="font-medium">请求失败</p>' +
        '<p class="text-xs mt-1 leading-5">' + escapeHtml(err) + '</p>' +
      '</div>' +
      '<button type="button" onclick="clearRequestError(\'' + key + '\'); rerenderCurrentPage();" class="demo-retry-btn">关闭</button>' +
    '</div>';
  }
  return '';
}

function renderAiTypingBubble(extraBubbleClass) {
  return (
    '<div class="practice-msg-row practice-msg-row--ai">' +
      '<div class="practice-bubble practice-bubble--ai ai-typing-bubble ' + (extraBubbleClass || '') + '" aria-label="AI 正在回复" role="status">' +
        '<span class="ai-typing-dot" aria-hidden="true"></span>' +
        '<span class="ai-typing-dot" aria-hidden="true"></span>' +
        '<span class="ai-typing-dot" aria-hidden="true"></span>' +
      '</div>' +
    '</div>'
  );
}

function renderUnifiedChatTranscript(messages, isSending, extraAiBubbleClass) {
  var items = Array.isArray(messages) ? messages : [];
  var aiClass = extraAiBubbleClass ? ' ' + extraAiBubbleClass : '';
  var html = '<div class="practice-msg-stack">';
  for (var i = 0; i < items.length; i++) {
    var msg = items[i] || {};
    var role = String(msg.role || 'system');
    var content = escapeHtml((msg && msg.content) || '');
    if (role === 'user') {
      html +=
        '<div class="practice-msg-row practice-msg-row--user">' +
          '<div class="practice-bubble practice-bubble--user">' +
            '<p class="practice-bubble-text">' + content + '</p>' +
          '</div>' +
        '</div>';
      continue;
    }
    if (role === 'examiner' || role === 'assistant') {
      html +=
        '<div class="practice-msg-row practice-msg-row--ai">' +
          '<div class="practice-bubble practice-bubble--ai' + aiClass + '">' +
            '<p class="practice-bubble-text">' + content + '</p>' +
          '</div>' +
        '</div>';
      continue;
    }
    html +=
      '<div class="practice-msg-row practice-msg-row--hint">' +
        '<div class="practice-bubble practice-bubble--hint">' +
          '<p class="practice-bubble-text">' + content + '</p>' +
        '</div>' +
      '</div>';
  }
  if (isSending) {
    html += renderAiTypingBubble(extraAiBubbleClass || '');
  }
  html += '</div>';
  return html;
}

loadAssessmentStateFromStorage();

var PRACTICE_STATE_KEY = 'practice_state_v2';

function savePracticeStateToStorage() {
  try {
    var p = moduleState.practice || {};
    var serial = JSON.parse(JSON.stringify(p));
    delete serial.abilityLastDelta;
    sessionStorage.setItem(PRACTICE_STATE_KEY, JSON.stringify(serial));
  } catch (e) {}
}

function loadPracticeStateFromStorage() {
  try {
    var raw = sessionStorage.getItem(PRACTICE_STATE_KEY);
    if (!raw) return;
    var obj = JSON.parse(raw);
    if (!obj || typeof obj !== 'object') return;
    delete obj.abilityLastDelta;
    moduleState.practice = Object.assign({}, moduleState.practice, obj);
    moduleState.practice.abilityLastDelta = null;
    var pc = moduleState.practice.practiceCardCollapsed;
    if (!pc || typeof pc !== 'object') {
      moduleState.practice.practiceCardCollapsed = { config: false, feedback: false, ability: false };
    } else {
      moduleState.practice.practiceCardCollapsed = Object.assign(
        { config: false, feedback: false, ability: false },
        pc
      );
    }
  } catch (e) {}
}

loadPracticeStateFromStorage();

function practiceModuleLabel(moduleCode) {
  var code = String(moduleCode || '').trim();
  for (var i = 0; i < PRACTICE_MODULE_OPTIONS.length; i++) {
    if (PRACTICE_MODULE_OPTIONS[i].value === code) return PRACTICE_MODULE_OPTIONS[i].label;
  }
  return code || '未选择模块';
}

function normalizeModuleIndexItems(items) {
  var raw = Array.isArray(items) ? items : [];
  var map = {};
  for (var i = 0; i < raw.length; i++) {
    var item = raw[i] && typeof raw[i] === 'object' ? raw[i] : {};
    var code = String(item.module_code || '').trim();
    if (!code) continue;
    map[code] = {
      module_code: code,
      module_name: item.module_name || practiceModuleLabel(code),
      learning_index: Number(item.learning_index != null ? item.learning_index : 0),
      practice_index: Number(item.practice_index != null ? item.practice_index : 0),
      assessment_index: Number(item.assessment_index != null ? item.assessment_index : 0),
      overall_index: Number(item.overall_index != null ? item.overall_index : 0),
    };
  }
  var out = [];
  for (var j = 0; j < PRACTICE_MODULE_OPTIONS.length; j++) {
    var option = PRACTICE_MODULE_OPTIONS[j];
    out.push(map[option.value] || {
      module_code: option.value,
      module_name: option.label,
      learning_index: 0,
      practice_index: 0,
      assessment_index: 0,
      overall_index: 0,
    });
  }
  return out;
}

function moduleIndexCurrentRole() {
  return normalizeRole(localStorage.getItem('role') || '');
}

function moduleIndexCanPickUsers() {
  return isManagementRole(moduleIndexCurrentRole());
}

function moduleIndexCanPickStores() {
  return moduleIndexCurrentRole() === 'admin';
}

function getModuleIndexScopedUsers() {
  var state = moduleState.moduleIndex || {};
  var users = Array.isArray(state.users) ? state.users.slice() : [];
  var storeId = String(state.selectedStoreId || '').trim();
  if (!storeId) return users;
  return users.filter(function (user) {
    return String(user && user.store_id || '').trim() === storeId;
  });
}

function pickModuleIndexDefaultUserId(users) {
  var list = Array.isArray(users) ? users : [];
  var selfId = String(localStorage.getItem('userId') || '').trim();
  for (var i = 0; i < list.length; i++) {
    if (String(list[i] && list[i].id || '').trim() === selfId) return selfId;
  }
  return list.length ? String(list[0] && list[0].id || '').trim() : '';
}

async function loadModuleIndexFilters(options) {
  options = options || {};
  var state = moduleState.moduleIndex || {};
  var role = moduleIndexCurrentRole();
  state.viewerRole = role;
  if (!moduleIndexCanPickUsers()) {
    state.selectedUserId = String(localStorage.getItem('userId') || '').trim();
    state.selectedStoreId = String(localStorage.getItem('store_id') || '').trim();
    state.filtersLoaded = true;
    return;
  }
  if (state.filtersLoaded && !options.force) {
    if (!state.selectedStoreId && !moduleIndexCanPickStores()) {
      state.selectedStoreId = String(localStorage.getItem('store_id') || '').trim();
    }
    return;
  }
  try {
    if (moduleIndexCanPickStores()) {
      var storesRes = await apiFetch('/api/stores', { method: 'GET' });
      state.stores = Array.isArray(storesRes && storesRes.data && storesRes.data.items) ? storesRes.data.items : [];
      if (!state.selectedStoreId) state.selectedStoreId = '';
    } else {
      state.stores = [];
      state.selectedStoreId = String(localStorage.getItem('store_id') || '').trim();
    }
    var usersRes = await apiFetch('/api/users', { method: 'GET' });
    state.users = Array.isArray(usersRes && usersRes.data && usersRes.data.items) ? usersRes.data.items : [];
    state.filtersLoaded = true;
  } catch (e) {
    state.filtersLoaded = true;
    state.stores = state.stores || [];
    state.users = state.users || [];
    state.selectedUserId = state.selectedUserId || String(localStorage.getItem('userId') || '').trim();
  }
}

async function loadModuleIndexData(options) {
  options = options || {};
  var state = moduleState.moduleIndex;
  await loadModuleIndexFilters();
  var targetUserId = String(localStorage.getItem('userId') || '').trim();
  state.emptyHint = '';
  if (moduleIndexCanPickUsers()) {
    var scopedUsers = getModuleIndexScopedUsers();
    if (!state.selectedUserId || !scopedUsers.some(function (user) { return String(user.id || '') === String(state.selectedUserId || ''); })) {
      state.selectedUserId = pickModuleIndexDefaultUserId(scopedUsers);
    }
    if (!state.selectedUserId) {
      state.items = normalizeModuleIndexItems([]);
      state.loaded = true;
      state.lastLoadedUserId = '';
      state.selectedUserName = '';
      state.viewingStoreId = String(state.selectedStoreId || '').trim();
      state.viewingStoreName = '';
      state.emptyHint = state.selectedStoreId ? '当前门店暂无可查看员工' : '暂无可查看员工';
      setRequestLoading('moduleIndex', false);
      clearRequestError('moduleIndex');
      rerenderCurrentPage();
      return state.items || [];
    }
    targetUserId = String(state.selectedUserId || '').trim();
  }
  if (requestLoading('moduleIndex') && !options.force) return state.items || [];
  if (state.loaded && state.lastLoadedUserId === targetUserId && !options.force) return state.items || [];
  setRequestLoading('moduleIndex', true);
  if (!options.keepError) clearRequestError('moduleIndex');
  try {
    var data = await fetchModuleIndexes({ userId: targetUserId });
    state.items = normalizeModuleIndexItems(data.items || []);
    state.loaded = true;
    state.lastLoadedUserId = targetUserId;
    state.viewerRole = String(data.viewer_role || state.viewerRole || moduleIndexCurrentRole());
    state.selectedUserId = String(data.selected_user_id || state.selectedUserId || targetUserId);
    state.selectedUserName = String(data.selected_user_name || '').trim();
    state.viewingStoreId = String(data.selected_store_id || '').trim();
    state.viewingStoreName = String(data.selected_store_name || '').trim();
    state.emptyHint = '';
    setRequestLoading('moduleIndex', false);
    rerenderCurrentPage();
  } catch (e) {
    state.loaded = true;
    state.items = state.items || [];
    state.lastLoadedUserId = targetUserId;
    setRequestLoading('moduleIndex', false);
    setRequestError('moduleIndex', e.message || '模块指数加载失败');
    rerenderCurrentPage();
  }
  return state.items || [];
}

function onModuleIndexStoreChange(storeId) {
  var state = moduleState.moduleIndex || {};
  state.selectedStoreId = String(storeId || '').trim();
  state.selectedUserId = '';
  state.loaded = false;
  loadModuleIndexData({ force: true });
}

function onModuleIndexUserChange(userId) {
  var state = moduleState.moduleIndex || {};
  state.selectedUserId = String(userId || '').trim();
  state.loaded = false;
  loadModuleIndexData({ force: true });
}

