function getGrowthCoursePriorityMeta(priority) {
  var raw = String(priority || '').trim().toLowerCase();
  if (raw === 'high' || raw === '高' || raw === '高优先级') {
    return { key: 'high', label: '高优先级', cls: 'gp-course-chip gp-course-chip--high' };
  }
  if (raw === 'low' || raw === '低' || raw === '低优先级') {
    return { key: 'low', label: '低优先级', cls: 'gp-course-chip gp-course-chip--low' };
  }
  return { key: 'medium', label: '中优先级', cls: 'gp-course-chip gp-course-chip--medium' };
}

function buildGrowthCourseFallback(course, priorityKey) {
  var title = String((course && course.course_name) || '').trim();
  var focus = title ? ('围绕“' + title + '”补齐关键话术和实际接待动作') : '围绕当前计划中的关键短板做专项补齐';
  var action = priorityKey === 'high'
    ? '建议本周优先完成课程学习，并安排 2 次针对性陪练'
    : priorityKey === 'low'
      ? '建议在核心训练完成后穿插学习，并结合日常接待复盘'
      : '建议在高优先级主题完成后 1 周内补上，并安排至少 1 次复练';
  var outcome = priorityKey === 'high'
    ? '目标是尽快把关键话术说完整，并在门店现场稳定应用'
    : '目标是把新动作固化为稳定习惯，减少训练后回落';
  return {
    focus: focus,
    action: action,
    outcome: outcome,
  };
}

function renderGrowthCourseItem(course, index) {
  var c = course && typeof course === 'object' ? course : { course_name: String(course || '') };
  var title = String(c.course_name || '').trim() || ('培训主题 ' + (index + 1));
  var priorityMeta = getGrowthCoursePriorityMeta(c.priority);
  var fallback = buildGrowthCourseFallback(c, priorityMeta.key);
  var reason = String(c.recommendation_reason || c.description || '').trim();
  var focus = String(c.training_focus || c.focus || '').trim() || fallback.focus;
  var action = String(c.recommended_action || c.action || '').trim() || fallback.action;
  var outcome = String(c.expected_outcome || c.outcome || '').trim() || fallback.outcome;
  var code = String(c.course_code || '').trim();
  var html = '<div class="gp-result__item gp-course-item">';
  html += '<div class="gp-course-item__head">';
  html += '<div class="gp-course-item__title-wrap">';
  html += '<div class="gp-course-item__title">' + escapeHtml(title) + '</div>';
  if (code) {
    html += '<div class="gp-course-item__code">课程编号：' + escapeHtml(code) + '</div>';
  }
  html += '</div>';
  html += '<span class="' + priorityMeta.cls + '">' + escapeHtml(priorityMeta.label) + '</span>';
  html += '</div>';
  if (reason) {
    html += '<div class="gp-course-item__detail"><span class="gp-course-item__detail-label">建议原因</span>' + escapeHtml(reason) + '</div>';
  }
  html += '<div class="gp-course-item__detail"><span class="gp-course-item__detail-label">训练重点</span>' + escapeHtml(focus) + '</div>';
  html += '<div class="gp-course-item__detail"><span class="gp-course-item__detail-label">建议安排</span>' + escapeHtml(action) + '</div>';
  html += '<div class="gp-course-item__detail"><span class="gp-course-item__detail-label">预期结果</span>' + escapeHtml(outcome) + '</div>';
  html += '</div>';
  return html;
}

