function renderUnlockMatrix(unlocks) {
  if (!unlocks) return '';
  var modules = [
    { code: 'growth_plan', name: '成长计划', page: 'growth_plan' },
    { code: 'practical_training', name: '智能陪练', page: 'practical_training' },
    { code: 'on_duty_assistant', name: '在岗助手', page: 'on_duty_assistant' },
    { code: 'knowledge_qa', name: '知识问答', page: 'knowledge_qa' },
    { code: 'assessment', name: '考试中心', page: 'assessment' },
    { code: 'dashboard', name: '培训奖金', page: 'competition' },
    { code: 'quick_query', name: '一句话查询', page: 'quick_query' },
  ];
  var html = '<section class="gp-card"><div class="gp-card__body gp-card__body--airy">';
  html += '<div class="gp-section-head"><h2 class="gp-section-head__title">模块解锁</h2></div>';
  html += '<div class="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-3">';
  for (var i = 0; i < modules.length; i++) {
    var m = modules[i];
    var unlocked = !!unlocks[m.code];
    if (unlocked) {
      html += '<button type="button" onclick="navigateTo(\'' + m.page + '\')" class="flex flex-col items-center justify-center p-3 rounded-xl border-2 border-green-200 bg-green-50/60 hover:bg-green-100/80 transition-colors cursor-pointer text-center">';
      html += '<div class="w-8 h-8 rounded-full bg-green-500 flex items-center justify-center mb-1.5">';
      html += '<svg class="w-4 h-4 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M5 13l4 4L19 7"/></svg>';
      html += '</div>';
      html += '<span class="text-xs font-medium text-green-800">' + escapeHtml(m.name) + '</span>';
      html += '<span class="text-[10px] text-green-500 mt-0.5">已解锁</span>';
      html += '</button>';
    } else {
      var unlockHint = (m.code === 'practical_training' || m.code === 'on_duty_assistant' || m.code === 'knowledge_qa') ? '通过阶段1后解锁' : '通过阶段2后解锁';
      html += '<div class="flex flex-col items-center justify-center p-3 rounded-xl border-2 border-gray-200 bg-gray-50/60 text-center" title="' + unlockHint + '">';
      html += '<div class="w-8 h-8 rounded-full bg-gray-300 flex items-center justify-center mb-1.5">';
      html += '<svg class="w-4 h-4 text-gray-500" fill="currentColor" viewBox="0 0 20 20"><path fill-rule="evenodd" d="M5 9V7a5 5 0 0110 0v2a2 2 0 012 2v5a2 2 0 01-2 2H5a2 2 0 01-2-2v-5a2 2 0 012-2zm8-2v2H7V7a3 3 0 016 0z" clip-rule="evenodd"/></svg>';
      html += '</div>';
      html += '<span class="text-xs font-medium text-gray-400">' + escapeHtml(m.name) + '</span>';
      html += '<span class="text-[10px] text-gray-300 mt-0.5">' + escapeHtml(unlockHint) + '</span>';
      html += '</div>';
    }
  }
  html += '</div></div></section>';
  return html;
}

function renderStageTimeline(stageNo, stageStatus) {
  var stages = [
    { no: 1, name: '基础认知', shortName: '阶段1' },
    { no: 2, name: '销售转化与上岗', shortName: '阶段2' },
  ];
  var html = '<section class="gp-card"><div class="gp-card__body gp-card__body--airy">';
  html += '<div class="gp-section-head"><h2 class="gp-section-head__title">培训阶段</h2></div>';
  html += '<div class="flex items-start justify-between max-w-lg mx-auto py-4">';
  for (var i = 0; i < stages.length; i++) {
    var st = stages[i];
    var isCurrent = (st.no === stageNo);
    var isPast = (st.no < stageNo);
    var isFuture = (st.no > stageNo);
    var iconHtml = '';
    var circleClass = 'w-11 h-11 rounded-full flex items-center justify-center text-sm font-bold border-2 transition-all ';
    if (isPast || (isCurrent && stageStatus === 'passed')) {
      circleClass += 'bg-green-500 border-green-500 text-white';
      iconHtml = '<svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M5 13l4 4L19 7"/></svg>';
    } else if (isCurrent && stageStatus === 'active') {
      circleClass += 'bg-blue-500 border-blue-500 text-white animate-pulse';
      iconHtml = '<span class="text-base font-bold">' + st.no + '</span>';
    } else if (isCurrent && stageStatus === 'waiting_review') {
      circleClass += 'bg-amber-400 border-amber-400 text-white';
      iconHtml = '<svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>';
    } else if (isCurrent && stageStatus === 'failed') {
      circleClass += 'bg-red-500 border-red-500 text-white';
      iconHtml = '<svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M6 18L18 6M6 6l12 12"/></svg>';
    } else {
      circleClass += 'bg-gray-100 border-gray-300 text-gray-400';
      iconHtml = '<svg class="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path fill-rule="evenodd" d="M5 9V7a5 5 0 0110 0v2a2 2 0 012 2v5a2 2 0 01-2 2H5a2 2 0 01-2-2v-5a2 2 0 012-2zm8-2v2H7V7a3 3 0 016 0z" clip-rule="evenodd"/></svg>';
    }
    html += '<div class="flex flex-col items-center relative z-10 min-w-[80px]">';
    html += '<div class="' + circleClass + '">' + iconHtml + '</div>';
    html += '<span class="text-xs font-semibold mt-2 ' + (isFuture ? 'text-gray-400' : 'text-gray-700') + '">' + escapeHtml(st.shortName) + '</span>';
    html += '<span class="text-xs ' + (isFuture ? 'text-gray-300' : 'text-gray-500') + '">' + escapeHtml(st.name) + '</span>';
    html += '</div>';
    if (i < stages.length - 1) {
      var lineColor = isPast || (isCurrent && stageStatus === 'passed') ? 'bg-green-400' : 'bg-gray-200';
      html += '<div class="flex-1 flex items-center justify-center pt-5">';
      html += '<div class="h-1 w-full rounded-full ' + lineColor + '"></div>';
      html += '</div>';
    }
  }
  html += '</div></div></section>';
  return html;
}

function renderStageInfoCard() {
  var s = moduleState.growth;
  var cycle = s.cycleProgress || {};
  var stageNo = s.currentStageNo || 0;
  var stageStatus = s.stageStatus || '';
  if (!stageNo) return '';

  var totalDays = Number(cycle.total_days || 7);
  var currentDay = Number(cycle.current_day || 0);
  var progressPct = totalDays > 0 ? Math.min(100, Math.round(currentDay * 100 / totalDays)) : 0;

  var statusLabel = '';
  var statusBadge = '';
  if (stageStatus === 'active') {
    statusLabel = '进行中';
    statusBadge = 'inline-flex items-center rounded-full bg-blue-50 border border-blue-200 px-2.5 py-0.5 text-xs font-medium text-blue-700';
  } else if (stageStatus === 'waiting_review') {
    statusLabel = '等待评估';
    statusBadge = 'inline-flex items-center rounded-full bg-amber-50 border border-amber-200 px-2.5 py-0.5 text-xs font-medium text-amber-700';
  } else if (stageStatus === 'passed') {
    statusLabel = '已通过';
    statusBadge = 'inline-flex items-center rounded-full bg-green-50 border border-green-200 px-2.5 py-0.5 text-xs font-medium text-green-700';
  } else if (stageStatus === 'failed') {
    statusLabel = '未通过';
    statusBadge = 'inline-flex items-center rounded-full bg-red-50 border border-red-200 px-2.5 py-0.5 text-xs font-medium text-red-700';
  }

  var html = '<section class="gp-card"><div class="gp-card__body gp-card__body--airy">';
  html += '<div class="flex items-center justify-between mb-3">';
  html += '<div>';
  html += '<h3 class="text-sm font-semibold text-gray-800">' + escapeHtml(s.currentStageName || ('阶段' + stageNo)) + '</h3>';
  html += '<p class="text-xs text-gray-500 mt-0.5">第 ' + currentDay + ' / ' + totalDays + ' 天</p>';
  html += '</div>';
  if (statusLabel) {
    html += '<span class="' + statusBadge + '">' + escapeHtml(statusLabel) + '</span>';
  }
  html += '</div>';
  html += '<div class="w-full bg-gray-100 rounded-full h-2 mb-2">';
  html += '<div class="h-2 rounded-full transition-all ' + (stageStatus === 'passed' ? 'bg-green-500' : 'bg-blue-500') + '" style="width:' + progressPct + '%"></div>';
  html += '</div>';
  html += '<p class="text-xs text-gray-400">完成率 ' + progressPct + '%</p>';

  if (stageStatus === 'waiting_review') {
    html += '<div class="mt-3 p-3 rounded-xl bg-amber-50 border border-amber-100">';
    html += '<p class="text-xs text-amber-700 font-medium">所有任务已完成，等待管理员进行阶段评估</p>';
    html += '</div>';
  } else if (stageStatus === 'passed') {
    html += '<div class="mt-3 p-3 rounded-xl bg-green-50 border border-green-100">';
    html += '<p class="text-xs text-green-700 font-medium">恭喜！阶段评估已通过，下一阶段已解锁</p>';
    html += '</div>';
  } else if (stageStatus === 'failed') {
    html += '<div class="mt-3 p-3 rounded-xl bg-red-50 border border-red-100">';
    html += '<p class="text-xs text-red-700 font-medium">阶段评估未通过，系统已安排补训任务，请继续努力</p>';
    html += '</div>';
  }

  if ((growthViewerIsManager() || growthViewerRole() === 'admin') && stageStatus === 'waiting_review' && cycle.cycle_id) {
    html += '<div class="mt-3"><button type="button" onclick="submitStageReview()" class="gp-btn gp-btn--sm">发起阶段评估</button></div>';
  }

  html += '</div></section>';
  return html;
}

async function submitStageReview() {
  var s = moduleState.growth;
  var cycle = s.cycleProgress || {};
  var cycleId = cycle.cycle_id || '';
  if (!cycleId) {
    showToast('找不到当前阶段训练', 'error');
    return;
  }
  if (!confirm('确认评估？')) return;
  try {
    var json = await apiFetch('/api/training-cycle/review-stage', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ cycle_id: cycleId }),
    });
    if (json.code === 200 || json.code === 0) {
      var d = json.data || {};
      var msg = d.is_pass ? '阶段评估通过！得分: ' + (d.review_score || '--') : '阶段评估未通过，得分: ' + (d.review_score || '--');
      showToast(msg, d.is_pass ? 'success' : 'error');
      s.onboardingStatusLoaded = false;
      s.cycleProgress = null;
      await loadOnboardingStatus();
    } else {
      showToast(json.message || '阶段评估失败', 'error');
    }
  } catch (e) {
    showToast('阶段评估请求失败', 'error');
  }
}

