function openGrowthTaskDestination(routePage, routeTab, moduleCode) {
  var nextPage = String(routePage || '').trim() || 'home';
  var nextTab = String(routeTab || '').trim();
  var mc = String(moduleCode || '').trim();
  if (nextPage === 'growth_plan' && nextTab) {
    moduleState.growth.activeTab = nextTab;
  }
  if (nextPage === 'practical_training' && mc) {
    moduleState.practice.module_code = mc;
    moduleState.practice.scene_code = _MODULE_SCENE_MAP[mc] || 'jewelry_recommendation';
    moduleState.practice.difficulty_level = 'standard';
  }
  navigateTo(nextPage);
}

function goPracticeFromTask(moduleCode, sceneCode, difficulty) {
  var mc = String(moduleCode || '').trim();
  var sc = String(sceneCode || '').trim();
  var df = String(difficulty || '').trim();
  if (mc) moduleState.practice.module_code = mc;
  if (sc) moduleState.practice.scene_code = sc;
  if (df) moduleState.practice.difficulty_level = df;
  navigateTo('practical_training');
}

function renderGrowthTaskList() {
  var s = moduleState.growth;
  var tasks = Array.isArray(s.dailyTasks) ? s.dailyTasks : [];
  var manualLoading = requestLoading('growthTaskManualCheck');
  if (!tasks.length) {
    return renderEmptyState('任务');
  }
  var html = '<section class="gp-card">' +
    '<div class="gp-card__body">' +
      '<div class="gp-section-head">' +
        '<h2 class="gp-section-head__title">7 天每日任务</h2>' +
      '</div>' +
      '<div class="gp-task-board">';
  for (var i = 0; i < tasks.length; i++) {
    var task = tasks[i] || {};
    var status = String(task.status || '');
    var done = status === 'done';
    var locked = status === 'locked';
    var branch = String(task.branch || '');
    var branchClass = 'gp-branch-badge';
    if (branch === 'assessment') branchClass += ' gp-branch-badge--warn';
    if (branch === 'practice') branchClass += ' gp-branch-badge--blue';
    html += '<article class="gp-task-card' + (done ? ' gp-task-card--done' : '') + (locked ? ' gp-task-card--locked' : '') + '">' +
      '<div class="gp-task-card__top">' +
        '<div class="gp-task-check' + (done ? ' gp-task-check--done' : '') + (locked ? ' gp-task-check--locked' : '') + '">' + (done ? '✓' : (locked ? '锁' : String(task.day_index || i + 1))) + '</div>' +
        '<div class="gp-task-card__main">' +
          '<div class="gp-task-card__meta">' +
            '<span class="' + branchClass + '">' + escapeHtml(branch === 'assessment' ? '考核' : (branch === 'practice' ? '练习' : '成长')) + '</span>' +
            '<span class="gp-task-card__day">第 ' + escapeHtml(String(task.day_index || i + 1)) + ' 天</span>' +
            '<span class="gp-task-card__state">' + escapeHtml(task.done_label || '待完成') + '</span>' +
          '</div>' +
          '<h3 class="gp-task-card__title">' + escapeHtml(task.title || '') + '</h3>' +
          '<p class="gp-task-card__desc">' + escapeHtml(task.description || '') + '</p>' +
          '<div class="gp-task-card__foot">' +
            '<span class="gp-task-card__progress">' + escapeHtml(locked ? (task.unlock_hint || '待解锁') : ('系统进度 ' + (task.progress_text || '--'))) + '</span>' +
            (!locked && task.route_page ? '<button type="button" class="gp-mini-link" onclick="openGrowthTaskDestination(\'' + escapeJs(task.route_page || '') + '\',\'' + escapeJs(task.route_tab || '') + '\',\'' + escapeJs(task.module_code || '') + '\')">' + escapeHtml(task.route_label || '去完成') + '</button>' : '') +
          '</div>' +
          (task.manual_note ? '<div class="gp-task-card__note">备注：' + escapeHtml(task.manual_note) + '</div>' : '') +
        '</div>' +
      '</div>' +
      (((task.manager_can_check || task.manual_checked) && !locked) ? '<div class="gp-task-card__actions"><button type="button" class="gp-btn gp-btn--sm gp-btn--ghost" onclick="submitGrowthTaskManualCheck(\'' + escapeHtml(task.task_code || '') + '\', ' + (task.manual_checked ? 'false' : 'true') + ')"' + buttonDisabledAttrByState(manualLoading) + '>' + escapeHtml(task.manual_checked ? '取消补记' : '管理层补记完成') + '</button></div>' : '') +
    '</article>';
  }
  html += '</div></div></section>';
  return html;
}

