function _detectPracticeEmotion(chatResult) {
  var conv = chatResult && chatResult.conversation ? chatResult.conversation : [];
  var lastAiMsg = '';
  for (var i = conv.length - 1; i >= 0; i--) {
    if (conv[i].role !== 'user') { lastAiMsg = conv[i].content || ''; break; }
  }
  if (!lastAiMsg) return null;

  var positive = ['很好', '不错', '正确', '非常好', '太棒了', '有进步', '说得对', '恰当', '专业', '到位'];
  var negative = ['不太合适', '可以改进', '建议你', '但是', '不足', '需要加强', '避免', '需要注意', '不太', '还需'];

  var posCount = 0, negCount = 0;
  for (var p = 0; p < positive.length; p++) {
    if (lastAiMsg.indexOf(positive[p]) >= 0) posCount++;
  }
  for (var n = 0; n < negative.length; n++) {
    if (lastAiMsg.indexOf(negative[n]) >= 0) negCount++;
  }

  if (posCount > negCount + 1) return 'celebrate';
  if (posCount > 0 && negCount === 0) return 'agree';
  if (negCount > posCount) return 'think';
  if (negCount > 0) return 'encourage';
  return null;
}

function _detectKnowledgeQaEmotion(answerBrief, answerReason, answerSubtype) {
  var text = [answerBrief, answerReason].filter(Boolean).join(' ');
  if (!text) return { pose: 'agree', emotion: 'calm' };

  var positive = ['正确', '对的', '没错', '很好', '准确', '非常好'];
  var corrective = ['不对', '错误', '注意', '避免', '不可以', '千万别', '误解'];
  var negCount = 0, posCount = 0;
  for (var i = 0; i < positive.length; i++) if (text.indexOf(positive[i]) >= 0) posCount++;
  for (var j = 0; j < corrective.length; j++) if (text.indexOf(corrective[j]) >= 0) negCount++;

  if (posCount > negCount + 1) return { pose: 'celebrate', emotion: 'happy' };
  if (posCount > 0 && negCount === 0) return { pose: 'agree', emotion: 'calm' };
  if (negCount > posCount) return { pose: 'encourage', emotion: 'calm' };
  if (negCount > 0) return { pose: 'think', emotion: 'calm' };
  return { pose: 'agree', emotion: 'calm' };
}

function normalizePracticeTurnFeedback(raw) {
  var obj = raw && typeof raw === 'object' ? raw : {};
  var out = {
    intent_label: String(obj.intent_label || '').trim(),
    intent_reason: String(obj.intent_reason || '').trim(),
    customer_state: String(obj.customer_state || '').trim(),
    mentor_comment: String(obj.mentor_comment || '').trim(),
    next_action: String(obj.next_action || '').trim(),
    next_question: String(obj.next_question || '').trim(),
    voice_advice: String(obj.voice_advice || '').trim(),
    risk_flag: String(obj.risk_flag || '').trim(),
  };
  if (!out.intent_label && !out.intent_reason && !out.customer_state && !out.mentor_comment &&
      !out.next_action && !out.next_question && !out.voice_advice && !out.risk_flag) {
    return null;
  }
  return out;
}

function getLatestPracticeTurnFeedback(data) {
  var direct = normalizePracticeTurnFeedback(data && data.turn_feedback);
  if (direct) return direct;
  var conv = data && Array.isArray(data.conversation) ? data.conversation : [];
  for (var i = conv.length - 1; i >= 0; i--) {
    var item = conv[i];
    if (!item || item.role !== 'assistant') continue;
    var feedback = normalizePracticeTurnFeedback(item.turn_feedback);
    if (feedback) return feedback;
  }
  return null;
}

function resolvePracticePageSpeechText() {
  var s = moduleState.practice || {};
  var mentorText = String(s.mentorSentence || '').trim();
  if (s.evaluationResult && mentorText) return mentorText;
  var turnVoice = String(s.latestTurnVoiceAdvice || '').trim();
  if (turnVoice) return turnVoice;
  return String(s.lastDigitalHumanSpeech || '').trim();
}

function applyPracticeChatData(data, meta) {
  var s = moduleState.practice;
  s.chatResult = data || null;
  s.chatMeta = meta || null;
  s.session_id = data && data.session_id ? data.session_id : s.session_id;
  s.conversation_id = data && data.conversation_id ? data.conversation_id : s.conversation_id;
  s.scene_code = data && data.scene_code ? data.scene_code : s.scene_code;
  s.module_code = data && data.module_code ? data.module_code : s.module_code;
  s.difficulty_level = data && data.difficulty_level ? data.difficulty_level : s.difficulty_level;
  s.round_count = data && data.round_count ? Number(data.round_count) : 0;
  s.stage = data && data.stage ? data.stage : 'init';
  s.end_flag = data && data.end_flag ? Number(data.end_flag) : 0;
  s.latestTurnFeedback = getLatestPracticeTurnFeedback(data);
  s.latestTurnVoiceAdvice = s.latestTurnFeedback ? String(s.latestTurnFeedback.voice_advice || '').trim() : '';
  s.user_message = '';
  savePracticeStateToStorage();
}

function pushPracticeOptimisticUserMessage(text) {
  var s = moduleState.practice;
  var base = s.chatResult || {};
  var conv = Array.isArray(base.conversation) ? base.conversation.slice() : [];
  conv.push({ role: 'user', content: text, _optimistic: true });
  s.chatResult = Object.assign({}, base, {
    session_id: base.session_id || s.session_id || '',
    conversation_id: base.conversation_id || s.conversation_id || '',
    scene_code: base.scene_code || s.scene_code || '',
    module_code: base.module_code || s.module_code || '',
    difficulty_level: base.difficulty_level || s.difficulty_level || '',
    round_count: base.round_count != null ? Number(base.round_count) : Number(s.round_count || 0),
    stage: base.stage || s.stage || 'init',
    end_flag: base.end_flag != null ? Number(base.end_flag) : Number(s.end_flag || 0),
    conversation: conv,
  });
}

async function submitPracticeChat(action) {
  syncPracticeFormState();
  setRequestLoading('practiceChat', true);
  clearRequestError('practiceChat');
  // Micro-expression: thinking while waiting for AI reply
  if (typeof digitalHumanMicroExpression === 'function' && action === 'send') {
    digitalHumanMicroExpression('think');
  }
  var s = moduleState.practice;
  var act = action || 'send';
  if (act === 'send' && !s.user_message) {
    setRequestLoading('practiceChat', false);
    showToast('请输入内容', 'info');
    rerenderCurrentPage();
    return;
  }
  if ((act === 'send' || act === 'end') && !String(s.module_code || '').trim()) {
    setRequestLoading('practiceChat', false);
    showToast('请先选模块', 'info');
    rerenderCurrentPage();
    return;
  }
  // 保存用户消息后立即清空，避免 rerender 时输入框残留
  var userMsg = s.user_message;
  var prevChatResult = s.chatResult;
  s.user_message = '';
  if (act === 'send' && userMsg) {
    pushPracticeOptimisticUserMessage(userMsg);
  }
  rerenderCurrentPage();
  try {
    var res = await apiFetch('/api/practice/chat', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        session_id: s.session_id,
        scene_code: s.scene_code,
        module_code: s.module_code,
        difficulty_level: s.difficulty_level,
        user_message: userMsg,
        conversation_id: s.conversation_id || '',
        action: act,
        score_branch: moduleState.cycleTaskContext.branch || 'practice',
        cycle_day_index: moduleState.cycleTaskContext.dayIndex || null,
      }),
    });
    applyPracticeChatData(res.data || null, res.meta || null);
    setRequestLoading('practiceChat', false);
    var latestTurnFeedback = getLatestPracticeTurnFeedback(res.data || null);
    var turnVoiceAdvice = latestTurnFeedback ? String(latestTurnFeedback.voice_advice || '').trim() : '';
    if (latestTurnFeedback) {
      s.latestTurnFeedback = latestTurnFeedback;
      s.latestTurnVoiceAdvice = turnVoiceAdvice;
      s.lastDigitalHumanSpeech = turnVoiceAdvice || String(latestTurnFeedback.mentor_comment || '').trim();
      setDigitalHumanContext({
        focus_source: 'practice',
        focus_dimension: String(latestTurnFeedback.intent_label || '').trim(),
        module_code: s.module_code || '',
        scene_code: s.scene_code || '',
        difficulty_level: s.difficulty_level || 'standard',
        practice_turn_feedback_summary: String(latestTurnFeedback.mentor_comment || '').trim(),
        practice_turn_feedback_voice_advice: turnVoiceAdvice,
      });
    }
    if (typeof digitalHumanReact === 'function') {
      var _dhEmotion = _detectPracticeEmotion(res.data);
      if (_dhEmotion) {
        digitalHumanReact(_dhEmotion);
      } else if (typeof digitalHumanMicroExpression === 'function') {
        var _conv = res.data && res.data.conversation ? res.data.conversation : [];
        var _lastMsg = '';
        for (var _i = _conv.length - 1; _i >= 0; _i--) {
          if (_conv[_i].role !== 'user') { _lastMsg = _conv[_i].content || ''; break; }
        }
        if (_lastMsg) digitalHumanMicroExpression(digitalHumanAnalyzeReply(_lastMsg));
      }
    }
    if (typeof digitalHumanSpeak === 'function' && latestTurnFeedback && turnVoiceAdvice &&
        shouldAutoPlayDigitalHumanVoice('practice_turn_feedback')) {
      digitalHumanSpeak(turnVoiceAdvice, {
        bubbleKind: 'turn_feedback',
        pose: 'encourage',
        emotion: 'calm',
        trigger: 'auto',
        scene: 'practice_turn_feedback',
      });
    }
    if (s.chatResult && Number(s.chatResult.end_flag || 0) === 1) {
      await runPracticeClosureChain(true);
    }
    rerenderCurrentPage();
  } catch (e) {
    s.chatResult = prevChatResult;
    if (act === 'send') {
      s.user_message = userMsg;
    }
    setRequestLoading('practiceChat', false);
    showToast(e.message || '对话失败', 'error');
    rerenderCurrentPage();
  }
}

async function submitPracticeEnd() {
  return submitPracticeChat('end');
}

function resolvePracticeMentorText(data) {
  var payload = data && typeof data === 'object' ? data : {};
  var mentorText = String(payload.mentor_sentence || payload.mentorSentence || '').trim();
  if (mentorText) return mentorText;
  var coachSummary = String(payload.coach_summary || '').trim();
  if (coachSummary) return '根据刚才的陪练表现，我总结如下：' + coachSummary;
  return '';
}

async function fetchPracticeMentorFeedback(evaluationResult) {
  var s = moduleState.practice;
  var payload = evaluationResult && typeof evaluationResult === 'object' ? evaluationResult : null;
  if (!s.session_id || !payload) return null;
  try {
    return await apiFetch('/api/practice/mentor-feedback', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        session_id: s.session_id,
        scene_code: s.scene_code,
        module_code: s.module_code,
        conversation: s.chatResult && s.chatResult.conversation ? s.chatResult.conversation : [],
        overall_score: payload.overall_score,
        strengths: Array.isArray(payload.strengths) ? payload.strengths : [],
        improvements: Array.isArray(payload.improvements) ? payload.improvements : [],
        coach_summary: payload.coach_summary || '',
      }),
    });
  } catch (e) {
    console.warn('fetchPracticeMentorFeedback failed:', e);
    return null;
  }
}

async function submitPracticeEvaluate(silent) {
  setRequestLoading('practiceEvaluate', true);
  clearRequestError('practiceEvaluate');
  if (!silent) rerenderCurrentPage();
  try {
    var s = moduleState.practice;
    if (!s.session_id) {
      setRequestLoading('practiceEvaluate', false);
      if (!silent) showToast('', 'info');
      if (!silent) rerenderCurrentPage();
      return;
    }
    var res = await apiFetch('/api/practice/evaluate', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        session_id: s.session_id,
        scene_code: s.scene_code,
        module_code: s.module_code,
        conversation: s.chatResult && s.chatResult.conversation ? s.chatResult.conversation : [],
        score_branch: moduleState.cycleTaskContext.branch || 'practice',
        cycle_day_index: moduleState.cycleTaskContext.dayIndex || null,
      }),
    });
    s.evaluationResult = res.data || null;
    s.evaluationMeta = res.meta || null;
    s.mentorSentence = resolvePracticeMentorText(s.evaluationResult);
    s.mentorMeta = null;
    var mentorRes = await fetchPracticeMentorFeedback(s.evaluationResult);
    if (mentorRes && mentorRes.data) {
      s.mentorMeta = mentorRes.meta || null;
      if (s.evaluationResult && mentorRes.data.mentor_sentence) {
        s.evaluationResult.mentor_sentence = String(mentorRes.data.mentor_sentence || '').trim();
      }
      if (s.evaluationResult && !s.evaluationResult.coach_summary && mentorRes.data.coach_summary) {
        s.evaluationResult.coach_summary = String(mentorRes.data.coach_summary || '').trim();
      }
      s.mentorSentence = resolvePracticeMentorText(
        Object.assign({}, s.evaluationResult || {}, mentorRes.data || {})
      );
    } else {
      s.mentorSentence = resolvePracticeMentorText(s.evaluationResult);
    }
    s.lastDigitalHumanSpeech = s.mentorSentence;
    savePracticeStateToStorage();
    setRequestLoading('practiceEvaluate', false);
    if (!silent) showToast('', 'ok');
    var dhScore = s.evaluationResult ? Number(s.evaluationResult.overall_score || 0) : 0;
    var mentorText = String(s.mentorSentence || '').trim();
    if (s.evaluationResult) {
      setDigitalHumanContext({
        focus_source: 'practice',
        focus_dimension: String(s.evaluationResult.weak_dimension || '').trim(),
        mentor_sentence: mentorText,
        practice_score_mentor_sentence: mentorText,
        coach_tip: '',
        knowledge_patch: '',
        module_code: s.module_code || '',
        scene_code: s.scene_code || '',
        difficulty_level: s.difficulty_level || 'standard',
        knowledge_question: digitalHumanWeakQuestion(s.evaluationResult.weak_dimension || ''),
      });
    }
    // Digital human speaks mentor sentence (preferred) or coach summary
    if (typeof digitalHumanSpeak === 'function' && s.evaluationResult && shouldAutoPlayDigitalHumanVoice('practice_score')) {
      if (mentorText) {
        digitalHumanSpeak(mentorText, {
          bubbleKind: 'score',
          pose: dhScore >= 80 ? 'celebrate' : 'encourage',
          emotion: dhScore >= 80 ? 'happy' : 'calm',
          trigger: 'auto',
          scene: 'practice_score',
        });
      }
    }
    // Emotion reaction based on practice score
    if (typeof digitalHumanReact === 'function' && s.evaluationResult) {
      digitalHumanReact(dhScore >= 80 ? 'celebrate' : 'encourage');
    }
    if (!silent) rerenderCurrentPage();
  } catch (e) {
    setRequestLoading('practiceEvaluate', false);
    setRequestError('practiceEvaluate', e.message || '评分失败');
    if (!silent) showToast(e.message || '评分失败', 'error');
    if (!silent) rerenderCurrentPage();
  }
}

async function submitPracticeAbilityUpdate(silent) {
  setRequestLoading('practiceAbility', true);
  clearRequestError('practiceAbility');
  if (!silent) rerenderCurrentPage();
  try {
    var s = moduleState.practice;
    if (!s.session_id) {
      setRequestLoading('practiceAbility', false);
      if (!silent) showToast('', 'info');
      if (!silent) rerenderCurrentPage();
      return;
    }
    var score = s.evaluationResult && s.evaluationResult.overall_score ? s.evaluationResult.overall_score : null;
    var res = await apiFetch('/api/practice/update-ability', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        session_id: s.session_id,
        employee_id: '',
        evaluation_id: s.evaluationResult && s.evaluationResult.evaluation_id ? s.evaluationResult.evaluation_id : '',
        module_code: s.module_code,
        score: score,
        score_branch: moduleState.cycleTaskContext.branch || 'practice',
        cycle_day_index: moduleState.cycleTaskContext.dayIndex || null,
      }),
    });
    var prevSnap = s.abilityPrevSnapshot && typeof s.abilityPrevSnapshot === 'object' ? s.abilityPrevSnapshot : null;
    s.abilityResult = res.data || null;
    s.abilityMeta = res.meta || null;
    var nextSnap = s.abilityResult && s.abilityResult.ability_snapshot ? s.abilityResult.ability_snapshot : null;
    s.abilityLastDelta = practiceComputeAbilityDelta(prevSnap, nextSnap);
    if (nextSnap && typeof nextSnap === 'object') {
      s.abilityPrevSnapshot = JSON.parse(JSON.stringify(nextSnap));
    }
    savePracticeStateToStorage();
    setRequestLoading('practiceAbility', false);
    if (!silent) showToast('', 'ok');
    if (!silent) rerenderCurrentPage();
  } catch (e) {
    setRequestLoading('practiceAbility', false);
    setRequestError('practiceAbility', e.message || '更新失败');
    if (!silent) showToast(e.message || '更新失败', 'error');
    if (!silent) rerenderCurrentPage();
  }
}

async function runPracticeClosureChain(silent) {
  var s = moduleState.practice;
  if (!s.chatResult || Number(s.chatResult.end_flag || 0) !== 1) return;
  await submitPracticeEvaluate(true);
  if (s.evaluationResult && s.evaluationResult.evaluation_id) {
    await submitPracticeAbilityUpdate(true);
  }
  // Auto-complete cycle task if active
  if (moduleState.cycleTaskContext.active && moduleState.cycleTaskContext.taskType === 'practice_chat') {
    await completeCurrentCycleTask();
  }
  if (!silent) showToast('已完成', 'ok');
}

function practiceNum01(v) {
  var n = Number(v);
  if (isNaN(n)) return 0;
  return Math.min(100, Math.max(0, n));
}

function practiceComputeAbilityDelta(prev, next) {
  if (!prev || !next || typeof prev !== 'object' || typeof next !== 'object') return null;
  var keys = ['product_knowledge', 'sales_expression', 'objection_handling', 'closing_skill'];
  var out = {};
  var any = false;
  for (var i = 0; i < keys.length; i++) {
    var k = keys[i];
    var a = Number(prev[k]);
    var b = Number(next[k]);
    if (isNaN(b)) continue;
    if (isNaN(a)) a = b;
    var d = Math.round((b - a) * 10) / 10;
    out[k] = d;
    if (d !== 0) any = true;
  }
  return any ? out : null;
}

