    var dActive = s.difficulty_level === d.value ? ' practice-capsule-item--active' : '';
    html += '<div class="practice-capsule-item' + dActive + '" data-value="' + escapeHtml(d.value) + '" onclick="selectCapsuleOption(this,\'difficulty\')">';
