function renderPracticeConversation() {
  var data = moduleState.practice.chatResult;
  var conv = data && data.conversation ? data.conversation : [];
  var chatLoading = requestLoading('practiceChat');
  if (!conv.length && !chatLoading) {
    return (
      '<div class="practice-chat-empty">' +
      '<p class="practice-chat-empty-title">开始你的第一轮应答</p>' +
      '<p class="practice-chat-empty-hint">选择场景与难度后，在下方输入框中发送消息</p>' +
      '</div>'
    );
  }
  var html = '<div class="practice-msg-stack">';
  for (var i = 0; i < conv.length; i++) {
    var item = conv[i];
    var isUser = item.role === 'user';
    var rowClass = isUser ? 'practice-msg-row practice-msg-row--user' : 'practice-msg-row practice-msg-row--ai';
    var bubbleClass = isUser ? 'practice-bubble practice-bubble--user' : 'practice-bubble practice-bubble--ai';
    html +=
      '<div class="' +
      rowClass +
      '">' +
      '<div class="' +
      bubbleClass +
      '">' +
      '<p class="practice-bubble-text">' +
      escapeHtml(item.content || '') +
      '</p></div>' +
      (!isUser ? renderPracticeTurnFeedbackCard(item.turn_feedback) : '') +
      '</div>';
  }
  if (chatLoading) {
    html += renderPracticePendingHintBubble();
  }
  html += '</div>';
  return html;
}

function practiceSceneLabel(sceneCode) {
  var scenes = {
    jewelry_recommendation: '珠宝推荐',
    objection_handling: '异议处理',
    after_sales: '售后安抚',
    product_consultation: '产品咨询',
    customer_opening: '接待开场',
    needs_discovery: '需求洞察',
    combo_recommendation: '搭配推荐',
    closing_conversion: '成交推进',
    compliance_guidance: '合规引导',
  };
  return scenes[sceneCode] || '未选择场景';
}

function renderPracticeModuleBadge(moduleCode) {
  var label = practiceModuleLabel(moduleCode);
  if (!moduleCode) {
    return '<span class="inline-flex items-center rounded-full border border-amber-200 bg-amber-50 px-3 py-1 text-[11px] font-medium text-amber-700">待选择模块</span>';
  }
  return '<span class="inline-flex items-center rounded-full border border-sky-200 bg-sky-50 px-3 py-1 text-[11px] font-medium text-sky-700">' + escapeHtml(label) + '</span>';
}

function renderPracticeScore() {
  var data = moduleState.practice.evaluationResult;
  var latestTurnFeedback = normalizePracticeTurnFeedback(moduleState.practice.latestTurnFeedback);
  if (!data) {
    if (!latestTurnFeedback) return renderEmptyState('评估');
    return (
      '<div class="practice-feedback-summary">' +
      '<p class="practice-feedback-summary__eyebrow">最近一轮经验人点评</p>' +
      '<p class="practice-feedback-summary__headline">' + escapeHtml(latestTurnFeedback.intent_label || '经验人判断') + '</p>' +
      '<p class="practice-feedback-summary__body">' + escapeHtml(latestTurnFeedback.mentor_comment || '') + '</p>' +
      '<div class="practice-feedback-summary__meta">' +
      '<span class="practice-feedback-summary__chip">' + escapeHtml(latestTurnFeedback.customer_state || '顾客状态') + '</span>' +
      '<span class="practice-feedback-summary__chip">' + escapeHtml(latestTurnFeedback.next_action || '继续推进') + '</span>' +
      '</div>' +
      '<p class="practice-feedback-summary__question">' + escapeHtml(latestTurnFeedback.next_question || '') + '</p>' +
      renderMetaHint(moduleState.practice.chatMeta) +
      '</div>'
    );
  }
  var strengthsHtml = renderPracticeInsightList(data.strengths || [], 'strength');
  var improveHtml = renderPracticeInsightList(data.improvements || [], 'improve');
  if (!strengthsHtml) strengthsHtml = '<p class="text-sm text-[#86868B]">暂无记录</p>';
  if (!improveHtml) improveHtml = '<p class="text-sm text-[#86868B]">暂无建议</p>';
  var coach = data.coach_summary ? '<p class="practice-coach-summary">' + escapeHtml(data.coach_summary) + '</p>' : '';
  return (
    '<div class="practice-score-inner space-y-4">' +
    '<div class="flex flex-wrap items-center gap-2">' +
    renderPracticeModuleBadge(moduleState.practice.module_code) +
    '</div>' +
    '<div class="practice-health-hero">' +
    '<div><p class="practice-health-label">综合得分</p><p class="practice-health-score">' +
    escapeHtml(data.overall_score == null ? '--' : String(data.overall_score)) +
    '</p></div>' +
    renderPracticeRadarSvg(data) +
    '</div>' +
    coach +
    '<div class="practice-insight-columns">' +
    '<div><p class="practice-insight-title practice-insight-title--pos">亮点</p>' +
    strengthsHtml +
    '</div>' +
    '<div><p class="practice-insight-title practice-insight-title--warn">改进点</p>' +
    improveHtml +
    '</div></div>' +
    '<div class="mt-2">' +
    renderMetaHint(moduleState.practice.evaluationMeta) +
    '</div></div>'
  );
}

function renderPracticeAbility() {
  var data = moduleState.practice.abilityResult;
  if (!data) return renderEmptyState('数据');
  var snap = data.ability_snapshot || {};
  var delta = moduleState.practice.abilityLastDelta || null;
  var rings =
    renderPracticeAbilityRing('产品知识', snap.product_knowledge, delta && delta.product_knowledge) +
    renderPracticeAbilityRing('销售表达', snap.sales_expression, delta && delta.sales_expression) +
    renderPracticeAbilityRing('异议处理', snap.objection_handling, delta && delta.objection_handling) +
    renderPracticeAbilityRing('成交收口', snap.closing_skill, delta && delta.closing_skill);
  var tags = '';
  if (data.updated_tags && data.updated_tags.length) {
    tags = '<div class="practice-tag-row">';
    for (var i = 0; i < data.updated_tags.length; i++) {
      tags += '<span class="practice-ability-tag">' + escapeHtml(data.updated_tags[i]) + '</span>';
    }
    tags += '</div>';
  }
  return (
    '<div class="practice-ability-inner space-y-4">' +
    '<div class="practice-ability-rings">' +
    rings +
    '</div>' +
    tags +
    '<div class="practice-ability-comment">' +
    escapeHtml(data.ability_comment || '') +
    '</div>' +
    '<div>' +
    renderMetaHint(moduleState.practice.abilityMeta) +
    '</div></div>'
  );
}

/** SF Symbol–style sidebar.right (leading inspector / trailing sidebar). */
function practiceSidebarRightIconSvg() {
  return (
    '<svg class="practice-toolbar-sidebar-icon" viewBox="0 0 24 24" fill="none" aria-hidden="true">' +
    '<path d="M4.5 5.25h9a1.5 1.5 0 011.5 1.5v10.5a1.5 1.5 0 01-1.5 1.5h-9A1.5 1.5 0 013 17.25V6.75a1.5 1.5 0 011.5-1.5z" stroke="currentColor" stroke-width="1.5" stroke-linejoin="round"/>' +
    '<path d="M15 5.25h4.5a1.5 1.5 0 011.5 1.5v10.5a1.5 1.5 0 01-1.5 1.5H15" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>' +
    '</svg>'
  );
}

function practiceToolbarMoreIconSvg() {
  return (
    '<svg class="practice-toolbar-more-dots" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">' +
    '<circle cx="5" cy="12" r="2"/><circle cx="12" cy="12" r="2"/><circle cx="19" cy="12" r="2"/>' +
    '</svg>'
  );
}

function togglePracticeSidePanel() {
  var s = moduleState.practice;
  s.sidePanelCollapsed = !s.sidePanelCollapsed;
  savePracticeStateToStorage();
  if (!applyPracticeSidePanelState(s.sidePanelCollapsed)) {
    rerenderCurrentPage();
  }
}

function applyPracticeSidePanelState(sidePanelCollapsed) {
  var pageRoot = document.querySelector('.practice-page-root');
  if (!pageRoot) return false;
  var grid = pageRoot.querySelector('.practice-main-grid');
  var sideCol = pageRoot.querySelector('.practice-col-side');
  var sideShell = pageRoot.querySelector('.practice-side-shell');
  var stageWrap = pageRoot.querySelector('.practice-main-stage-wrap');
  var toolbarSidebar = pageRoot.querySelector('.practice-toolbar-sidebar-btn');
  if (!grid || !sideCol) return false;

  var collapsed = !!sidePanelCollapsed;
  var toggleLabel = collapsed ? '展开右侧面板' : '收起右侧面板';
  grid.classList.toggle('practice-main-grid--side-collapsed', collapsed);
  if (stageWrap) {
    stageWrap.classList.toggle('practice-main-stage--side-collapsed', collapsed);
  }
  sideCol.classList.toggle('practice-col-side--collapsed', collapsed);
  sideCol.setAttribute('aria-expanded', collapsed ? 'false' : 'true');
  if (sideShell) {
    sideShell.classList.toggle('practice-side-shell--collapsed', collapsed);
  }
  if (toolbarSidebar) {
    toolbarSidebar.setAttribute('aria-expanded', collapsed ? 'false' : 'true');
    toolbarSidebar.setAttribute('aria-pressed', collapsed ? 'false' : 'true');
    toolbarSidebar.setAttribute('title', toggleLabel);
    toolbarSidebar.setAttribute('aria-label', toggleLabel);
  }
  return true;
}

function togglePracticeCard(cardKey) {
  var s = moduleState.practice;
  if (!s.practiceCardCollapsed || typeof s.practiceCardCollapsed !== 'object') {
    s.practiceCardCollapsed = { config: false, feedback: false, ability: false };
  }
  s.practiceCardCollapsed[cardKey] = !s.practiceCardCollapsed[cardKey];
  savePracticeStateToStorage();
  if (!applyPracticeCardCollapsedState(cardKey, s.practiceCardCollapsed[cardKey])) {
    rerenderCurrentPage();
  }
}

function applyPracticeCardCollapsedState(cardKey, collapsed) {
  var pageRoot = document.querySelector('.practice-page-root');
  if (!pageRoot) return false;
  var card = pageRoot.querySelector('.practice-side-card[data-card-key="' + cardKey + '"]');
  if (!card) return false;
  card.classList.toggle('practice-side-card--collapsed', !!collapsed);

  var btn = card.querySelector('.practice-card-collapse-btn');
  if (!btn) return true;
  var titleNode = card.querySelector('.practice-side-title');
  var titleText = titleNode ? String(titleNode.textContent || '').trim() : '';
  var labelVerb = collapsed ? '展开' : '收起';
  var ariaFull = labelVerb + titleText;
  btn.setAttribute('aria-expanded', collapsed ? 'false' : 'true');
  btn.setAttribute('title', ariaFull);
  btn.setAttribute('aria-label', ariaFull);
  btn.innerHTML = practiceCardCollapseIconSvg(!!collapsed);
  return true;
}

function practiceCardCollapseIconSvg(collapsed) {
  return (
    '<svg class="practice-card-collapse-icon' +
    (collapsed ? '' : ' practice-card-collapse-icon--open') +
    '" viewBox="0 0 24 24" fill="none" aria-hidden="true">' +
    '<path d="M6 9l6 6 6-6" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>' +
    '</svg>'
  );
}

function practiceSideCardTitleIcon(iconKey) {
  if (iconKey === 'coach') {
    return (
      '<svg class="practice-side-title-icon" viewBox="0 0 24 24" fill="none" aria-hidden="true">' +
      '<path d="M12 6.25a3.75 3.75 0 100 7.5 3.75 3.75 0 000-7.5zM5.5 19.75a6.5 6.5 0 0113 0" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"/>' +
      '</svg>'
    );
  }
  if (iconKey === 'feedback') {
    return (
      '<svg class="practice-side-title-icon" viewBox="0 0 24 24" fill="none" aria-hidden="true">' +
      '<path d="M5 6.75h14M5 12h9M5 17.25h6" stroke="currentColor" stroke-width="1.75" stroke-linecap="round"/>' +
      '<path d="M17.25 17.25l2.25 1.75V15" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"/>' +
      '</svg>'
    );
  }
  if (iconKey === 'ability') {
    return (
      '<svg class="practice-side-title-icon" viewBox="0 0 24 24" fill="none" aria-hidden="true">' +
      '<path d="M12 4.5l2.2 4.45 4.9.72-3.55 3.46.84 4.87L12 15.8 7.61 18l.84-4.87L4.9 9.67l4.9-.72L12 4.5z" stroke="currentColor" stroke-width="1.6" stroke-linejoin="round"/>' +
      '</svg>'
    );
  }
  return '';
}

function renderPracticeSideCardPanel(cardKey, iconKey, title, desc, panelClass, innerHtml, outerAttrs) {
  var s = moduleState.practice;
  var map = s.practiceCardCollapsed || {};
  var collapsed = !!map[cardKey];
  var expandedAttr = collapsed ? 'false' : 'true';
  var labelVerb = collapsed ? '展开' : '收起';
  var ariaFull = labelVerb + title;
  var attrs = outerAttrs || '';
  return (
    '<div ' +
    attrs +
    ' data-card-key="' +
    escapeHtml(cardKey) +
    '" class="practice-glass-panel ' +
    panelClass +
    ' practice-side-card' +
    (collapsed ? ' practice-side-card--collapsed' : '') +
    '">' +
    '<div class="practice-side-card-head">' +
    '<div class="practice-side-title-row">' +
    practiceSideCardTitleIcon(iconKey) +
    '<h2 class="practice-side-title">' +
    escapeHtml(title) +
    '</h2></div>' +
    '<button type="button" class="practice-card-collapse-btn" onclick="togglePracticeCard(\'' +
    cardKey +
    '\')" aria-expanded="' +
    expandedAttr +
    '" title="' +
    escapeHtml(ariaFull) +
    '" aria-label="' +
    escapeHtml(ariaFull) +
    '">' +
    practiceCardCollapseIconSvg(collapsed) +
    '</button></div>' +
    '<div class="practice-side-card-collapse-wrap"><div class="practice-side-card-collapse-inner">' +
    '<p class="practice-side-desc">' +
    escapeHtml(desc) +
    '</p>' +
    innerHtml +
    '</div></div></div>'
  );
}

function practiceCloseToolbarMore() {
  var d = document.querySelector('.practice-page-root .practice-toolbar-more');
  if (d) d.open = false;
}

function practiceMountScoreAnimation() {
  try {
    if (!moduleState.practice.evaluationResult) return;
    if (requestLoading('practiceEvaluate')) return;
    var panel = document.getElementById('practice-score-panel');
    if (!panel) return;
    panel.classList.remove('practice-score-enter');
    void panel.offsetWidth;
    panel.classList.add('practice-score-enter');
  } catch (e) {}
}

var PRACTICE_COMPOSE_MAX_HEIGHT_PX = 160;
var PRACTICE_COMPOSE_MIN_HEIGHT_PX = 48;
var PRACTICE_COMPOSE_FIXED_HEIGHT_PX = 96;

function practiceResizeUserMessageTextarea() {
  var ta = document.getElementById('practice-user-message');
  if (!ta) return;
  ta.style.height = PRACTICE_COMPOSE_FIXED_HEIGHT_PX + 'px';
  ta.style.minHeight = PRACTICE_COMPOSE_FIXED_HEIGHT_PX + 'px';
  ta.style.maxHeight = PRACTICE_COMPOSE_FIXED_HEIGHT_PX + 'px';
  ta.style.overflowY = ta.scrollHeight > PRACTICE_COMPOSE_FIXED_HEIGHT_PX ? 'auto' : 'hidden';
}

function practiceMountComposeTextarea() {
  var ta = document.getElementById('practice-user-message');
  if (ta) {
    ta.addEventListener('input', practiceResizeUserMessageTextarea);
    ta.addEventListener('keydown', function (e) {
      if (e.key === 'Enter' && !e.shiftKey) {
        e.preventDefault();
        submitPracticeChat('send');
      }
    });
  }
  // 事件委托到 #content-area，避免 rerender 后监听器丢失
  var contentArea = document.getElementById('content-area');
  if (contentArea) {
    contentArea.removeEventListener('click', handlePracticeComposeClick);
    contentArea.addEventListener('click', handlePracticeComposeClick);
  }
  if (ta) practiceResizeUserMessageTextarea();
}

function handlePracticeComposeClick(e) {
  var btn = e.target.closest('#practice-btn-send');
  if (btn) {
    // 立即禁用按钮，避免重复发送
    btn.disabled = true;
    // 显示发送中状态
    var iconEl = btn.querySelector('.practice-send-icon');
    if (iconEl) iconEl.style.display = 'none';
    var loadingEl = btn.querySelector('.practice-send-loading');
    if (loadingEl) loadingEl.style.display = '';
    submitPracticeChat('send');
  }
}

function practiceSendIconSvg(loading) {
  if (loading) {
    return '<span class="practice-send-loading" style="display:none"><svg class="h-5 w-5 animate-spin" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="3"/><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"/></svg></span>';
  }
  return '<svg class="h-[22px] w-[22px] practice-send-icon" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><path d="M22 2L11 13M22 2L15 22L11 13M22 2L2 9L11 13" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>';
}

function renderPracticePage(container) {
  var s = moduleState.practice;
  var practiceChatLoading = requestLoading('practiceChat');
  var practiceEvalLoading = requestLoading('practiceEvaluate');
  var practiceAbilityLoading = requestLoading('practiceAbility');
  var practiceFinishLoading = practiceChatLoading || practiceEvalLoading;
  var chatData = s.chatResult;
  var inSession =
    chatData &&
    chatData.conversation &&
    chatData.conversation.length > 0 &&
    Number(chatData.end_flag || 0) !== 1;
  var sideCollapsedClass = inSession ? ' practice-side-col--dim' : '';
  var sidePanelCollapsed = !!s.sidePanelCollapsed;
  var colSideClass =
    'practice-col-side' +
    (sidePanelCollapsed ? ' practice-col-side--collapsed' : '');
  var toggleLabel = sidePanelCollapsed ? '展开右侧面板' : '收起右侧面板';

  var toolbar =
    '<div class="practice-toolbar">' +
    '<div class="practice-toolbar-cluster">' +
    '<button type="button" class="practice-toolbar-sidebar-btn" onclick="togglePracticeSidePanel()" aria-expanded="' +
    (sidePanelCollapsed ? 'false' : 'true') +
    '" aria-pressed="' +
    (sidePanelCollapsed ? 'false' : 'true') +
    '" title="' +
    escapeHtml(toggleLabel) +
    '" aria-label="' +
    escapeHtml(toggleLabel) +
    '">' +
    practiceSidebarRightIconSvg() +
    '</button>' +
    '<div class="practice-toolbar-actions">' +
    '<button type="button" onclick="submitPracticeEnd()" class="practice-tool-btn practice-tool-btn--primary-accent"' +
    buttonDisabledAttrByState(practiceFinishLoading) +
    '>' +
    escapeHtml(buttonLabelByState(practiceFinishLoading, '结束陪练', '处理中')) +
    '</button>' +
    '<details class="practice-toolbar-more">' +
    '<summary class="practice-toolbar-more-summary" title="更多" aria-label="更多操作">' +
    practiceToolbarMoreIconSvg() +
    '</summary>' +
    '<div class="practice-toolbar-more-panel" role="menu">' +
    '<button type="button" role="menuitem" class="practice-toolbar-more-item" onclick="practiceCloseToolbarMore(); submitPracticeResume();"' +
    buttonDisabledAttrByState(practiceChatLoading) +
    '>恢复会话</button>' +
    '<button type="button" role="menuitem" class="practice-toolbar-more-item" onclick="practiceCloseToolbarMore(); resetPracticeSession();">新会话</button>' +
    '<button type="button" role="menuitem" class="practice-toolbar-more-item" onclick="practiceCloseToolbarMore(); submitPracticeAbilityUpdate();"' +
    buttonDisabledAttrByState(practiceAbilityLoading) +
    '>更新能力</button>' +
    '</div></details>' +
    '</div></div></div>';

  var hero =
    '<header class="practice-hero glass-practice">' +
    '<div class="practice-hero-top">' +
    '<div><h1 class="app-page-title">智能陪练</h1>' +
    '<div class="mt-3 flex flex-wrap gap-2">' +
    renderPracticeModuleBadge(s.module_code) +
    '<span class="inline-flex items-center rounded-full border border-slate-200 bg-white px-3 py-1 text-[11px] font-medium text-slate-600">' + escapeHtml(practiceSceneLabel(s.scene_code)) + '</span>' +
    '</div></div>' +
    toolbar +
    '</div></header>';

  var chatPanel =
    '<section id="practice-chat-panel" class="practice-glass-panel practice-chat-panel">' +
    '<div class="mb-3 flex flex-wrap items-center gap-2 px-1">' +
    renderPracticeModuleBadge(s.module_code) +
    '<span class="inline-flex items-center rounded-full bg-slate-100 px-3 py-1 text-[11px] font-medium text-slate-600">' + escapeHtml('场景 · ' + practiceSceneLabel(s.scene_code)) + '</span>' +
    '</div>' +
    '<div class="practice-chat-scroll">' +
    renderPracticeConversation() +
    '</div>' +
    '<div class="practice-compose-area mt-4 px-1">' +
    '<div class="compose-shell">' +
    '<textarea id="practice-user-message" class="compose-input" placeholder="发消息…" autocomplete="off" spellcheck="false">' +
    escapeHtml(s.user_message) +
    '</textarea>' +
    '<button type="button" id="practice-btn-send" class="compose-send-btn" aria-label="发送"' +
    buttonDisabledAttrByState(practiceChatLoading) +
    '>' +
    practiceSendIconSvg(practiceChatLoading) +
    '</button></div></div></section>';

  var sideStack =
    '<div class="practice-side-stack' +
    sideCollapsedClass +
    '">' +
    renderPracticeSideCardPanel(
      'config',
      'coach',
      '陪练',
      '',
      'practice-config-card',
      renderPracticeScenePicker(s),
      ''
    ) +
    renderPracticeSideCardPanel(
      'feedback',
      'feedback',
      '即时反馈',
      '',
      'practice-feedback-card' + (s.evaluationResult ? ' practice-feedback-card--has-score' : ''),
      renderRequestBanner('practiceEvaluate', '正在生成评分…') + renderPracticeScore(),
      'id="practice-score-panel" '
    ) +
    renderPracticeSideCardPanel(
      'ability',
      'ability',
      '能力更新',
      '',
      'practice-ability-card',
      renderRequestBanner('practiceAbility', '正在更新能力画像…') +
        renderPracticeAbility(),
      ''
    ) +
    '</div>';

  container.innerHTML =
    '<div class="practice-page-root w-full">' +
    hero +
    '<div class="practice-main-stage-wrap' +
    (sidePanelCollapsed ? ' practice-main-stage--side-collapsed' : '') +
    '">' +
    '<div class="practice-main-grid' +
    (sidePanelCollapsed ? ' practice-main-grid--side-collapsed' : '') +
    '">' +
    '<div class="practice-col-chat">' +
    '<div class="practice-chat-stage">' +
    chatPanel +
    '</div></div>' +
    '<aside class="' +
    colSideClass +
    '" aria-expanded="' +
    (sidePanelCollapsed ? 'false' : 'true') +
    '">' +
    '<div class="practice-side-shell' +
    (sidePanelCollapsed ? ' practice-side-shell--collapsed' : '') +
    '">' +
    '<div class="practice-side-rail">' +
    '<div class="practice-side-rail-head">' +
    '<div class="practice-side-rail-head-copy">' +
    '<span class="practice-side-rail-unified">管理面板 · 陪练</span>' +
    '</div>' +
    '</div>' +
    '<div class="practice-side-body">' +
    sideStack +
    '</div>' +
    '</div></div></aside></div>' +
    '</div></div>';

  setTimeout(function () {
    practiceMountScoreAnimation();
    if (typeof digitalHumanSetActivePage === 'function') {
      digitalHumanSetActivePage('practical_training');
    }
    if (typeof mountDigitalHuman === 'function') {
      mountDigitalHuman();
    }
  }, 40);
  practiceMountComposeTextarea();
}

function syncAssistantState() {
  moduleState.assistant.scene_input = getFieldValue('assistant-scene-input');
}

function assistantStorageKey() {
  var uid = String(localStorage.getItem('userId') || localStorage.getItem('username') || 'anonymous').trim() || 'anonymous';
  return ASSISTANT_SESSION_KEY + ':' + uid;
}

function loadAssistantSessionState() {
  var s = moduleState.assistant;
  if (s._sessionLoaded) return;
  s._sessionLoaded = true;
  try {
    var raw = sessionStorage.getItem(assistantStorageKey());
    if (!raw) return;
    var data = JSON.parse(raw);
    if (!data || typeof data !== 'object') return;
    s.scene_input = String(data.scene_input || '');
    s.replyResult = data.replyResult && typeof data.replyResult === 'object' ? data.replyResult : null;
    s.lastDigitalHumanSpeech = String(data.lastDigitalHumanSpeech || '');
    s.lastSubmittedText = String(data.lastSubmittedText || '');
    s.conversationHistory = Array.isArray(data.conversationHistory) ? data.conversationHistory : [];
    s.conversationId = String(data.conversationId || '');
    s.latestTurnFeedback = data.latestTurnFeedback && typeof data.latestTurnFeedback === 'object' ? data.latestTurnFeedback : null;
    s.isChatting = !!data.isChatting || s.conversationHistory.length > 0 || !!s.replyResult;
  } catch (e) {}
}

function saveAssistantSessionState() {
  var s = moduleState.assistant;
  try {
    sessionStorage.setItem(assistantStorageKey(), JSON.stringify({
      scene_input: String(s.scene_input || ''),
      replyResult: s.replyResult || null,
      lastDigitalHumanSpeech: String(s.lastDigitalHumanSpeech || ''),
      lastSubmittedText: String(s.lastSubmittedText || ''),
      conversationHistory: Array.isArray(s.conversationHistory) ? s.conversationHistory.slice(-40) : [],
      conversationId: String(s.conversationId || ''),
      latestTurnFeedback: s.latestTurnFeedback || null,
      isChatting: !!s.isChatting,
    }));
  } catch (e) {}
}

async function submitAssistantReply() {
  syncAssistantState();
  var s = moduleState.assistant;
  var q = String(s.scene_input || '').trim();
  if (!q) {
    showToast('请输入场景', 'info');
    return;
  }
  if (requestLoading('assistantReply')) {
    return;
  }
  s.isChatting = true;
  s.lastSubmittedText = q;
  s.scene_input = '';
  s.replyResult = null;
  // Micro-expression: thinking while waiting for reply
  if (typeof digitalHumanMicroExpression === 'function') {
    digitalHumanMicroExpression('think');
  }
  s.conversationHistory = Array.isArray(s.conversationHistory) ? s.conversationHistory : [];
  s.conversationHistory.push({ role: 'user', content: q });
  saveAssistantSessionState();
  setRequestLoading('assistantReply', true);
  clearRequestError('assistantReply');
  rerenderCurrentPage();
  try {
    s = moduleState.assistant;
    var res = await apiFetch('/api/assistant/reply', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ scene_input: q, history: s.conversationHistory, conversation_id: s.conversationId || '' }),
    });
    s.replyResult = res.data || null;
    // 存储 conversation_id 用于下一轮对话
    if (res.data && res.data.conversation_id) {
      s.conversationId = res.data.conversation_id;
    }
    var assistantSpeech = '';
    var turnFeedback = (res.data && res.data.turn_feedback) || null;
    s.latestTurnFeedback = turnFeedback;
    if (res.data) {
      // 优先使用 turn_feedback 中的 voice_advice
      var tfVoice = turnFeedback ? String(turnFeedback.voice_advice || '').trim() : '';
      var coachAdvice = tfVoice || String(res.data.voice_advice || res.data.coach_tip || '').trim();
      assistantSpeech = coachAdvice;
      s.lastDigitalHumanSpeech = assistantSpeech;
      if (coachAdvice) {
        setDigitalHumanContext({
          focus_source: 'assistant',
          coach_tip: coachAdvice,
          assistant_scene_input: q,
          knowledge_patch: '',
        });
      }
    }
    s._replyAnimAt = Date.now();
    // 添加助手回复到对话历史（话术和追问分开存储，附带 turn_feedback）
    if (res.data && res.data.reply_script) {
      s.conversationHistory.push({ role: 'assistant', content: res.data.reply_script, msgType: 'reply', turn_feedback: turnFeedback });
    }
    if (res.data && res.data.followup_question) {
      s.conversationHistory.push({ role: 'assistant', content: res.data.followup_question, msgType: 'followup' });
    }
    saveAssistantSessionState();
    setRequestLoading('assistantReply', false);
    showToast('', 'ok');
    rerenderCurrentPage();
    // 数字人朗读教练建议，使用 encourage 姿势
    if (typeof digitalHumanSpeak === 'function' && assistantSpeech) {
      digitalHumanSpeak(assistantSpeech, {
        bubbleKind: turnFeedback ? 'assistant_feedback' : 'assistant',
        pose: turnFeedback ? 'encourage' : 'agree',
        emotion: 'calm',
        trigger: 'auto',
        scene: 'assistant',
      });
    }
  } catch (e) {
    setRequestLoading('assistantReply', false);
    setRequestError('assistantReply', e.message || '话术生成失败');
    showToast(e.message || '话术生成失败', 'error');
    rerenderCurrentPage();
  }
}

function clearAssistantSession() {
  var s = moduleState.assistant;
  s.conversationHistory = [];
  s.scene_input = '';
  s.replyResult = null;
  s.isChatting = false;
  s.lastSubmittedText = '';
  s.lastDigitalHumanSpeech = '';
  s.conversationId = '';
  s.latestTurnFeedback = null;
  clearRequestError('assistantReply');
  setRequestLoading('assistantReply', false);
  saveAssistantSessionState();
  rerenderCurrentPage();
}

function assistantAnimWindowActive(ts) {
  return ts && Date.now() - ts < 480;
}

/* ---- 语音识别 (Web Speech API) ---- */
var _assistantVoiceRecognition = null;
var _assistantVoiceListening = false;

(function initAssistantVoice() {
  var SR = window.SpeechRecognition || window.webkitSpeechRecognition;
  if (!SR) return;
  var recognition = new SR();
  recognition.lang = 'zh-CN';
  recognition.continuous = false;
  recognition.interimResults = true;

  recognition.onstart = function () {
    _assistantVoiceListening = true;
    var btn = document.getElementById('assistant-voice-btn');
    if (btn) {
      btn.classList.add('bg-red-500', 'text-white', 'animate-pulse');
      btn.classList.remove('text-[#86868B]');
      btn.title = '录音中…点击停止';
    }
  };
  recognition.onend = function () {
    _assistantVoiceListening = false;
    var btn = document.getElementById('assistant-voice-btn');
    if (btn) {
      btn.classList.remove('bg-red-500', 'text-white', 'animate-pulse');
      btn.classList.add('text-[#86868B]');
      btn.title = '语音输入';
    }
  };
  recognition.onresult = function (e) {
    var transcript = '';
    for (var i = e.resultIndex; i < e.results.length; i++) {
      transcript += e.results[i][0].transcript;
    }
    var input = document.getElementById('assistant-scene-input');
    if (input) {
      input.value = transcript;
      if (typeof window.assistantResizeSceneInput === 'function') {
        window.assistantResizeSceneInput();
      }
    }
  };
  recognition.onerror = function (e) {
    if (e.error === 'not-allowed') {
      showToast('麦克风未授权', 'error');
    } else if (e.error !== 'aborted') {
      showToast('语音识别出错：' + e.error, 'error');
    }
  };
  _assistantVoiceRecognition = recognition;
})();

function toggleAssistantVoice() {
  if (!_assistantVoiceRecognition) {
    showToast('不支持语音', 'info');
    return;
  }
  if (_assistantVoiceListening) {
    _assistantVoiceRecognition.stop();
  } else {
    _assistantVoiceRecognition.start();
  }
}

var _assistantSceneTaLinePx = 24;
var _assistantSceneTaMaxRows = 8;

function assistantResizeSceneInput() {
  var ta = document.getElementById('assistant-scene-input');
  if (!ta || ta.tagName !== 'TEXTAREA') return;
  ta.style.height = 'auto';
  var maxH = _assistantSceneTaLinePx * _assistantSceneTaMaxRows;
  var next = Math.min(ta.scrollHeight, maxH);
  ta.style.height = Math.max(next, _assistantSceneTaLinePx) + 'px';
  ta.style.overflowY = ta.scrollHeight > maxH ? 'auto' : 'hidden';
}

function assistantMountQuestionTextarea() {
  assistantResizeSceneInput();
}

window.assistantResizeSceneInput = assistantResizeSceneInput;

function copyAssistantReplyToClipboard() {
  var data = moduleState.assistant.replyResult;
  var text = data && (data.reply_script || data.reply_text) || '';
  if (!String(text).trim()) {
    showToast('', 'info');
    return;
  }
  navigator.clipboard.writeText(String(text)).then(
    function () {
      showToast('', 'ok');
      var btn = document.getElementById('assistant-copy-reply-btn');
      if (btn) {
        btn.classList.add('assistant-copy-btn--done');
        setTimeout(function () {
          btn.classList.remove('assistant-copy-btn--done');
        }, 900);
      }
    },
    function () {
      showToast('复制失败', 'error');
    }
  );
}

/** 在岗助手：单输入 + 单提交（仅同步在岗 1） */
