    '<svg class="h-[18px] w-[18px]" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden="true">' +
      '<path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.6" d="M12 1a3 3 0 00-3 3v8a3 3 0 006 0V4a3 3 0 00-3-3z" />' +
      '<path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.6" d="M19 10v2a7 7 0 01-14 0v-2" />' +
      '<path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.6" d="M12 19v4m-4 0h8" />' +
    '</svg>'
