function renderAssistantTurnFeedbackCard(feedback) {
  if (!feedback || typeof feedback !== 'object') return '';
  var intentLabel = String(feedback.intent_label || '').trim();
  var customerState = String(feedback.customer_state || '').trim();
  var mentorComment = String(feedback.mentor_comment || '').trim();
  var nextAction = String(feedback.next_action || '').trim();
  var nextQuestion = String(feedback.next_question || '').trim();
  var riskFlag = String(feedback.risk_flag || '').trim();
  if (!intentLabel && !customerState && !mentorComment && !nextAction && !nextQuestion && !riskFlag) return '';

  var html = '<div class="assistant-turn-feedback-card">';
  if (intentLabel || customerState) {
    html += '<div class="assistant-turn-feedback-card__meta">';
    if (intentLabel) {
      html += '<span class="assistant-turn-feedback-card__badge assistant-turn-feedback-card__badge--intent">' + escapeHtml(intentLabel) + '</span>';
    }
    if (customerState) {
      html += '<span class="assistant-turn-feedback-card__badge assistant-turn-feedback-card__badge--state">' + escapeHtml(customerState) + '</span>';
    }
    html += '</div>';
  }
  if (mentorComment) {
    html += '<div class="assistant-turn-feedback-card__section">' +
      '<p class="assistant-turn-feedback-card__label">导师点评</p>' +
      '<p class="assistant-turn-feedback-card__text">' + escapeHtml(mentorComment) + '</p></div>';
  }
  if (nextAction) {
    html += '<div class="assistant-turn-feedback-card__section">' +
      '<p class="assistant-turn-feedback-card__label">下一步</p>' +
      '<p class="assistant-turn-feedback-card__text">' + escapeHtml(nextAction) + '</p></div>';
  }
  if (nextQuestion) {
    html += '<div class="assistant-turn-feedback-card__section">' +
      '<p class="assistant-turn-feedback-card__label">推荐话术</p>' +
      '<p class="assistant-turn-feedback-card__text">' + escapeHtml(nextQuestion) + '</p></div>';
  }
  if (riskFlag) {
    html += '<div class="assistant-turn-feedback-card__risk">' +
      '<p class="assistant-turn-feedback-card__risk-label">合规提醒</p>' +
      '<p class="assistant-turn-feedback-card__risk-text">' + escapeHtml(riskFlag) + '</p></div>';
  }
  html += '</div>';
  return html;
}

function renderAssistantPage(container) {
  loadAssistantSessionState();
  var s = moduleState.assistant;
  var assistantReplyLoading = requestLoading('assistantReply');
  var animReply = assistantAnimWindowActive(s._replyAnimAt);
  var aiAnim = animReply ? ' assistant-cc-panel--enter' : '';

  var showChatLayout = !!s.isChatting || !!s.replyResult;
  var composer = renderAssistantComposer(s, assistantReplyLoading, showChatLayout);

  // 渲染对话历史
  var chatItems = '';
  var history = s.conversationHistory || [];
  for (var i = 0; i < history.length; i++) {
    var msg = history[i];
    if (msg.role === 'user') {
      chatItems += '<div class="practice-msg-row practice-msg-row--user">' +
        '<div class="practice-bubble practice-bubble--user">' +
        '<p class="practice-bubble-text">' + escapeHtml(msg.content) + '</p></div></div>';
    } else if (msg.role === 'assistant') {
      // 纯气泡样式，无卡片标签
      var msgClass = msg.msgType === 'followup' ? 'border-[#E5E5EA] bg-[#F2F2F7]' : '';
      chatItems += '<div class="practice-msg-row practice-msg-row--ai">' +
        '<div class="practice-bubble practice-bubble--ai assistant-ai-bubble ' + msgClass + '" style="border-bottom:1px solid #E5E5EA;margin-top:8px;">' +
        '<p class="text-[15px] leading-relaxed text-[#1D1D1F]">' + escapeHtml(msg.content) + '</p>' +
        '</div>' +
        renderAssistantTurnFeedbackCard(msg.turn_feedback) +
        '</div>';
    }
  }

  // 如果有当前加载中的回复，显示加载状态
  if (assistantReplyLoading) {
    chatItems += renderAiTypingBubble('assistant-ai-bubble');
  }

  var chatStack =
    '<div class="mx-auto max-w-4xl practice-msg-stack pb-6">' + chatItems + '</div>';

  var baseFont =
    'font-family:-apple-system,BlinkMacSystemFont,\'SF Pro Text\',\'PingFang SC\',\'Helvetica Neue\',Helvetica,Arial,sans-serif';

  if (!showChatLayout) {
    container.innerHTML =
      '<section class="oj-assistant-page qq-page w-full bg-transparent text-[#1D1D1F]" style="' + baseFont + '">' +
        '<div class="mx-auto flex min-h-[calc(100dvh-12rem)] w-full max-w-2xl flex-col items-center justify-center px-4 py-12 sm:max-w-3xl">' +
          '<div class="mb-10 w-full text-center">' +
            '<h1 class="app-page-title">在岗助手</h1>' +
            '<p class="knowledge-qa-hero-desc">把顾客当下的话和异议，转成你现场可以直接使用的回复。</p>' +
          '</div>' +
          '<div class="w-full max-w-4xl mt-8">' + composer + '</div>' +
        '</div>' +
      '</section>';
  } else {
    container.innerHTML =
      '<section class="oj-assistant-page qq-page app-chat-page w-full bg-transparent text-[#1D1D1F]" style="' + baseFont + '">' +
        '<div class="app-chat-shell app-chat-shell--assistant mx-auto flex min-h-[calc(100dvh-9rem)] w-full max-w-4xl flex-col">' +
          '<div class="flex items-center justify-between border-b border-[#E5E5EA] px-4 py-3">' +
            '<div>' +
              '<h2 class="text-sm font-semibold text-[#1D1D1F]">在岗助手</h2>' +
              '<p class="mt-1 text-xs text-[#86868B]">顾客现场应答工具，重点是“直接生成可说的话术”</p>' +
            '</div>' +
            '<button type="button" onclick="clearAssistantSession()" class="flex items-center gap-1.5 rounded-lg bg-[#F2F2F7] px-3 py-1.5 text-xs font-medium text-[#86868B] transition hover:bg-[#E5E5EA] hover:text-[#1D1D1F]" title="清除当前会话上下文">' +
              '<svg class="h-3.5 w-3.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">' +
                '<path d="M3 6h18M8 6V4h8v2M19 6l-1 14H6L5 6" stroke-linecap="round" stroke-linejoin="round"/>' +
              '</svg>' +
              '清除会话' +
            '</button>' +
          '</div>' +
          '<div id="oa-chat-scroll" class="app-chat-scroll min-h-0 flex-1 overflow-y-auto overscroll-y-contain px-4 py-6" style="max-height:min(72vh,calc(100dvh - 13rem))">' +
            chatStack +
          '</div>' +
          '<div class="app-chat-composer sticky bottom-0 z-10 shrink-0 border-t border-transparent bg-gradient-to-t from-[#F2F2F7] via-[#F2F2F7]/98 to-transparent px-4 pb-5 pt-10 backdrop-blur-sm">' +
            '<div class="mx-auto w-full max-w-4xl">' +
            composer +
            '</div>' +
          '</div>' +
        '</div>' +
      '</section>';
  }

  setTimeout(function () {
    var el = document.getElementById('oa-chat-scroll');
    if (el) {
      try {
        el.scrollTo({ top: el.scrollHeight, behavior: 'smooth' });
      } catch (e) {
        el.scrollTop = el.scrollHeight;
      }
    }
    assistantMountQuestionTextarea();
  }, 0);
}

