    '<svg class="h-4 w-4" viewBox="0 0 16 16" fill="currentColor" aria-hidden="true"><path d="M6 4l4 4-4 4V4z"/></svg></button>' +
    '</div>';

  var wk =
    '<div class="mb-2 grid grid-cols-7 gap-0 text-center text-[12px] font-medium leading-none">';
  var wlabels = ['一', '二', '三', '四', '五', '六', '日'];
  var wlabelCls = ['text-[#7B92AE]', 'text-[#7B92AE]', 'text-[#7B92AE]', 'text-[#7B92AE]', 'text-[#7B92AE]', 'text-[#FF5B57]', 'text-[#FF5B57]'];
  for (var wi = 0; wi < 7; wi++) {
    wk += '<div class="flex h-8 items-center justify-center ' + wlabelCls[wi] + '">' + wlabels[wi] + '</div>';
  }
  wk += '</div>';

  var grid = '<div class="grid grid-cols-7 gap-0">';
