function openDashboardCalendar(target, ev) {
  if (ev) {
    ev.preventDefault();
    ev.stopPropagation();
  }
  closeDashboardPeriodMenu();
  var s = moduleState.dashboard;
  var ymd = target === 'to' ? (s.date_to || '').trim() : (s.date_from || '').trim();
  var now = new Date();
  if (ymd.length >= 10) {
    var p = ymd.slice(0, 10).split('-');
    dashboardCalendarState.year = parseInt(p[0], 10);
    dashboardCalendarState.month = parseInt(p[1], 10);
  } else {
    dashboardCalendarState.year = now.getFullYear();
    dashboardCalendarState.month = now.getMonth() + 1;
  }
  dashboardCalendarState.target = target;
  var pop = ensureDashboardCalendarEl();
  renderDashboardCalendarInto(pop);
  var anchorId = target === 'to' ? 'dashboard-date-to-display' : 'dashboard-date-from-display';
  var anchor = document.getElementById(anchorId);
  pop.classList.remove('hidden');
  if (anchor) {
    positionDashboardCalendarBelow(anchor, pop);
    requestAnimationFrame(function () {
      positionDashboardCalendarBelow(anchor, pop);
    });
  }

  if (!window._dashboardCalDismissBound) {
    window._dashboardCalDismissBound = true;
    window.addEventListener(
      'scroll',
      function () {
        closeDashboardCalendarPopover();
      },
      true
    );
    window.addEventListener('resize', function () {
      var p = document.getElementById('dashboard-calendar-popover');
      if (!p || p.classList.contains('hidden') || !dashboardCalendarState.target) return;
      var tid =
        dashboardCalendarState.target === 'to' ? 'dashboard-date-to-display' : 'dashboard-date-from-display';
      var a = document.getElementById(tid);
      if (a) positionDashboardCalendarBelow(a, p);
    });
  }
}

function dashboardCalendarPrevMonth(ev) {
  if (ev) ev.stopPropagation();
  var m = dashboardCalendarState.month - 1;
  var y = dashboardCalendarState.year;
  if (m < 1) {
    m = 12;
    y -= 1;
  }
  dashboardCalendarState.month = m;
  dashboardCalendarState.year = y;
  var inline = document.getElementById('dashboard-period-calendar-container');
  if (inline && moduleState.dashboard.period_detail_expanded) renderDashboardCalendarInline(inline);
  var pop = document.getElementById('dashboard-calendar-popover');
  if (pop && !pop.classList.contains('hidden')) {
    renderDashboardCalendarInto(pop);
    var aid = dashboardCalendarState.target === 'to' ? 'dashboard-date-to-display' : 'dashboard-date-from-display';
    var an = document.getElementById(aid);
    if (an) positionDashboardCalendarBelow(an, pop);
  }
}

function dashboardCalendarNextMonth(ev) {
  if (ev) ev.stopPropagation();
  var m = dashboardCalendarState.month + 1;
  var y = dashboardCalendarState.year;
  if (m > 12) {
    m = 1;
    y += 1;
  }
  dashboardCalendarState.month = m;
  dashboardCalendarState.year = y;
  var inline = document.getElementById('dashboard-period-calendar-container');
  if (inline && moduleState.dashboard.period_detail_expanded) renderDashboardCalendarInline(inline);
  var pop = document.getElementById('dashboard-calendar-popover');
  if (pop && !pop.classList.contains('hidden')) {
    renderDashboardCalendarInto(pop);
    var aid = dashboardCalendarState.target === 'to' ? 'dashboard-date-to-display' : 'dashboard-date-from-display';
    var an = document.getElementById(aid);
    if (an) positionDashboardCalendarBelow(an, pop);
  }
}

function dashboardCalendarPickDate(ev, ymd) {
  if (ev) ev.stopPropagation();
  var target = dashboardCalendarState.target;
  if (!target) return;
  moduleState.dashboard.period_kind = 'custom';
  var hk = document.getElementById('dashboard-period-kind');
  if (hk) hk.value = 'custom';
  if (target === 'from') {
    moduleState.dashboard.date_from = ymd;
    var hf = document.getElementById('dashboard-date-from');
    if (hf) hf.value = ymd;
    var selTo = (moduleState.dashboard.date_to || '').trim().slice(0, 10);
    if (selTo && selTo < ymd) {
      moduleState.dashboard.date_to = '';
      var ht = document.getElementById('dashboard-date-to');
      if (ht) ht.value = '';
    }
  } else {
    moduleState.dashboard.date_to = ymd;
    var ht2 = document.getElementById('dashboard-date-to');
    if (ht2) ht2.value = ymd;
  }
  refreshDashboardPeriodQuickChips();
  updateDashboardDateDisplayTexts();
  closeDashboardCalendarPopover();
}

function dashboardCalendarClear(ev) {
  if (ev) ev.stopPropagation();
  var target = dashboardCalendarState.target;
  if (!target) return;
  moduleState.dashboard.period_kind = 'custom';
  var hk = document.getElementById('dashboard-period-kind');
  if (hk) hk.value = 'custom';
  if (target === 'from') {
    moduleState.dashboard.date_from = '';
    var hf = document.getElementById('dashboard-date-from');
    if (hf) hf.value = '';
  } else {
    moduleState.dashboard.date_to = '';
    var ht = document.getElementById('dashboard-date-to');
    if (ht) ht.value = '';
  }
  refreshDashboardPeriodQuickChips();
  updateDashboardDateDisplayTexts();
  closeDashboardCalendarPopover();
}

function dashboardCalendarToday(ev) {
  if (ev) ev.stopPropagation();
  dashboardCalendarPickDate(ev, _dashboardTodayYmd());
}

function formatDashboardDisplayTime(iso) {
  if (iso == null || iso === '') return '--';
  try {
    var d = new Date(String(iso));
    if (isNaN(d.getTime())) return String(iso).slice(0, 19);
    return d.toLocaleString('zh-CN', { hour12: false });
  } catch (e) {
    return String(iso).slice(0, 19);
  }
}

function formatDashboardSnapshotLabel(detail) {
  if (!detail || typeof detail !== 'object') return '';
  var period = detail.period != null ? String(detail.period) : '';
  var t = formatDashboardDisplayTime(detail.created_at);
  return (period ? '周期 ' + period + ' · ' : '') + '生成于 ' + t;
}

function parseDashboardSnapshotPayload(detail) {
  if (!detail || typeof detail !== 'object') return null;
  var raw = detail.payload_json;
  if (raw === undefined || raw === null || raw === '') raw = null;
  else if (typeof raw === 'string') {
    try {
      raw = JSON.parse(raw);
    } catch (e) {
      raw = null;
    }
  }
  if (raw && typeof raw === 'object' && raw.overview) return raw;
  var dr = detail.dashboard_result_json;
  if (dr === undefined || dr === null || dr === '') dr = null;
  else if (typeof dr === 'string') {
    try {
      dr = JSON.parse(dr);
    } catch (e) {
      dr = null;
    }
  }
  if (dr && typeof dr === 'object' && dr.overview) return dr;
  if (raw && typeof raw === 'object') return raw;
  return null;
}

function refreshDashboardSnapshotsQuiet() {
  var storeId = (moduleState.dashboard.store_id || '').trim();
  var qs = storeId ? '?store_id=' + encodeURIComponent(storeId) + '&limit=30' : '?limit=30';
  return apiFetch('/api/dashboard/snapshots' + qs)
    .then(function (res) {
      if (res && res.code === 200 && res.data) {
        moduleState.dashboard.snapshotHistory = res.data.items || [];
        moduleState.dashboard.snapshotHistoryTotal = res.data.total || 0;
      }
    })
    .catch(function () {});
}

async function refreshDashboardSnapshots() {
  syncDashboardState();
  setRequestLoading('dashboardSnapshots', true);
  clearRequestError('dashboardSnapshots');
  rerenderCurrentPage();
  try {
    var storeId = (moduleState.dashboard.store_id || '').trim();
    var qs = storeId ? '?store_id=' + encodeURIComponent(storeId) + '&limit=30' : '?limit=30';
    var res = await apiFetch('/api/dashboard/snapshots' + qs);
    if (!res || res.code !== 200) throw new Error((res && res.message) || '加载失败');
    var d = res.data || {};
    moduleState.dashboard.snapshotHistory = d.items || [];
    moduleState.dashboard.snapshotHistoryTotal = d.total || 0;
  } catch (e) {
    setRequestError('dashboardSnapshots', e.message || '加载失败');
    showToast(e.message || '加载失败', 'error');
  }
  setRequestLoading('dashboardSnapshots', false);
  rerenderCurrentPage();
}

async function applyDashboardSnapshotFromHistory(snapshotId) {
  var sid = String(snapshotId || '').trim();
  if (!sid) return;
  var s = moduleState.dashboard;
  setRequestLoading('dashboardSnapshotDetail', true);
  clearRequestError('dashboardSnapshotDetail');
  rerenderCurrentPage();
  try {
    var res = await apiFetch('/api/dashboard/snapshots/' + encodeURIComponent(sid));
    if (!res || res.code !== 200) throw new Error((res && res.message) || '加载失败');
    var row = res.data;
    var payload = parseDashboardSnapshotPayload(row);
    if (!payload) throw new Error('快照数据无法解析');
    if (!s.viewingSnapshotId && s.riskResult) {
      s.cachedLiveRiskResult = s.riskResult;
      s.cachedLiveRiskMeta = s.riskMeta;
      s.cachedLiveSelectedEmployeeId = s.selected_employee_id || '';
    }
    s.riskResult = payload;
    s.riskMeta = Object.assign({}, res.meta || {}, { snapshot_view: true, snapshot_id: sid });
    s.selected_employee_id = String(payload.selected_employee_id || '').trim();
    s.viewingSnapshotId = sid;
    s.viewingSnapshotLabel = formatDashboardSnapshotLabel(row);
    showToast('已载入', 'ok');

    // Update digital human risk brief to use snapshot data
    var _snapRiskList = Array.isArray(payload.risk_list) ? payload.risk_list : [];
    window._dhRiskBrief = function () {
      if (typeof digitalHumanSpeak !== 'function') return;
      var overview = payload.overview && typeof payload.overview === 'object' ? payload.overview : {};
      var overviewHigh = overview.high_risk_count != null ? Number(overview.high_risk_count) : 0;
      var overviewMed = overview.medium_risk_count != null ? Number(overview.medium_risk_count) : 0;
      var highRisk = _snapRiskList.filter(function (e) { return String(e.risk_level || '').toLowerCase() === 'high'; });
      var medRisk = _snapRiskList.filter(function (e) { return String(e.risk_level || '').toLowerCase() === 'medium'; });
      var hCount = Math.max(highRisk.length, overviewHigh);
      var mCount = Math.max(medRisk.length, overviewMed);
      var parts = [];
      var summary = payload.summary || payload.risk_summary || '';
      if (summary) parts.push(String(summary).slice(0, 150));
      if (hCount > 0) {
        parts.push('发现' + hCount + '名高风险员工');
        if (highRisk[0] && highRisk[0].employee_name) parts.push('，包括' + highRisk.slice(0, 2).map(function (e) { return e.employee_name; }).join('、'));
        parts.push('。');
      }
      if (mCount > 0) {
        parts.push(mCount + '名中等风险。');
      }
      if (parts.length === 0) parts.push('该快照整体风险较低，团队状态良好。');
      digitalHumanSpeak(parts.join(''), { bubbleKind: 'dashboard', pose: 'agree' });
    };

    // Auto-brief for snapshot load
    setTimeout(function () {
      if (typeof digitalHumanSpeak !== 'function') return;
      var overview = payload.overview && typeof payload.overview === 'object' ? payload.overview : {};
      var overviewHigh = overview.high_risk_count != null ? Number(overview.high_risk_count) : 0;
      var overviewMed = overview.medium_risk_count != null ? Number(overview.medium_risk_count) : 0;
      var highRisk = _snapRiskList.filter(function (e) { return String(e.risk_level || '').toLowerCase() === 'high'; });
      var medRisk = _snapRiskList.filter(function (e) { return String(e.risk_level || '').toLowerCase() === 'medium'; });
      var hCount = Math.max(highRisk.length, overviewHigh);
      var mCount = Math.max(medRisk.length, overviewMed);
      var msg = '已载入历史快照。';
      if (hCount > 0) msg += '发现' + hCount + '名高风险员工，需要重点关注。';
      else if (mCount > 0) msg += mCount + '名中等风险，建议关注。';
      else msg += '整体风险较低，团队状态良好。';
      digitalHumanSpeak(msg, { bubbleKind: 'dashboard', pose: hCount > 0 ? 'think' : 'agree' });
    }, 1000);
  } catch (e) {
    setRequestError('dashboardSnapshotDetail', e.message || '加载失败');
    showToast(e.message || '加载失败', 'error');
  }
  setRequestLoading('dashboardSnapshotDetail', false);
  rerenderCurrentPage();
}

function exitDashboardSnapshotView() {
  var s = moduleState.dashboard;
  s.viewingSnapshotId = '';
  s.viewingSnapshotLabel = '';
  if (s.cachedLiveRiskResult) {
    s.riskResult = s.cachedLiveRiskResult;
    s.riskMeta = s.cachedLiveRiskMeta;
    s.selected_employee_id = s.cachedLiveSelectedEmployeeId || '';
  } else {
    s.riskResult = null;
    s.riskMeta = null;
    s.selected_employee_id = '';
  }
  s.cachedLiveRiskResult = null;
  s.cachedLiveRiskMeta = null;
  s.cachedLiveSelectedEmployeeId = '';
  rerenderCurrentPage();
}

async function submitDashboardRisk() {
  syncDashboardState();
  normalizeDashboardSelectedEmployee();
  var s = moduleState.dashboard;
  var df = (s.date_from || '').trim();
  var dt = (s.date_to || '').trim();
  var pk = (s.period_kind || '7d').trim();
  if (pk === 'custom') {
    if (df.length < 10 || dt.length < 10) {
      showToast('请选择日期', 'error');
      return;
    }
  } else if ((df && !dt) || (!df && dt)) {
    showToast('请同时选择开始与结束日期，或两者都留空以使用「近 7 天 / 近 30 天」', 'error');
    return;
  }
  if (df.length >= 10 && dt.length >= 10 && df > dt) {
    showToast('日期范围有误', 'error');
    return;
  }
  setRequestLoading('dashboardRisk', true);
  clearRequestError('dashboardRisk');
  rerenderCurrentPage();
  try {
    var payload = {
      store_id: s.store_id,
      period: s.period,
      role_scope: 'all',
    };
    if (s.selected_employee_id) {
      payload.employee_id = s.selected_employee_id;
    }
    if (df.length >= 10 && dt.length >= 10) {
      payload.date_from = df.slice(0, 10);
      payload.date_to = dt.slice(0, 10);
    }
    var res = await apiFetch('/api/dashboard/risk', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
    });
    s.riskResult = res.data || null;
    s.riskMeta = res.meta || null;
    s.viewingSnapshotId = '';
    s.viewingSnapshotLabel = '';
    s.cachedLiveRiskResult = null;
    s.cachedLiveRiskMeta = null;
    setRequestLoading('dashboardRisk', false);
    showToast('已完成', 'ok');

    // --- Risk dashboard narrator ---
    var _riskData = res.data;
    var _riskList = Array.isArray(_riskData && _riskData.risk_list) ? _riskData.risk_list : [];
    window._dhRiskBrief = function () {
      if (typeof digitalHumanSpeak !== 'function' || !_riskData) {
        if (typeof digitalHumanSpeak === 'function') digitalHumanSpeak('暂无风险数据，请先生成评估。', { bubbleKind: 'greeting', pose: 'think' });
        return;
      }
      var parts = [];
      var overview = _riskData.overview && typeof _riskData.overview === 'object' ? _riskData.overview : {};
      var overviewHigh = overview.high_risk_count != null ? Number(overview.high_risk_count) : 0;
      var overviewMed = overview.medium_risk_count != null ? Number(overview.medium_risk_count) : 0;
      var summary = _riskData.summary || _riskData.risk_summary || '';
      if (summary) {
        parts.push(String(summary).slice(0, 150));
      }
      var highRisk = _riskList.filter(function (e) { return String(e.risk_level || '').toLowerCase() === 'high'; });
      if (highRisk.length > 0 || overviewHigh > 0) {
        var hCount = Math.max(highRisk.length, overviewHigh);
        parts.push('发现' + hCount + '名高风险员工');
        if (highRisk[0] && highRisk[0].employee_name) parts.push('，包括' + highRisk.slice(0, 2).map(function (e) { return e.employee_name; }).join('、'));
        parts.push('。');
      }
      var medRisk = _riskList.filter(function (e) { return String(e.risk_level || '').toLowerCase() === 'medium'; });
      var medCount = Math.max(medRisk.length, overviewMed);
      if (medCount > 0) {
        parts.push(medCount + '名中等风险。');
      }
      if (parts.length === 0) {
        parts.push('评估已完成，整体风险较低，团队状态良好。');
      }
      digitalHumanSpeak(parts.join(''), { bubbleKind: 'dashboard', pose: 'agree' });
    };

    // Auto-brief after risk loads
    setTimeout(function () {
      if (typeof digitalHumanSpeak !== 'function' || !_riskData) return;
      var overview = _riskData.overview && typeof _riskData.overview === 'object' ? _riskData.overview : {};
      var overviewHigh = overview.high_risk_count != null ? Number(overview.high_risk_count) : 0;
      var overviewMed = overview.medium_risk_count != null ? Number(overview.medium_risk_count) : 0;
      var highRisk = _riskList.filter(function (e) { return String(e.risk_level || '').toLowerCase() === 'high'; });
      var medRisk = _riskList.filter(function (e) { return String(e.risk_level || '').toLowerCase() === 'medium'; });
      var hCount = Math.max(highRisk.length, overviewHigh);
      var mCount = Math.max(medRisk.length, overviewMed);
      var msg = '风险评估已完成。';
      if (hCount > 0) msg += '发现' + hCount + '名高风险员工，需要重点关注。';
      else if (mCount > 0) msg += mCount + '名中等风险，建议关注。';
      else msg += '整体风险较低，团队状态良好。';
      digitalHumanSpeak(msg, { bubbleKind: 'dashboard', pose: hCount > 0 ? 'think' : 'agree' });
    }, 2000);

    refreshDashboardSnapshotsQuiet().then(function () {
      rerenderCurrentPage();
    });
  } catch (e) {
    setRequestLoading('dashboardRisk', false);
    setRequestError('dashboardRisk', e.message || '加载失败');
    showToast(e.message || '加载失败', 'error');
    rerenderCurrentPage();
  }
}

function toggleDashboardSnapshotHistoryExpanded() {
  moduleState.dashboard.snapshotHistoryExpanded = !moduleState.dashboard.snapshotHistoryExpanded;
  rerenderCurrentPage();
}

function getDashboardRiskLevelMeta(level) {
  var raw = String(level == null ? '' : level).trim();
  var normalized = raw.toLowerCase();
  if (normalized === 'high' || raw.indexOf('高') !== -1) {
    return {
      key: 'high',
      label: '高风险',
      color: '#ff3b30',
      dotCls: 'db-risk-dot db-risk-dot--high',
      pillCls: 'db-risk-pill db-risk-pill--high',
    };
  }
  if (normalized === 'medium' || raw.indexOf('中') !== -1) {
    return {
      key: 'medium',
      label: '中风险',
      color: '#ff9500',
      dotCls: 'db-risk-dot db-risk-dot--medium',
      pillCls: 'db-risk-pill db-risk-pill--medium',
    };
  }
  if (normalized === 'low' || raw.indexOf('低') !== -1) {
    return {
      key: 'low',
      label: '低风险',
      color: '#34c759',
      dotCls: 'db-risk-dot db-risk-dot--low',
      pillCls: 'db-risk-pill db-risk-pill--low',
    };
  }
  return {
    key: normalized || 'unknown',
    label: raw ? '待评估' : '—',
    color: '#8e8e93',
    dotCls: 'db-risk-dot db-risk-dot--low',
    pillCls: 'db-risk-pill db-risk-pill--low',
  };
}

function dashboardRiskLevelPillHtml(level) {
  var meta = getDashboardRiskLevelMeta(level);
  return '<span class="' + meta.pillCls + '"><span class="' + meta.dotCls + '"></span>' + escapeHtml(meta.label) + '</span>';
}

function renderTalentDashboardPage(container) {
  var s = moduleState.dashboard;
  var normalizedSelectedEmployeeId = normalizeDashboardSelectedEmployee();
  var dashboardRiskLoading = requestLoading('dashboardRisk');
  var histLoading = requestLoading('dashboardSnapshots');
  var detailLoading = requestLoading('dashboardSnapshotDetail');
  var hist = s.snapshotHistory || [];
  var histTotal = s.snapshotHistoryTotal || 0;
  var histExpanded = !!s.snapshotHistoryExpanded;
  var histVisible = histExpanded || hist.length <= 3 ? hist : hist.slice(0, 3);
  var data = s.riskResult;

  // Helper: risk level color
  function riskLevelColor(level) {
    return getDashboardRiskLevelMeta(level).color;
  }
  function riskLevelLabel(level) {
    return getDashboardRiskLevelMeta(level).label;
  }

  // --- Historical banner ---
  var historicalBanner = s.viewingSnapshotId
    ? '<div class="db-snapshot-banner">' +
      '<p class="db-snapshot-label"><strong>历史快照</strong> · ' +
      escapeHtml(s.viewingSnapshotLabel || s.viewingSnapshotId) +
      '</p>' +
      '<button type="button" onclick="exitDashboardSnapshotView()" class="db-snapshot-exit">回到当前</button>' +
      '</div>'
    : '';

  // --- Filter bar: store + employee ---
  var storePickerHtml =
    '<div style="position:relative;min-width:140px;flex:1;max-width:200px">' +
    '<input type="hidden" id="dashboard-store-id" value="' + escapeHtml(s.store_id) + '" />' +
    '<div class="db-store-picker" id="db-store-picker">' +
    '<button type="button" class="db-input db-store-picker__btn" id="db-store-picker-btn" aria-haspopup="listbox" aria-expanded="false" style="display:flex;align-items:center;justify-content:space-between;cursor:pointer;border:none;background:rgba(0,0,0,0.03)">' +
    '<span id="db-store-picker-label">加载中…</span>' +
    '<svg width="12" height="12" viewBox="0 0 12 12" fill="none" style="flex-shrink:0;opacity:0.5;transition:transform 0.2s ease"><path d="M2 4L6 8L10 4" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg>' +
    '</button>' +
    '<div class="db-store-picker__list" id="db-store-picker-list" role="listbox" aria-label="选择门店"></div>' +
    '</div>' +
    '</div>';

  // Employee picker
  var empList = getDashboardVisibleEmployeeList();
  var empOptionsHtml = '<option value="">全部员工</option>';
  for (var ei = 0; ei < empList.length; ei++) {
    var emp = empList[ei];
    var empId = dashboardEmployeeIdentity(emp);
    var empName = escapeHtml(formatDashboardEmployeeLabel(emp));
    var sel = normalizedSelectedEmployeeId === empId ? ' selected' : '';
    empOptionsHtml += '<option value="' + escapeHtml(empId) + '"' + sel + '>' + empName + '</option>';
  }

  var empPickerHtml =
    '<div style="min-width:140px;flex:1;max-width:200px">' +
    '<select id="dashboard-employee-select" onchange="onDashboardEmployeeChange(this.value)" class="db-input" style="cursor:pointer;border:none;background:rgba(0,0,0,0.03);padding-right:2rem;-webkit-appearance:none;appearance:none;background-image:url(\'data:image/svg+xml;utf8,<svg width=\\\'12\\\' height=\\\'12\\\' viewBox=\\\'0 0 12 12\\\' fill=\\\'none\\\' xmlns=\\\'http://www.w3.org/2000/svg\\\'><path d=\\\'M2 4L6 8L10 4\\\' stroke=\\\'%2386868b\\\' stroke-width=\\\'1.5\\\' stroke-linecap=\\\'round\\\' stroke-linejoin=\\\'round\\\'/></svg>\');background-repeat:no-repeat;background-position:right 12px center">' +
    empOptionsHtml +
    '</select>' +
    '</div>';

  var filterBar =
    '<div class="db-card" style="overflow:visible;position:relative;z-index:2">' +
    '<div style="display:flex;align-items:center;gap:24px;flex-wrap:wrap">' +
    storePickerHtml +
    empPickerHtml +
    '<button type="button" onclick="submitDashboardRisk()" class="inline-flex items-center justify-center rounded-full bg-[#007AFF] px-8 py-3 text-[15px] font-semibold text-white hover:opacity-90 transition-opacity min-h-[44px] ml-auto"' +
    buttonDisabledAttrByState(dashboardRiskLoading) +
    '>' +
    escapeHtml(buttonLabelByState(dashboardRiskLoading, '生成评估', '生成中…')) +
    '</button>' +
    '</div>' +
    renderRequestBanner('dashboardRisk', '看板计算中…') +
    '</div>';

  // --- Core result: risk overview + follow-up (4:6) ---
  var coreResultHtml = '';
  if (dashboardRiskLoading) {
    coreResultHtml =
      '<div class="db-card" style="display:flex;align-items:center;justify-content:center;min-height:320px">' +
      '<div style="text-align:center">' +
      '<div class="db-spinner" style="margin:0 auto 12px"></div>' +
      '<p style="margin:0;font-size:15px;color:#6e6e73">正在生成评估结果...</p>' +
      '</div>' +
      '</div>';
  } else if (!data || !data.risk_list || !data.risk_list.length) {
    coreResultHtml =
      '<div class="db-card" style="display:flex;align-items:center;justify-content:center;min-height:240px">' +
      '<p style="margin:0;font-size:15px;color:#6e6e73">' +
      (data ? '暂无数据' : '选择门店和员工后将自动生成评估结果') +
      '</p>' +
      '</div>';
  } else {
    var allRiskItems = dashboardDedupRiskItems(Array.isArray(data.risk_list) ? data.risk_list : []);
    var highRiskItems = [];
    for (var hri = 0; hri < allRiskItems.length; hri++) {
      if (getDashboardRiskLevelMeta(allRiskItems[hri] && allRiskItems[hri].risk_level).key === 'high') {
        highRiskItems.push(allRiskItems[hri]);
      }
    }
    var overviewData = data.overview && typeof data.overview === 'object' ? data.overview : {};
    var overviewTotalPeople = overviewData.total_people != null ? parseInt(overviewData.total_people, 10) : allRiskItems.length;
    if (!isFinite(overviewTotalPeople)) overviewTotalPeople = allRiskItems.length;
    var overviewHighCount = overviewData.high_risk_count != null ? parseInt(overviewData.high_risk_count, 10) : highRiskItems.length;
    if (!isFinite(overviewHighCount)) overviewHighCount = highRiskItems.length;
    if (!s.viewingSnapshotId && !normalizedSelectedEmployeeId) {
      var liveVisibleEmployeeCount = getDashboardVisibleEmployeeList().length;
      if (liveVisibleEmployeeCount > 0) {
        overviewTotalPeople = liveVisibleEmployeeCount;
      }
      overviewHighCount = highRiskItems.length;
    }
    var detailMismatch = !!s.viewingSnapshotId && (
      overviewTotalPeople > allRiskItems.length ||
      overviewHighCount > highRiskItems.length
    );

    // Pick the selected employee or first from list
    var riskItem = null;
    var selEmpId = s.selected_employee_id;
    if (selEmpId) {
      for (var ri = 0; ri < data.risk_list.length; ri++) {
        if (String(data.risk_list[ri].employee_id || '') === selEmpId) {
          riskItem = data.risk_list[ri];
          break;
        }
      }
    }
    if (!riskItem) {
      riskItem = allRiskItems[0];
    }

    var rLevel = riskLevelLabel(riskItem.risk_level);
    var rColor = riskLevelColor(riskItem.risk_level);
    var rScore = riskItem.risk_score != null ? riskItem.risk_score : '--';
    var panelSummary = escapeHtml((riskItem.panel_summary || '').replace(/\bhigh\b/g, '高').replace(/\bmedium\b/g, '中').replace(/\blow\b/g, '低'));
    var tags = riskItem.dashboard_tags || [];
    var tagsHtml = '';
    for (var ti = 0; ti < tags.length; ti++) {
      tagsHtml += '<span style="display:inline-block;background:#f5f5f7;border-radius:8px;padding:4px 10px;font-size:12px;color:#1d1d1f;margin:0 8px 6px 0">' + escapeHtml(String(tags[ti])) + '</span>';
    }

    var followup = escapeHtml(riskItem.follow_up_action || '');
    var nextAction = escapeHtml(riskItem.next_action || '--');
    var actionWindow = escapeHtml(riskItem.action_window || '--');
    var coachingFocus = escapeHtml(riskItem.coaching_focus || '--');
    var employeeName = escapeHtml(dashboardDisplayEmployeeName(riskItem));
    var employeeNo = escapeHtml(riskItem.employee_no || dashboardEmployeeNo(riskItem) || '--');
    var employeePosition = escapeHtml(dashboardDisplayPosition(riskItem));
    var rosterItems = allRiskItems;
    var rosterTitle = '全部员工';
    var rosterCount = rosterItems.length;
    var rosterSubtitle = normalizedSelectedEmployeeId ? '已按风险排序，当前高亮选中员工' : '已按风险由高到低展示全部员工';
    var rosterCardsHtml = '';
    if (allRiskItems.length > 1) {
      rosterCardsHtml +=
        '<button type="button" onclick="focusDashboardRiskEmployee(\'\')" style="border:1px solid ' +
        (selEmpId ? 'rgba(60,60,67,0.12)' : 'rgba(29,29,31,0.18)') +
        ';text-align:left;border-radius:20px;padding:16px 18px;cursor:pointer;background:#ffffff;color:#1d1d1f;box-shadow:' +
        (selEmpId ? '0 8px 20px rgba(15,23,42,0.04)' : '0 10px 24px rgba(15,23,42,0.06)') +
        ';font-family:inherit;min-height:140px">' +
        '<div style="display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:14px">' +
        '<span style="font-size:16px;font-weight:700">查看全部</span>' +
        '<span style="display:inline-flex;align-items:center;border-radius:999px;padding:6px 12px;font-size:12px;font-weight:600;background:#f5f5f7;color:#6e6e73">门店总览</span>' +
        '</div>' +
        '<p style="margin:0 0 10px;font-size:13px;line-height:1.6;color:#6e6e73">直接回看本次快照的整体分布和排序结果</p>' +
        '<div style="display:flex;gap:10px;flex-wrap:wrap">' +
        '<span style="font-size:12px;color:#6e6e73">高风险 ' + escapeHtml(String(overviewHighCount)) + '</span>' +
        '<span style="font-size:12px;color:#6e6e73">总人数 ' + escapeHtml(String(overviewTotalPeople)) + '</span>' +
        '</div>' +
        '</button>';
    }
    for (var rsi = 0; rsi < rosterItems.length; rsi++) {
      var rosterItem = rosterItems[rsi] || {};
      var rosterEmpId = String(rosterItem.employee_id || '').trim();
      if (!rosterEmpId) continue;
      var rosterMeta = getDashboardRiskLevelMeta(rosterItem.risk_level);
      var isRosterActive = selEmpId === rosterEmpId || (!selEmpId && riskItem === rosterItem);
      var rosterScore = rosterItem.risk_score != null && rosterItem.risk_score !== '' ? String(rosterItem.risk_score) : '--';
      var rosterFocus = escapeHtml(rosterItem.coaching_focus || '--');
      var rosterAction = escapeHtml(rosterItem.next_action || rosterItem.follow_up_action || '--');
      var rosterName = escapeHtml(dashboardDisplayEmployeeName(rosterItem));
      var rosterNo = escapeHtml(rosterItem.employee_no || dashboardEmployeeNo(rosterItem) || '--');
      var rosterPosition = escapeHtml(dashboardDisplayPosition(rosterItem));
      var rosterSummary = escapeHtml((rosterItem.panel_summary || rosterItem.risk_reason || '').slice(0, 42));
      rosterCardsHtml +=
        '<button type="button" onclick="focusDashboardRiskEmployee(\'' + escapeHtml(rosterEmpId) + '\')" style="border:1px solid ' +
        (isRosterActive ? 'rgba(29,29,31,0.18)' : 'rgba(60,60,67,0.12)') +
        ';text-align:left;border-radius:20px;padding:18px;cursor:pointer;background:#ffffff;color:#1d1d1f;box-shadow:' +
        (isRosterActive ? '0 12px 28px rgba(15,23,42,0.08)' : '0 8px 20px rgba(15,23,42,0.04)') +
        ';font-family:inherit;min-height:180px">' +
        '<div style="display:flex;align-items:flex-start;justify-content:space-between;gap:12px;margin-bottom:14px">' +
        '<div>' +
        '<p style="margin:0 0 6px;font-size:18px;font-weight:700;color:inherit">' + rosterName + '</p>' +
        '<p style="margin:0;font-size:12px;color:#6e6e73">' + rosterNo + ' · ' + rosterPosition + '</p>' +
        '</div>' +
        '<span style="display:inline-flex;align-items:center;border-radius:999px;padding:6px 12px;font-size:12px;font-weight:600;background:#f5f5f7;color:#424245">' + escapeHtml(rosterMeta.label) + '</span>' +
        '</div>' +
        '<div style="display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin-bottom:14px">' +
        '<div style="border-radius:14px;padding:12px;background:#f5f5f7">' +
        '<p style="margin:0 0 4px;font-size:11px;color:#8e8e93">风险分</p>' +
        '<p style="margin:0;font-size:18px;font-weight:700;color:inherit">' + escapeHtml(rosterScore) + '</p>' +
        '</div>' +
        '<div style="border-radius:14px;padding:12px;background:#f5f5f7">' +
        '<p style="margin:0 0 4px;font-size:11px;color:#8e8e93">辅导重点</p>' +
        '<p style="margin:0;font-size:13px;font-weight:600;color:inherit;line-height:1.4">' + rosterFocus + '</p>' +
        '</div>' +
        '</div>' +
        '<p style="margin:0 0 10px;font-size:13px;line-height:1.6;color:#424245">' + (rosterSummary || '暂无补充说明') + '</p>' +
        '<p style="margin:0;font-size:12px;color:#6e6e73">下一步：' + rosterAction + '</p>' +
        '</button>';
    }
    var rosterCard = '';
    if (rosterCardsHtml) {
      rosterCard =
        '<div class="db-card" style="margin-bottom:24px">' +
        '<div style="display:flex;align-items:flex-start;justify-content:space-between;gap:16px;flex-wrap:wrap;margin-bottom:12px">' +
        '<div>' +
        '<p style="margin:0 0 8px;font-size:16px;font-weight:700;color:#1d1d1f">' + escapeHtml(rosterTitle) + '</p>' +
        '<p style="margin:0;font-size:14px;color:#6e6e73">当前展示 ' + escapeHtml(String(rosterCount)) + ' / ' + escapeHtml(String(overviewTotalPeople)) + ' 人，' + escapeHtml(rosterSubtitle) + (detailMismatch ? ' 当前仅恢复出 ' + escapeHtml(String(rosterItems.length)) + ' 人明细' : '') + '</p>' +
        '</div>' +
        '</div>' +
        '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px">' + rosterCardsHtml + '</div>' +
        '</div>';
    }
    var detailNotice = detailMismatch
      ? '<div class="db-card" style="margin-bottom:24px;border:1px solid rgba(60,60,67,0.12);box-shadow:none">' +
        '<p style="margin:0;font-size:14px;color:#6e6e73;line-height:1.6">这条历史快照的汇总统计是完整的，但员工明细只保存了部分记录，所以会出现“高' + escapeHtml(String(overviewHighCount)) + '”而姓名不全的情况</p>' +
        '</div>'
      : '';
    var identityTitle = selEmpId ? '评估对象' : (allRiskItems.length > 1 ? '当前查看员工' : '评估对象');
    var identityCard =
      '<div class="db-card" style="margin-bottom:24px">' +
      '<div style="display:flex;align-items:flex-start;justify-content:space-between;gap:16px;flex-wrap:wrap">' +
      '<div>' +
      '<p style="margin:0 0 8px;font-size:16px;font-weight:700;color:#1d1d1f">' + identityTitle + '</p>' +
      '<p style="margin:0;font-size:22px;font-weight:700;color:#1d1d1f">' + employeeName + '</p>' +
      '</div>' +
      '<div style="display:flex;gap:20px;flex-wrap:wrap">' +
      '<div>' +
      '<p style="margin:0 0 4px;font-size:12px;color:#8e8e93">工号</p>' +
      '<p style="margin:0;font-size:14px;color:#1d1d1f">' + employeeNo + '</p>' +
      '</div>' +
      '<div>' +
      '<p style="margin:0 0 4px;font-size:12px;color:#8e8e93">岗位</p>' +
      '<p style="margin:0;font-size:14px;color:#1d1d1f">' + employeePosition + '</p>' +
      '</div>' +
      '</div>' +
      '</div>' +
      '</div>';

    // Left: risk overview
    var leftCard =
      '<div style="flex:0 0 40%;max-width:40%;min-width:0">' +
      '<div class="db-card" style="height:100%">' +
      '<p style="margin:0 0 20px;font-size:16px;font-weight:700;color:#1d1d1f">风险概览</p>' +
      '<p style="margin:0 0 8px;font-size:24px;font-weight:700;color:' + rColor + '">' + escapeHtml(rLevel) + '</p>' +
      '<p style="margin:0 0 20px;font-size:14px;color:#6e6e73">风险评分：' + escapeHtml(String(rScore)) + '分</p>' +
      (panelSummary ? '<p style="margin:0 0 20px;font-size:16px;color:#1d1d1f;line-height:1.4">' + panelSummary + '</p>' : '') +
      (tagsHtml ? '<div style="display:flex;flex-wrap:wrap;align-items:center">' + tagsHtml + '</div>' : '') +
      '</div>' +
      '</div>';

    // Right: follow-up advice
    var rightCard =
      '<div style="flex:0 0 58%;max-width:58%;min-width:0">' +
      '<div class="db-card" style="height:100%">' +
      '<p style="margin:0 0 20px;font-size:16px;font-weight:700;color:#1d1d1f">跟进建议</p>' +
      (followup ? '<p style="margin:0 0 20px;font-size:18px;color:#1d1d1f;line-height:1.4">' + followup + '</p>' : '') +
      '<div style="display:flex;flex-direction:column;gap:12px">' +
      '<div style="display:flex;justify-content:space-between;align-items:center">' +
      '<span style="font-size:14px;color:#6e6e73">下一步动作</span>' +
      '<span style="font-size:14px;font-weight:600;color:#1d1d1f">' + nextAction + '</span>' +
      '</div>' +
      '<div style="display:flex;justify-content:space-between;align-items:center">' +
      '<span style="font-size:14px;color:#6e6e73">执行窗口期</span>' +
      '<span style="font-size:14px;font-weight:600;color:#1d1d1f">' + actionWindow + '</span>' +
      '</div>' +
      '<div style="display:flex;justify-content:space-between;align-items:center">' +
      '<span style="font-size:14px;color:#6e6e73">重点辅导维度</span>' +
      '<span style="font-size:14px;font-weight:600;color:#1d1d1f">' + coachingFocus + '</span>' +
      '</div>' +
      '</div>' +
      '</div>' +
      '</div>';

    coreResultHtml =
      detailNotice +
      rosterCard +
      identityCard +
      '<div style="display:flex;gap:2%;align-items:stretch">' + leftCard + rightCard + '</div>';

    // --- Risk detail card ---
    var riskReason = escapeHtml(riskItem.risk_reason || '');
    var observationNote = '';
    if (data.workflow_stats && data.workflow_stats.fallback_count > 0) {
      observationNote = '评估基于本地规则生成，建议持续跟进观察';
    }
    // Check for observation_note in raw data
    var rawData = s.riskMeta || {};
    if (rawData.observation_note) {
      observationNote = escapeHtml(rawData.observation_note);
    }

    coreResultHtml +=
      '<div class="db-card" style="margin-top:24px">' +
      '<p style="margin:0 0 16px;font-size:16px;font-weight:700;color:#1d1d1f">风险详情</p>' +
      (riskReason ? '<p style="margin:0 0 12px;font-size:15px;color:#1d1d1f;line-height:1.5">风险原因：' + riskReason + '</p>' : '') +
      (observationNote ? '<p style="margin:16px 0 0;font-size:15px;color:#424245;line-height:1.5">补充说明：' + observationNote + '</p>' : '') +
      '</div>';
  }

  // --- History section ---
  var histRows = '';
  for (var hi = 0; hi < histVisible.length; hi++) {
    var row = histVisible[hi];
    var ov = row.overview || {};
    var sid = row.snapshot_id || '';
    var isActiveSnapshot = s.viewingSnapshotId === sid;
    var highR = ov.high_risk_count != null ? ov.high_risk_count : '--';
    var medR = ov.medium_risk_count != null ? ov.medium_risk_count : '--';
    var lowR = ov.low_risk_count != null ? ov.low_risk_count : '--';

    histRows +=
      '<div style="display:flex;align-items:center;justify-content:space-between;padding:16px 0;border-bottom:1px solid #f0f0f0;gap:16px;flex-wrap:wrap' +
      (isActiveSnapshot ? ';background:rgba(0,122,255,0.04);padding:16px;border-radius:10px' : '') +
      '">' +
      '<span style="font-size:14px;color:#1d1d1f;white-space:nowrap">' + escapeHtml(formatDashboardDisplayTime(row.created_at)) + '</span>' +
      '<span style="font-size:14px;color:#6e6e73;white-space:nowrap">高' + escapeHtml(String(highR)) + ' · 中' + escapeHtml(String(medR)) + ' · 低' + escapeHtml(String(lowR)) + '</span>' +
      '<button type="button" onclick="applyDashboardSnapshotFromHistory(\'' + escapeHtml(sid) + '\')" style="border:none;background:none;color:#007AFF;font-size:14px;cursor:pointer;padding:0;font-family:inherit;opacity:1;transition:opacity 0.15s"' +
      (isActiveSnapshot ? ' aria-current="true"' : '') +
      ' onmouseover="this.style.opacity=0.7" onmouseout="this.style.opacity=1"' +
      '>' +
      (isActiveSnapshot ? '查看中' : '查看详情') +
      '</button>' +
      '</div>';
  }

  var historyExpandRow = '';
  if (!histLoading && hist.length > 3) {
    historyExpandRow =
      '<button type="button" onclick="toggleDashboardSnapshotHistoryExpanded()" style="border:none;background:none;color:#007AFF;font-size:14px;cursor:pointer;padding:8px 0;font-family:inherit;width:100%;text-align:right;transition:opacity 0.15s" onmouseover="this.style.opacity=0.7" onmouseout="this.style.opacity=1">' +
      escapeHtml(histExpanded ? '收起' : '展开更多') +
      '</button>';
  }

  var historySection = '';
  if (histLoading) {
    historySection =
      '<div class="db-card" style="display:flex;align-items:center;justify-content:center;min-height:120px">' +
      '<p style="margin:0;font-size:14px;color:#6e6e73">加载中…</p>' +
      '</div>';
  } else if (hist.length > 0) {
    historySection =
      '<div class="db-card" style="margin-top:32px">' +
      '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px">' +
      '<p style="margin:0;font-size:16px;font-weight:700;color:#1d1d1f">历史评估记录</p>' +
      '</div>' +
      histRows +
      historyExpandRow +
      '<p style="margin:12px 0 0;text-align:center;font-size:13px;color:#6e6e73">共' + escapeHtml(String(histTotal || hist.length)) + '条，展示最近' + escapeHtml(String(Math.min(3, hist.length))) + '条</p>' +
      '</div>';
  }

  // --- Overview stats (high/medium/low) as inline summary ---
  var overviewHtml = '';
  if (data && data.overview) {
    var ov2 = data.overview;
    overviewHtml =
      '<div style="display:flex;gap:24px;flex-wrap:wrap;margin-bottom:24px">' +
      '<div style="font-size:14px;color:#6e6e73">在训 <span style="font-weight:700;color:#1d1d1f">' + escapeHtml(String(ov2.total_people != null ? ov2.total_people : '--')) + '</span></div>' +
      '<div style="font-size:14px;color:#6e6e73">高风险 <span style="font-weight:700;color:#ff3b30">' + escapeHtml(String(ov2.high_risk_count != null ? ov2.high_risk_count : '--')) + '</span></div>' +
      '<div style="font-size:14px;color:#6e6e73">中风险 <span style="font-weight:700;color:#ff9500">' + escapeHtml(String(ov2.medium_risk_count != null ? ov2.medium_risk_count : '--')) + '</span></div>' +
      '<div style="font-size:14px;color:#6e6e73">低风险 <span style="font-weight:700;color:#34c759">' + escapeHtml(String(ov2.low_risk_count != null ? ov2.low_risk_count : '--')) + '</span></div>' +
      '</div>';
  }

  // --- Compose full page ---
  container.innerHTML =
    '<div class="db-page">' +
    '<div class="app-page-shell app-page-shell--xl space-y-6">' +
    /* 1. Title */
    '<header class="app-page-header">' +
    '<h1 class="app-page-title">风险看板</h1>' +
    '</header>' +
    historicalBanner +
    /* 2. Filter bar */
    filterBar +
    /* 3. Overview stats */
    overviewHtml +
    /* 4. Core results */
    coreResultHtml +
    /* 5. History */
    historySection +
    '</div></div>';

  // Post-render init
  setTimeout(function () {
    initDashboardStorePicker();
    _dbFetchEmployeeList();
    if (moduleState.dashboard.needSnapshotAutoFetch) {
      moduleState.dashboard.needSnapshotAutoFetch = false;
      syncDashboardState();
      refreshDashboardSnapshotsQuiet().then(function () {
        if (currentPage === 'talent_dashboard') {
          rerenderCurrentPage();
        }
      });
    }
  }, 0);
}

// Fetch employee list for the employee dropdown
function _dbFetchEmployeeList() {
  apiFetch('/api/users').then(function (j) {
    if (j && j.code === 200 && j.data && j.data.items) {
      moduleState.dashboard.employeeList = j.data.items || [];
      refreshDashboardEmployeeSelect();
    }
  }).catch(function () {});
}

// Handle employee dropdown change
function onDashboardEmployeeChange(val) {
  moduleState.dashboard.selected_employee_id = val || '';
}

function focusDashboardRiskEmployee(val) {
  onDashboardEmployeeChange(val || '');
  rerenderCurrentPage();
}

function renderPersonnelManage(container) {
  var fontStack =
    "font-family: -apple-system, BlinkMacSystemFont, 'SF Pro Text', 'PingFang SC', 'Helvetica Neue', Helvetica, Arial, sans-serif;";

  container.innerHTML =
    '<section class="w-full bg-transparent text-[#1D1D1F]" style="' +
    fontStack +
    '">' +
    '<div class="personnel-list-viewport">' +
    '<header class="app-page-header">' +
    '<h1 class="app-page-title">人员管理</h1>' +
    '</header>' +
    '<div class="bg-white rounded-2xl shadow-sm p-4 sm:p-6">' +
    '<div class="flex flex-col gap-4 sm:flex-row sm:items-start sm:gap-5">' +
    '<div class="w-12 h-12 bg-blue-50 text-blue-500 rounded-2xl flex items-center justify-center flex-shrink-0">' +
    '<svg class="w-6 h-6" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24">' +
    '<path stroke-linecap="round" stroke-linejoin="round" d="M15.75 6a3.75 3.75 0 11-7.5 0 3.75 3.75 0 017.5 0zM4.501 20.118a7.5 7.5 0 0114.998 0A17.933 17.933 0 0112 21.75c-2.676 0-5.216-.584-7.499-1.632z"/>' +
    '</svg>' +
    '</div>' +
    '<div class="flex-1">' +
    '<h2 class="text-xl font-bold text-gray-800">员工账号</h2>' +
    '<div class="mt-5 flex flex-wrap items-center gap-2.5 personnel-toolbar-row">' +
    '<button type="button" onclick="openAddUserModal()" class="personnel-toolbar-pill bg-[#007AFF] text-white rounded-full px-5 py-2 text-sm font-medium hover:bg-[#0066d6] transition-colors">新增员工账号</button>' +
    '<button type="button" onclick="openPersonnelRolesModal()" class="personnel-toolbar-pill bg-gray-100 text-gray-700 rounded-full px-5 py-2 text-sm font-medium hover:bg-gray-200 transition-colors">角色管理</button>' +
    '<select id="personnel-filter-store" class="capsule-select personnel-filter-pill"><option value="">全部门店</option></select>' +
    '<select id="personnel-filter-role" class="capsule-select personnel-filter-pill"><option value="">全部角色</option></select>' +
    '</div>' +
    '</div>' +
    '</div>' +
    '</div>' +
    '<div class="bg-white rounded-2xl shadow-sm overflow-hidden p-4 sm:p-6 flex-1 min-h-0 flex flex-col">' +
    '<div class="flex flex-wrap items-center gap-3 mb-4">' +
    '<h3 class="text-lg font-bold text-gray-800">员工列表</h3>' +
    '<div class="flex-1"></div>' +
    '<div class="relative w-full sm:w-auto">' +
    '<svg class="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400 pointer-events-none" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/></svg>' +
    '<input id="personnel-search" type="text" placeholder="搜索姓名 / 工号 / 手机号" class="h-10 w-full sm:w-56 rounded-lg border border-gray-200 bg-gray-50 pl-9 pr-3 text-sm text-gray-700 placeholder:text-gray-400 focus:border-blue-400 focus:outline-none focus:ring-1 focus:ring-blue-400/30" />' +
    '</div>' +
    '</div>' +
    '<div id="personnel-table-wrap" class="flex-1 min-h-0 overflow-y-auto">' +
    '<div class="flex items-center justify-center min-h-[11rem]" id="personnel-table-loading">' +
    '<span class="text-gray-400 text-sm">加载中...</span>' +
    '</div>' +
    '<div id="personnel-table-error" class="hidden px-6 py-8 text-center">' +
    '<p class="text-red-500 text-sm" id="personnel-table-error-msg"></p>' +
    '</div>' +
    '<div id="personnel-table-empty" class="hidden px-6 py-8 text-center">' +
    '<p class="text-gray-400 text-sm">暂无员工</p>' +
    '</div>' +
    '<div id="personnel-table-container" class="hidden overflow-x-auto"></div>' +
    '</div>' +
    '</div>' +
    '</div>' +
    '</section>';

  // Fetch and render user list
  apiFetch('/api/users')
    .then(function (j) {
      if (!j || Number(j.code) !== 200) {
        throw new Error((j && j.message) || '加载失败');
      }
      return j.data && j.data.items ? j.data.items : [];
    })
    .then(function (users) {
      cachePersonnelUsers(users || []);
      buildPersonnelFilterOptions(users);
      renderPersonnelTable(users);
    })
    .catch(function (err) {
      var wrap = document.getElementById('personnel-table-wrap');
      if (!wrap) return;
      var errEl = document.getElementById('personnel-table-error');
      var msgEl = document.getElementById('personnel-table-error-msg');
      var loadEl = document.getElementById('personnel-table-loading');
      if (loadEl) loadEl.classList.add('hidden');
      if (errEl) errEl.classList.remove('hidden');
      if (msgEl) msgEl.textContent = err.message || '加载失败';
    });

  // Filter listeners
  var searchEl = document.getElementById('personnel-search');
  var storeFilterEl = document.getElementById('personnel-filter-store');
  var roleFilterEl = document.getElementById('personnel-filter-role');
  var _personnelFilterTimer = null;
  function applyPersonnelFilters() {
    clearTimeout(_personnelFilterTimer);
    _personnelFilterTimer = setTimeout(function () {
      var all = window._allPersonnelUsers || [];
      var q = (searchEl && searchEl.value || '').trim().toLowerCase();
      var storeFilter = storeFilterEl ? storeFilterEl.value : '';
      var roleFilter = roleFilterEl ? roleFilterEl.value : '';
      var filtered = all.filter(function (u) {
        if (storeFilter && (u.store_id || '') !== storeFilter) return false;
        if (roleFilter && (u.role || '') !== roleFilter) return false;
        if (q) {
          var hay = [u.display_name, u.username, u.employee_no, u.phone, u.store_label].join(' ').toLowerCase();
          return hay.indexOf(q) !== -1;
        }
        return true;
      });
      renderPersonnelTable(filtered);
    }, 200);
  }
  if (searchEl) searchEl.addEventListener('input', applyPersonnelFilters);
  if (storeFilterEl) storeFilterEl.addEventListener('change', applyPersonnelFilters);
  if (roleFilterEl) roleFilterEl.addEventListener('change', applyPersonnelFilters);
}

function buildPersonnelFilterOptions(users) {
  var storeFilterEl = document.getElementById('personnel-filter-store');
  var roleFilterEl = document.getElementById('personnel-filter-role');
  if (storeFilterEl) {
    var seen = {};
    var opts = '<option value="">全部门店</option>';
    for (var i = 0; i < users.length; i++) {
      var sid = users[i].store_id || '';
      if (!sid || seen[sid]) continue;
      seen[sid] = true;
      opts += '<option value="' + escapeHtml(sid) + '">' + escapeHtml(users[i].store_label || sid) + '</option>';
    }
    storeFilterEl.innerHTML = opts;
  }
  if (roleFilterEl) {
    var opts2 = '<option value="">全部角色</option>';
    var keys = Object.keys(ROLE_LABELS);
    for (var j = 0; j < keys.length; j++) {
      opts2 += '<option value="' + escapeHtml(keys[j]) + '">' + escapeHtml(ROLE_LABELS[keys[j]]) + '</option>';
    }
    roleFilterEl.innerHTML = opts2;
  }
}

function renderPersonnelTable(users) {
  var loadEl = document.getElementById('personnel-table-loading');
  var emptyEl = document.getElementById('personnel-table-empty');
  var container = document.getElementById('personnel-table-container');
  if (!container) return;
  if (loadEl) loadEl.classList.add('hidden');

  var isAdmin = isActorAdmin();

  if (!users || users.length === 0) {
    if (emptyEl) emptyEl.classList.remove('hidden');
    return;
  }
  if (emptyEl) emptyEl.classList.add('hidden');
  container.classList.remove('hidden');

  if (isPhoneViewport()) {
    var mobileHtml = '<div class="personnel-mobile-list">';
    for (var mi = 0; mi < users.length; mi++) {
      var user = users[mi];
      var userEmpNo = escapeHtml(String(user.employee_no || user.id || ''));
      var userName = escapeHtml(user.display_name || user.username || '');
      var userRole = escapeHtml(ROLE_LABELS[user.role] || user.role || '');
      var userStore = escapeHtml(user.store_label || user.store_id || '—');
      var userPhone = escapeHtml(user.phone || '—');
      var userCreated = user.created_at ? escapeHtml(user.created_at.substr(0, 10)) : '—';
      mobileHtml +=
        '<article class="personnel-mobile-card rounded-[24px] border border-slate-200 bg-white p-4 shadow-[0_10px_24px_rgba(15,23,42,0.04)]">' +
          '<div class="flex items-start justify-between gap-3">' +
            '<div class="min-w-0">' +
              '<div class="text-[11px] font-semibold tracking-[0.08em] text-slate-400">' + userEmpNo + '</div>' +
              '<h3 class="mt-1 text-base font-semibold text-slate-900">' + userName + '</h3>' +
              '<p class="mt-1 text-sm text-slate-500">' + userRole + '</p>' +
            '</div>' +
            '<div class="shrink-0 rounded-full border border-slate-200 bg-slate-50 px-3 py-1 text-xs font-medium text-slate-500">' + userRole + '</div>' +
          '</div>' +
          '<div class="personnel-mobile-meta mt-4 grid grid-cols-2 gap-3 text-sm">' +
            '<div class="rounded-2xl bg-slate-50 px-3 py-3"><div class="text-[11px] text-slate-400">门店</div><div class="mt-1 font-medium text-slate-800">' + userStore + '</div></div>' +
            '<div class="rounded-2xl bg-slate-50 px-3 py-3"><div class="text-[11px] text-slate-400">手机</div><div class="mt-1 font-medium text-slate-800">' + userPhone + '</div></div>' +
            '<div class="rounded-2xl bg-slate-50 px-3 py-3 col-span-2"><div class="text-[11px] text-slate-400">创建时间</div><div class="mt-1 font-medium text-slate-800">' + userCreated + '</div></div>' +
          '</div>' +
          '<div class="personnel-mobile-actions mt-4 flex flex-wrap gap-2">' +
            '<button type="button" onclick="openEditUserModal(' + mi + ')" class="store-mgm-action-btn store-mgm-action-btn--accent inline-flex min-h-[42px] flex-1 items-center justify-center gap-1 rounded-xl px-4 py-2 text-sm font-medium bg-blue-50 text-blue-600 transition-colors">编辑</button>';
      if (isAdmin) {
        var mobileDelId = escapeHtml(String(user.id != null ? user.id : ''));
        var mobileDelLabel = escapeHtml(String(user.display_name || user.username || ''));
        mobileHtml +=
            '<button type="button" data-action="delete-personnel-user" data-user-id="' + mobileDelId + '" data-label="' + mobileDelLabel + '" class="store-mgm-action-btn store-mgm-action-btn--danger inline-flex min-h-[42px] flex-1 items-center justify-center gap-1 rounded-xl px-4 py-2 text-sm font-medium bg-red-50 text-red-600 transition-colors">删除</button>';
      }
      mobileHtml +=
            '<button type="button" onclick="openEmployeeJourney(\'' + escapeJs(String(user.id || user.username || '')) + '\')" class="store-mgm-action-btn inline-flex min-h-[42px] flex-1 items-center justify-center gap-1 rounded-xl px-4 py-2 text-sm font-medium bg-emerald-50 text-emerald-700 transition-colors">成长之旅</button>' +
          '</div>' +
        '</article>';
    }
    window._personnelUsers = users;
    mobileHtml += '</div>';
    container.innerHTML = mobileHtml;
    return;
  }

  var thClass = 'px-4 py-3 text-left ios-table-head bg-gray-50 whitespace-nowrap border-b border-gray-100';
  var tdClass = 'px-4 py-4 text-sm text-gray-700 whitespace-nowrap';
  var trClass = 'border-b border-gray-100 hover:bg-gray-50 transition-colors';

  var html =
    '<table class="w-full text-left">' +
    '<thead>' +
    '<tr>' +
    '<th class="' + thClass + '">工号</th>' +
    '<th class="' + thClass + '">姓名</th>' +
    '<th class="' + thClass + '">角色</th>' +
    '<th class="' + thClass + '">门店</th>' +
    '<th class="' + thClass + '">手机</th>' +
    '<th class="' + thClass + '">创建时间</th>' +
    '<th class="' + thClass + '">操作</th>' +
    '</tr>' +
    '</thead>' +
    '<tbody>';

  for (var i = 0; i < users.length; i++) {
    var u = users[i];
    var empNo = u.employee_no || u.id || '';
    var name = escapeHtml(u.display_name || u.username || '');
    var role = escapeHtml(ROLE_LABELS[u.role] || u.role || '');
    var store = escapeHtml(u.store_label || u.store_id || '—');
    var phone = escapeHtml(u.phone || '—');
    var created = u.created_at ? escapeHtml(u.created_at.substr(0, 10)) : '—';

    html += '<tr class="' + trClass + '">';
    html += '<td class="' + tdClass + ' font-mono text-gray-500">' + empNo + '</td>';
    html += '<td class="' + tdClass + ' font-medium">' + name + '</td>';
    html += '<td class="' + tdClass + '">' + role + '</td>';
    html += '<td class="' + tdClass + '">' + store + '</td>';
    html += '<td class="' + tdClass + '">' + phone + '</td>';
    html += '<td class="' + tdClass + ' text-gray-400">' + created + '</td>';
    html += '<td class="' + tdClass + '">';
    html += '<button type="button" onclick="openEditUserModal(' + i + ')" class="store-mgm-action-btn store-mgm-action-btn--accent inline-flex items-center gap-1 rounded-lg px-3 py-1.5 text-xs font-medium bg-blue-50 text-blue-600 transition-colors">编辑</button>';
    html += '<button type="button" onclick="openEmployeeJourney(\'' + escapeJs(String(u.id || u.username || '')) + '\')" class="store-mgm-action-btn ml-1 inline-flex items-center gap-1 rounded-lg px-3 py-1.5 text-xs font-medium bg-emerald-50 text-emerald-700 transition-colors">成长之旅</button>';
    if (isAdmin) {
      var delId = escapeHtml(String(u.id != null ? u.id : ''));
      var delLabel = escapeHtml(String(u.display_name || u.username || ''));
      html +=
        '<button type="button" data-action="delete-personnel-user" data-user-id="' +
        delId +
        '" data-label="' +
        delLabel +
        '" class="store-mgm-action-btn store-mgm-action-btn--danger ml-1 inline-flex items-center gap-1 rounded-lg px-3 py-1.5 text-xs font-medium bg-red-50 text-red-600 transition-colors">删除</button>';
    }
    html += '</td>';
    html += '</tr>';
  }

  // Store users globally for edit modal lookup
  window._personnelUsers = users;

  html += '</tbody></table>';
  container.innerHTML = html;
}

// ===================== Store Management Page Functions =====================

// Store management state
window._storeMgm = {
  stores: [],
  loading: false,
  editingStore: null,
  formModalOpen: false
};

function isStoreMgmActorAdmin() {
  return normalizeRole(localStorage.getItem('role') || '') === 'admin';
}

async function fetchStoreListForPage() {
  try {
    var data = await apiFetch('/api/stores');
    if (data && data.code === 200 && data.data && data.data.items) {
      window._storeMgm.stores = data.data.items || [];
      return window._storeMgm.stores;
    }
    return [];
  } catch (e) {
    showToast('加载失败', 'error');
    return [];
  }
}

async function fetchStoreEmployees(storeId) {
  try {
    var data = await apiFetch('/api/users');
    if (data && data.code === 200 && data.data && data.data.items) {
      var employees = data.data.items.filter(function(u) {
        return u.store_id === storeId;
      });
      return employees;
    }
    return [];
  } catch (e) {
    return [];
  }
}

