window.openStoreFormModal = openStoreFormModal;
window.closeStoreFormModal = closeStoreFormModal;
window.submitStoreForm = submitStoreForm;
window.openStoreDeleteModal = openStoreDeleteModal;
window.closeStoreDeleteModal = closeStoreDeleteModal;
window.confirmStoreDelete = confirmStoreDelete;
window.loadStoreListForPage = loadStoreListForPage;
window.refreshStoreList = refreshStoreList;
window.openStoreDetailModal = openStoreDetailModal;
window.closeStoreDetailModal = closeStoreDetailModal;

// ===================== Preference Settings Supporting Functions =====================

async function fetchAccountSettingsData() {
  try {
    var data = await apiFetch('/api/me');
    if (data && data.data) {
      var me = data.data;
      if (me.phone !== undefined) {
        localStorage.setItem('phone', me.phone || '');
        var phoneEl = document.getElementById('settings-phone');
        if (phoneEl) phoneEl.value = me.phone || '';
      }
      if (me.store_id !== undefined || me.store_name !== undefined) {
        var storeLabel = me.store_name || me.store_id || '—';
        if (me.store_id !== undefined) localStorage.setItem('store_id', me.store_id || '');
        localStorage.setItem('store_name', storeLabel);
        var storeEl = document.getElementById('settings-store-label');
        if (storeEl) storeEl.textContent = storeLabel;
        var storeSummaryEl = document.getElementById('settings-store-summary');
        if (storeSummaryEl) storeSummaryEl.textContent = storeLabel;
      }
    }
  } catch (e) {
    // Silently fail; form will use localStorage defaults
  }
}

function toggleInlinePasswordPanel() {
  var panel = document.getElementById('settings-pwd-panel');
  if (!panel) return;
  var trigger = document.getElementById('settings-pwd-row');
  var toggleText = document.getElementById('settings-pwd-toggle-text');
  var shouldOpen = panel.classList.contains('hidden');
  setAnimatedVisibility(panel, shouldOpen, { mode: 'collapse' });
  if (trigger) trigger.setAttribute('aria-expanded', shouldOpen ? 'true' : 'false');
  if (toggleText) toggleText.textContent = shouldOpen ? '收起' : '展开';
  if (shouldOpen) {
    var oldPwdEl = document.getElementById('settings-old-pwd');
    if (oldPwdEl) oldPwdEl.focus();
  }
}

async function submitInlineAccountSettings() {
  var btn = document.getElementById('settings-save-btn');
  if (btn) { btn.disabled = true; btn.textContent = '保存中...'; }
  try {
    var body = {
      display_name: (document.getElementById('settings-display-name') || {}).value || '',
      phone: (document.getElementById('settings-phone') || {}).value || '',
      password: (document.getElementById('settings-new-pwd') || {}).value || '',
      old_password: (document.getElementById('settings-old-pwd') || {}).value || '',
    };
    if (body.password && !body.old_password) {
      showToast('请填写旧密码', 'error');
      return;
    }
    await apiFetch('/api/me', {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    });
    var username = localStorage.getItem('username') || '';
    var nextDisplayName = body.display_name || localStorage.getItem('displayName') || username || '用户';
    localStorage.setItem('displayName', nextDisplayName);
    localStorage.setItem('phone', body.phone || '');
    syncProfileWidget();
    var heroNameEl = document.getElementById('settings-identity-name');
    if (heroNameEl) heroNameEl.textContent = nextDisplayName;
    var avatarEl = document.getElementById('settings-avatar');
    if (avatarEl) avatarEl.textContent = profileInitial(nextDisplayName, username);
    moduleState.growth.employee_name = nextDisplayName;
    refreshHomeHeroTitle();
    // Clear password fields after success
    var npEl = document.getElementById('settings-new-pwd');
    var opEl = document.getElementById('settings-old-pwd');
    if (npEl) npEl.value = '';
    if (opEl) opEl.value = '';
    // Collapse password panel
    var panel = document.getElementById('settings-pwd-panel');
    if (panel) {
      setAnimatedVisibility(panel, false, { mode: 'collapse' });
    }
    var pwdRow = document.getElementById('settings-pwd-row');
    if (pwdRow) pwdRow.setAttribute('aria-expanded', 'false');
    var toggleText = document.getElementById('settings-pwd-toggle-text');
    if (toggleText) toggleText.textContent = '展开';
    showToast('', 'ok');
  } catch (e) {
    showToast(e.message || '保存失败', 'error');
  } finally {
    if (btn) { btn.disabled = false; btn.textContent = '保存更改'; }
  }
}

function onSidebarToggleChange(checked) {
  localStorage.setItem('sidebar_collapsed_v1', checked ? '1' : '0');
  applySidebarCollapsedState(checked);
}

function onThemeToggleChange(checked) {
  setThemePreference(checked, true);
}

function onNotifToggleChange(checked) {
  localStorage.setItem('notif_enabled_v1', checked ? '1' : '0');
}

function syncSettingsSlideRowState(row, checked) {
  if (!row) return;
  row.setAttribute('aria-pressed', checked ? 'true' : 'false');
  row.setAttribute('data-state', checked ? 'on' : 'off');
  var track = row.querySelector('.settings-slide-track');
  if (track) track.classList.toggle('settings-slide-track--on', !!checked);
  var stateEl = row.querySelector('.settings-pref-state');
  if (stateEl) {
    var onLabel = row.getAttribute('data-state-on') || '已开启';
    var offLabel = row.getAttribute('data-state-off') || '已关闭';
    stateEl.textContent = checked ? onLabel : offLabel;
  }
}

function setSettingsSlideRowDisabled(row, disabled) {
  if (!row) return;
  var isDisabled = !!disabled;
  row.classList.toggle('settings-slide-row--disabled', isDisabled);
  row.setAttribute('aria-disabled', isDisabled ? 'true' : 'false');
  if (isDisabled) row.tabIndex = -1;
  else row.removeAttribute('tabindex');
}

function syncDigitalHumanSettingsRows() {
  var prefs = getDigitalHumanPreferences();
  var systemEnabled = isDigitalHumanSystemEnabled();
  var muteRow = document.getElementById('settings-dh-voice-muted');
  var totalRow = document.getElementById('settings-dh-auto-voice');
  var practiceRow = document.getElementById('settings-dh-practice-voice');
  var practiceTurnRow = document.getElementById('settings-dh-practice-turn-feedback-voice');
  var assistantRow = document.getElementById('settings-dh-assistant-voice');
  var qaRow = document.getElementById('settings-dh-knowledge-voice');
  var mouseFollowRow = document.getElementById('settings-dh-mouse-follow');
  var dragRotateRow = document.getElementById('settings-dh-drag-rotate');
  var idleHintRow = document.getElementById('settings-dh-idle-hint');
  var emotionBubbleRow = document.getElementById('settings-dh-emotion-bubble');
  var microExpressionRow = document.getElementById('settings-dh-micro-expression');
  var pageGreetingRow = document.getElementById('settings-dh-page-greeting');
  var noteEl = document.getElementById('settings-dh-system-note');
  syncSettingsSlideRowState(muteRow, !!prefs.voice_muted);
  syncSettingsSlideRowState(totalRow, !!prefs.auto_voice_enabled);
  syncSettingsSlideRowState(practiceRow, !!prefs.scenes.practice_score);
  syncSettingsSlideRowState(practiceTurnRow, !!prefs.scenes.practice_turn_feedback);
  syncSettingsSlideRowState(assistantRow, !!prefs.scenes.assistant);
  syncSettingsSlideRowState(qaRow, !!prefs.scenes.knowledge_qa);
  syncSettingsSlideRowState(mouseFollowRow, !!prefs.mouse_follow);
  syncSettingsSlideRowState(dragRotateRow, !!prefs.drag_rotate);
  syncSettingsSlideRowState(idleHintRow, !!prefs.idle_hint);
  syncSettingsSlideRowState(emotionBubbleRow, !!prefs.emotion_bubble);
  syncSettingsSlideRowState(microExpressionRow, !!prefs.micro_expression);
  syncSettingsSlideRowState(pageGreetingRow, !!prefs.page_greeting);
  if (noteEl) {
    noteEl.hidden = systemEnabled;
    noteEl.textContent = systemEnabled ? '' : '系统管理员已关闭数字人，当前个人语音偏好已暂时停用。';
  }
  setSettingsSlideRowDisabled(muteRow, !systemEnabled);
  setSettingsSlideRowDisabled(totalRow, !systemEnabled);
  var disableScenes = !systemEnabled || !prefs.auto_voice_enabled;
  setSettingsSlideRowDisabled(practiceRow, disableScenes);
  setSettingsSlideRowDisabled(practiceTurnRow, disableScenes);
  setSettingsSlideRowDisabled(assistantRow, disableScenes);
  setSettingsSlideRowDisabled(qaRow, disableScenes);
  setSettingsSlideRowDisabled(mouseFollowRow, !systemEnabled);
  setSettingsSlideRowDisabled(dragRotateRow, !systemEnabled);
  setSettingsSlideRowDisabled(idleHintRow, !systemEnabled);
  setSettingsSlideRowDisabled(emotionBubbleRow, !systemEnabled);
  setSettingsSlideRowDisabled(microExpressionRow, !systemEnabled);
  setSettingsSlideRowDisabled(pageGreetingRow, !systemEnabled);
  var isMinimax = getDigitalHumanTtsProvider() === 'minimax';
  var voiceGrid = document.getElementById('settings-voice-grid');
  var voiceNote = document.getElementById('settings-voice-provider-note');
  var voiceCurrent = document.getElementById('settings-voice-current');
  if (voiceGrid) {
    voiceGrid.style.display = isMinimax ? '' : 'none';
    var tags = voiceGrid.querySelectorAll('.settings-voice-tag');
    var activeId = prefs.minimax_voice_id || 'female-tianmei';
    for (var i = 0; i < tags.length; i++) {
      var tag = tags[i];
      var isSelected = tag.getAttribute('data-voice-id') === activeId;
      tag.classList.toggle('settings-voice-tag--active', isSelected);
      tag.setAttribute('aria-pressed', isSelected ? 'true' : 'false');
    }
  }
  if (voiceNote) {
    if (!isMinimax) {
      voiceNote.hidden = false;
      voiceNote.textContent = '当前使用浏览器原生 TTS，音色设置不可用。';
    } else {
      voiceNote.hidden = true;
    }
  }
  if (voiceCurrent) {
    var currentVoice = MINIMAX_VOICE_OPTIONS.find(function (v) { return v.id === (prefs.minimax_voice_id || 'female-tianmei'); });
    voiceCurrent.textContent = currentVoice ? currentVoice.label : '';
  }
}

function onDigitalHumanVoiceMuteChange(checked) {
  setDigitalHumanPreferences({ voice_muted: checked });
  syncDigitalHumanSettingsRows();
}

function onDigitalHumanAutoVoiceChange(checked) {
  setDigitalHumanPreferences({ auto_voice_enabled: checked });
  syncDigitalHumanSettingsRows();
}

function onDigitalHumanSceneVoiceChange(scene, checked) {
  var patch = { scenes: {} };
  patch.scenes[String(scene || '').trim()] = checked;
  setDigitalHumanPreferences(patch);
  syncDigitalHumanSettingsRows();
}

function onDigitalHumanInteractionPreferenceChange(key, checked) {
  var prefKey = String(key || '').trim();
  if (!prefKey) return;
  var patch = {};
  patch[prefKey] = checked;
  setDigitalHumanPreferences(patch);
  syncDigitalHumanSettingsRows();
  syncDhmSettingsUI();
}

function selectMinimaxVoice(voiceId) {
  var id = String(voiceId || '').trim();
  if (!id) return;
  setDigitalHumanPreferences({ minimax_voice_id: id });
  syncDigitalHumanSettingsRows();
}

function getDigitalHumanMinimaxVoice() {
  return getDigitalHumanPreferences().minimax_voice_id || '';
}

// ===================== Slide Toggle Handler =====================

function settingsSlideToggle(row, type) {
  if (!row || row.getAttribute('aria-disabled') === 'true') return;
  var track = row.querySelector('.settings-slide-track');
  if (!track) return;
  var isOn = track.classList.toggle('settings-slide-track--on');
  row.setAttribute('aria-pressed', isOn ? 'true' : 'false');
  row.setAttribute('data-state', isOn ? 'on' : 'off');
  var stateEl = row.querySelector('.settings-pref-state');
  if (stateEl) {
    var onLabel = row.getAttribute('data-state-on') || '已开启';
    var offLabel = row.getAttribute('data-state-off') || '已关闭';
    stateEl.textContent = isOn ? onLabel : offLabel;
  }

  switch (type) {
    case 'sidebar':
      onSidebarToggleChange(isOn);
      break;
    case 'theme':
      onThemeToggleChange(isOn);
      break;
    case 'notif':
      onNotifToggleChange(isOn);
      break;
    case 'dh-voice-muted':
      onDigitalHumanVoiceMuteChange(isOn);
      break;
    case 'dh-auto-voice':
      onDigitalHumanAutoVoiceChange(isOn);
      break;
    case 'dh-practice-voice':
      onDigitalHumanSceneVoiceChange('practice_score', isOn);
      break;
    case 'dh-practice-turn-feedback-voice':
      onDigitalHumanSceneVoiceChange('practice_turn_feedback', isOn);
      break;
    case 'dh-assistant-voice':
      onDigitalHumanSceneVoiceChange('assistant', isOn);
      break;
    case 'dh-knowledge-voice':
      onDigitalHumanSceneVoiceChange('knowledge_qa', isOn);
      break;
    case 'dh-mouse-follow':
      onDigitalHumanInteractionPreferenceChange('mouse_follow', isOn);
      break;
    case 'dh-drag-rotate':
      onDigitalHumanInteractionPreferenceChange('drag_rotate', isOn);
      break;
    case 'dh-idle-hint':
      onDigitalHumanInteractionPreferenceChange('idle_hint', isOn);
      break;
    case 'dh-emotion-bubble':
      onDigitalHumanInteractionPreferenceChange('emotion_bubble', isOn);
      break;
    case 'dh-micro-expression':
      onDigitalHumanInteractionPreferenceChange('micro_expression', isOn);
      break;
    case 'dh-page-greeting':
      onDigitalHumanInteractionPreferenceChange('page_greeting', isOn);
      break;
    case 'dhm-system-enabled':
      dhmToggleSystemEnabled();
      break;
    case 'dhm-voice-muted':
      onDigitalHumanVoiceMuteChange(isOn);
      syncDhmSettingsUI();
      break;
    case 'dhm-auto-voice':
      onDigitalHumanAutoVoiceChange(isOn);
      syncDhmSettingsUI();
      break;
    case 'dhm-practice-score':
      onDigitalHumanSceneVoiceChange('practice_score', isOn);
      syncDhmSettingsUI();
      break;
    case 'dhm-practice-feedback':
      onDigitalHumanSceneVoiceChange('practice_turn_feedback', isOn);
      syncDhmSettingsUI();
      break;
    case 'dhm-assistant':
      onDigitalHumanSceneVoiceChange('assistant', isOn);
      syncDhmSettingsUI();
      break;
    case 'dhm-knowledge':
      onDigitalHumanSceneVoiceChange('knowledge_qa', isOn);
      syncDhmSettingsUI();
      break;
    case 'dhm-mouse-follow':
      onDigitalHumanInteractionPreferenceChange('mouse_follow', isOn);
      break;
    case 'dhm-drag-rotate':
      onDigitalHumanInteractionPreferenceChange('drag_rotate', isOn);
      break;
    case 'dhm-idle-hint':
      onDigitalHumanInteractionPreferenceChange('idle_hint', isOn);
      break;
    case 'dhm-emotion-bubble':
      onDigitalHumanInteractionPreferenceChange('emotion_bubble', isOn);
      break;
    case 'dhm-micro-expression':
      onDigitalHumanInteractionPreferenceChange('micro_expression', isOn);
      break;
    case 'dhm-page-greeting':
      onDigitalHumanInteractionPreferenceChange('page_greeting', isOn);
      break;
  }
}

function renderSettingsToggleRow(id, label, desc, checked, type, onLabel, offLabel) {
  var descMarkup = desc
    ? '<span class="settings-slide-desc">' + escapeHtml(desc) + '</span>'
    : '';
  return (
    '<button type="button" class="settings-slide-row" id="' + escapeHtml(id) + '"' +
      ' aria-pressed="' + (checked ? 'true' : 'false') + '"' +
      ' data-state="' + (checked ? 'on' : 'off') + '"' +
      ' data-state-on="' + escapeHtml(onLabel) + '"' +
      ' data-state-off="' + escapeHtml(offLabel) + '"' +
      ' onclick="settingsSlideToggle(this, \'' + escapeHtml(type) + '\')"' +
      '>' +
      '<span class="settings-slide-content">' +
        '<span class="settings-slide-label">' + escapeHtml(label) + '</span>' +
        descMarkup +
      '</span>' +
      '<span class="settings-slide-meta">' +
        '<span class="settings-pref-state">' + escapeHtml(checked ? onLabel : offLabel) + '</span>' +
        '<span class="settings-slide-track' + (checked ? ' settings-slide-track--on' : '') + '" aria-hidden="true">' +
          '<span class="settings-slide-thumb"></span>' +
        '</span>' +
      '</span>' +
    '</button>'
  );
}

async function saveDigitalHumanSystemSettings() {
  var btn = document.getElementById('system-settings-save-btn');
  if (btn) {
    btn.disabled = true;
    btn.textContent = '保存中...';
  }
  setDigitalHumanSystemSettingsState({ saving: true, error: '' });
  try {
    var draft = getDigitalHumanSystemSettingsDraft();
    var res = await apiFetch('/api/system-settings/digital-human', {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(draft),
    });
    var next = normalizeDigitalHumanSystemSettings(Object.assign({}, res && res.data ? res.data : {}, {
      loaded: true,
      loading: false,
      saving: false,
      error: '',
    }));
    moduleState.systemSettings.digitalHuman = next;
    syncDigitalHumanSystemSettingsDraft();
    if (!next.enabled && typeof destroyDigitalHuman === 'function') destroyDigitalHuman();
    showToast('系统设置已保存', 'ok');
    rerenderCurrentPage();
  } catch (e) {
    setDigitalHumanSystemSettingsState({ saving: false, error: String(e && e.message || '').trim() });
    showToast(e && e.message ? e.message : '保存失败', 'error');
  } finally {
    if (btn) {
      btn.disabled = false;
      btn.textContent = '保存设置';
    }
  }
}

