function dhmToggleSystemEnabled() {
  var draft = getDigitalHumanSystemSettingsDraft();
  setDigitalHumanSystemSettingsDraft({ enabled: !draft.enabled });
  var row = document.getElementById('system-dh-enabled');
  syncSettingsSlideRowState(row, !draft.enabled);
  syncDhmSettingsUI();
}

function dhmSelectProvider(provider) {
  setDigitalHumanSystemSettingsDraft({ tts_provider: provider });
  // Update button states
  ['minimax', 'browser'].forEach(function (p) {
    var btn = document.getElementById('system-dh-provider-' + p);
    if (!btn) return;
    var isSelected = p === provider;
    btn.setAttribute('aria-pressed', isSelected ? 'true' : 'false');
    btn.setAttribute('data-selected', isSelected ? 'true' : 'false');
    btn.classList.toggle('settings-provider-card--selected', isSelected);
  });
}

function syncDhmSettingsUI() {
  var draft = getDigitalHumanSystemSettingsDraft();
  var prefs = getDigitalHumanPreferences();
  var providerGroup = document.getElementById('system-dh-provider-group');
  if (providerGroup) providerGroup.setAttribute('aria-disabled', !draft.enabled ? 'true' : 'false');
  ['minimax', 'browser'].forEach(function (p) {
    var btn = document.getElementById('system-dh-provider-' + p);
    if (btn) btn.disabled = !draft.enabled;
  });
  var noteEl = document.getElementById('system-dh-prefs-note');
  if (noteEl) {
    noteEl.hidden = draft.enabled;
    noteEl.textContent = draft.enabled ? '' : '数字人已关闭，以下偏好暂不生效。';
  }
  var disableVoicePrefs = !draft.enabled;
  var rows = [
    { id: 'system-dh-voice-muted', disabled: disableVoicePrefs, checked: !!prefs.voice_muted },
    { id: 'system-dh-auto-voice', disabled: disableVoicePrefs },
    { id: 'system-dh-practice-score', disabled: disableVoicePrefs || !prefs.auto_voice_enabled },
    { id: 'system-dh-practice-feedback', disabled: disableVoicePrefs || !prefs.auto_voice_enabled },
    { id: 'system-dh-assistant', disabled: disableVoicePrefs || !prefs.auto_voice_enabled },
    { id: 'system-dh-knowledge', disabled: disableVoicePrefs || !prefs.auto_voice_enabled },
    { id: 'system-dh-mouse-follow', disabled: !draft.enabled, checked: !!prefs.mouse_follow },
    { id: 'system-dh-drag-rotate', disabled: !draft.enabled, checked: !!prefs.drag_rotate },
    { id: 'system-dh-idle-hint', disabled: !draft.enabled, checked: !!prefs.idle_hint },
    { id: 'system-dh-emotion-bubble', disabled: !draft.enabled, checked: !!prefs.emotion_bubble },
    { id: 'system-dh-micro-expression', disabled: !draft.enabled, checked: !!prefs.micro_expression },
    { id: 'system-dh-page-greeting', disabled: !draft.enabled, checked: !!prefs.page_greeting },
  ];
  rows.forEach(function (r) {
    var row = document.getElementById(r.id);
    if (row && r.checked !== undefined) syncSettingsSlideRowState(row, r.checked);
    setSettingsSlideRowDisabled(row, r.disabled);
  });
}

async function saveDigitalHumanMergedSettings() {
  var btn = document.getElementById('system-settings-save-btn');
  if (btn) btn.disabled = true;
  try {
    await saveDigitalHumanSystemSettings();
  } catch (e) {}
  if (btn) btn.disabled = false;
}

