function doStartTraining(userId, btnEl, employeeName) {
  var rs = 'trainingStart';
  if (requestLoading(rs)) return;

  var radios = document.querySelectorAll('input[name="start-release-mode"]');
  var releaseAll = false;
  for (var i = 0; i < radios.length; i++) {
    if (radios[i].checked && radios[i].value === 'all') { releaseAll = true; break; }
  }

  setRequestLoading(rs, true);
  btnEl.disabled = true;
  btnEl.textContent = '创建中...';

  apiFetch('/api/training-cycle/start-stage', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      user_id: userId,
      stage_no: 1,
      cycle_type: 'onboarding',
      release_all: releaseAll,
    }),
  })
    .then(function (d) {
      var result = d && d.data ? d.data : {};
      var plan = result.growth_plan || {};
      var msg = plan && plan.source_workflow === 'training_manage_seed'
        ? ('已为 ' + employeeName + ' 创建阶段 1 训练，并自动补齐成长计划')
        : ('已为 ' + employeeName + ' 基于成长计划创建阶段 1 训练');
      showToast(msg, 'success');
      var modal = btnEl.closest('.ios-modal');
      if (modal) iosCloseModal(modal);
      closeTrainingDetailModal();
      moduleState.trainingManage.loaded = false;
      rerenderCurrentPage();
    })
    .catch(function (e) {
      showToast('发起培训失败：' + (e.message || e), 'error');
      btnEl.disabled = false;
      btnEl.textContent = '确认发起';
    })
    .finally(function () {
      setRequestLoading(rs, false);
    });
}

function trainingChoiceCardStyle(selected, accentColor, accentBg, textColor) {
  if (selected) {
    return 'border-color:' + accentColor + ';background:' + accentBg + ';color:' + textColor + ';box-shadow:0 0 0 1px ' + accentColor;
  }
  return 'border-color:#e5e7eb;background:#fff;color:#374151;box-shadow:none';
}

function syncTrainingChoiceStyles(inputEl, groupSelector, accentColor, accentBg, textColor) {
  var group = inputEl && inputEl.closest ? inputEl.closest(groupSelector) : null;
  if (!group) return;
  var radios = group.querySelectorAll('input[type=radio]');
  for (var i = 0; i < radios.length; i++) {
    var radio = radios[i];
    var card = radio.parentElement ? radio.parentElement.querySelector('[data-training-choice-card]') : null;
    if (!card) continue;
    card.className = 'rounded-lg border-2 p-3 text-center transition';
    card.setAttribute('style', trainingChoiceCardStyle(radio.checked, accentColor, accentBg, textColor));
  }
}

