function cancelStoreForm() {
  var form = document.getElementById('form-store-edit');
  if (form) form.classList.add('hidden');
}

async function createUser(ev) {
  if (ev) ev.preventDefault();
  try {
    var body = {
      username: (document.getElementById('new-username') || {}).value || '',
      password: (document.getElementById('new-password') || {}).value || '',
      display_name: (document.getElementById('new-employee-name') || {}).value || '',
      role: normalizeRole((document.getElementById('new-role') || {}).value || 'trainee'),
      store_id: (document.getElementById('new-store') || {}).value || '',
      phone: (document.getElementById('new-phone') || {}).value || '',
      mentor_name: (document.getElementById('new-mentor-name') || {}).value || '',
    };
    await apiFetch('/api/users', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    });
    invalidatePersonnelStoreCaches();
    showToast('已创建', 'ok');
    closeModal();
    // Refresh the user list
    apiFetch('/api/users')
      .then(function (j) {
        if (j && Number(j.code) === 200) {
          var items = j.data && j.data.items || [];
          cachePersonnelUsers(items);
          buildPersonnelFilterOptions(items);
          renderPersonnelTable(items);
        }
      })
      .catch(function () {});
  } catch (e) {
    var err = document.getElementById('new-user-form-error');
    if (err) {
      err.textContent = e.message || '创建失败';
      err.classList.remove('hidden');
    } else {
      showToast(e.message || '创建失败', 'error');
    }
  }
}

function openEditUserModal(index) {
  var users = window._personnelUsers || [];
  var u = users[index];
  if (!u) return;
  var actorRole = normalizeRole(localStorage.getItem('role') || '');
  var isAdmin = actorRole === 'admin';

  document.getElementById('edit-user-id').value = u.id || '';
  document.getElementById('edit-username').value = u.username || '';
  document.getElementById('edit-password').value = '';
  document.getElementById('edit-password').placeholder = '选填';
  document.getElementById('edit-displayname').value = u.display_name || u.username || '';
  var empNoEl = document.getElementById('edit-emp-no');
  if (empNoEl) empNoEl.textContent = u.employee_no || u.id || '—';

  // Store: only admin can edit
  var storeWrap = document.getElementById('edit-store-trigger');
  var storeLabel = document.getElementById('edit-store-field-label');
  if (storeWrap) {
    if (isAdmin) {
      storeWrap.classList.remove('pointer-events-none', 'opacity-50', 'cursor-not-allowed');
      storeWrap.disabled = false;
    } else {
      storeWrap.classList.add('pointer-events-none', 'opacity-50', 'cursor-not-allowed');
      storeWrap.disabled = true;
    }
  }
  if (storeLabel) {
    storeLabel.innerHTML = isAdmin
      ? '归属门店 <span class="text-red-500" aria-hidden="true">*</span>'
      : '归属门店 <span class="ml-1 text-xs text-gray-400">(仅管理员可修改)</span>';
  }
  document.getElementById('edit-store').value = u.store_id || '';
  document.getElementById('edit-store-text').textContent = u.store_label || u.store_id || '—';

  // Role: only admin can edit
  var roleWrap = document.getElementById('edit-role-trigger');
  var roleLabel = document.getElementById('edit-role-label');
  if (roleWrap) {
    if (isAdmin) {
      roleWrap.classList.remove('pointer-events-none', 'opacity-50', 'cursor-not-allowed');
      roleWrap.disabled = false;
    } else {
      roleWrap.classList.add('pointer-events-none', 'opacity-50', 'cursor-not-allowed');
      roleWrap.disabled = true;
    }
  }
  if (roleLabel) {
    roleLabel.innerHTML = isAdmin
      ? '员工角色 <span class="text-red-500" aria-hidden="true">*</span>'
      : '员工角色 <span class="ml-1 text-xs text-gray-400">(仅管理员可修改)</span>';
  }
  document.getElementById('edit-role').value = u.role || 'trainee';
  document.getElementById('edit-role-text').textContent = ROLE_LABELS[u.role] || u.role || '导购';

  // Phone
  document.getElementById('edit-phone').value = u.phone || '';
  document.getElementById('edit-mentor-name').value = u.mentor_name || '';

  var errEl = document.getElementById('edit-user-form-error');
  if (errEl) { errEl.classList.add('hidden'); errEl.textContent = ''; }
  openModal('modal-edit-user');
}

function clearEditUserFormError() {
  var err = document.getElementById('edit-user-form-error');
  if (err) { err.classList.add('hidden'); err.textContent = ''; }
}

async function submitEditUser(ev) {
  if (ev) ev.preventDefault();
  var userId = (document.getElementById('edit-user-id') || {}).value || '';
  if (!userId) return;
  var actorRole = normalizeRole(localStorage.getItem('role') || '');
  var isAdmin = actorRole === 'admin';
  var body = {};
  var dn = (document.getElementById('edit-displayname') || {}).value || '';
  if (!dn.trim()) {
    var err = document.getElementById('edit-user-form-error');
    if (err) { err.textContent = '员工姓名不能为空'; err.classList.remove('hidden'); }
    return;
  }
  body.display_name = dn;
  var pwd = (document.getElementById('edit-password') || {}).value || '';
  if (pwd) body.password = pwd;
  var phoneVal = (document.getElementById('edit-phone') || {}).value || '';
  body.phone = phoneVal;
  body.mentor_name = (document.getElementById('edit-mentor-name') || {}).value || '';
  // Role and store_id: only admin can modify
  if (isAdmin) {
    var roleVal = (document.getElementById('edit-role') || {}).value || '';
    if (roleVal) body.role = roleVal;
    var storeVal = (document.getElementById('edit-store') || {}).value || '';
    if (storeVal) body.store_id = storeVal;
  }
  try {
    await apiFetch('/api/users/' + encodeURIComponent(userId), {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    });
    invalidatePersonnelStoreCaches();
    showToast('已更新', 'ok');
    closeEditModal();
    // Refresh the table
    apiFetch('/api/users')
      .then(function (j) {
        if (j && Number(j.code) === 200) {
          var items = j.data && j.data.items || [];
          cachePersonnelUsers(items);
          buildPersonnelFilterOptions(items);
          renderPersonnelTable(items);
        }
      })
      .catch(function () {});
  } catch (e) {
    var err2 = document.getElementById('edit-user-form-error');
    if (err2) { err2.textContent = e.message || '更新失败'; err2.classList.remove('hidden'); }
    else showToast(e.message || '更新失败', 'error');
  }
}

function ensurePersonnelDeleteModal() {
  if (document.getElementById('personnel-delete-modal')) return;
  var modal = document.createElement('div');
  modal.id = 'personnel-delete-modal';
  modal.className = 'fixed inset-0 z-[210] hidden flex items-center justify-center bg-black/20 backdrop-blur-sm p-4';
  modal.setAttribute('onclick', 'if(event.target===this)closePersonnelDeleteModal()');
  modal.innerHTML =
    '<div class="relative w-full max-w-sm bg-white rounded-2xl shadow-xl overflow-hidden" onclick="event.stopPropagation()">' +
    '<div class="p-6 text-center">' +
    '<div class="mx-auto w-12 h-12 rounded-full bg-red-100 flex items-center justify-center mb-4">' +
    '<svg class="w-6 h-6 text-red-600" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>' +
    '</div>' +
    '<h3 class="text-lg font-semibold text-gray-800 mb-2">删除员工</h3>' +
    '<p id="personnel-delete-msg" class="text-sm text-gray-500 mb-6"></p>' +
    '<div class="flex gap-3">' +
    '<button type="button" onclick="closePersonnelDeleteModal()" class="flex-1 px-5 py-2.5 rounded-xl text-sm font-medium text-gray-600 bg-gray-100 transition-all duration-200 hover:bg-gray-200 active:scale-[0.98]">取消</button>' +
    '<button type="button" id="personnel-delete-confirm-btn" class="flex-1 px-5 py-2.5 rounded-xl text-sm font-semibold text-white bg-red-600 transition-all duration-200 hover:brightness-105 active:scale-[0.98]">确认删除</button>' +
    '</div>' +
    '</div>' +
    '</div>';
  document.body.appendChild(modal);
}

function closePersonnelDeleteModal() {
  var modal = document.getElementById('personnel-delete-modal');
  if (modal) modal.classList.add('hidden');
}

function showPersonnelDeleteModal(userId, label) {
  ensurePersonnelDeleteModal();
  var modal = document.getElementById('personnel-delete-modal');
  var msgEl = document.getElementById('personnel-delete-msg');
  var confirmBtn = document.getElementById('personnel-delete-confirm-btn');
  if (msgEl) msgEl.textContent = '确定删除「' + label + '」？此操作不可撤销';
  if (confirmBtn) {
    confirmBtn.onclick = function () {
      closePersonnelDeleteModal();
      doDeletePersonnelUser(userId);
    };
  }
  modal.classList.remove('hidden');
}

async function deletePersonnelUserById(userId) {
  var uid = String(userId || '').trim();
  if (!uid) {
    showToast('未选中员工', 'error');
    return;
  }
  var actorId = localStorage.getItem('userId') || '';
  if (actorId && actorId === uid) {
    showToast('不可操作', 'error');
    return;
  }
  var users = window._personnelUsers || [];
  var label = '';
  for (var i = 0; i < users.length; i++) {
    if (String(users[i].id) === uid) {
      label = users[i].display_name || users[i].username || '';
      break;
    }
  }
  showPersonnelDeleteModal(uid, label || uid);
}

async function doDeletePersonnelUser(uid) {
  var enc = encodeURIComponent(uid);
  var jsonHeaders = { 'Content-Type': 'application/json' };
  function isRouteOrMethodIssue(msg) {
    var m = String(msg || '');
    return (
      /not found/i.test(m) ||
      /^404\b/.test(m.trim()) ||
      /method not allowed/i.test(m) ||
      /\b405\b/.test(m)
    );
  }
  try {
    try {
      await apiFetch('/api/user-delete', {
        method: 'POST',
        headers: jsonHeaders,
        body: JSON.stringify({ user_id: uid }),
      });
    } catch (e0) {
      var m0 = (e0 && e0.message) ? String(e0.message) : '';
      if (!isRouteOrMethodIssue(m0)) throw e0;
      try {
        await apiFetch('/api/users/' + enc + '/delete', {
          method: 'POST',
          headers: jsonHeaders,
          body: '{}',
        });
      } catch (e1) {
        var m1 = (e1 && e1.message) ? String(e1.message) : '';
        if (!isRouteOrMethodIssue(m1)) throw e1;
        await apiFetch('/api/users/' + enc, { method: 'DELETE' });
      }
    }
    invalidatePersonnelStoreCaches();
    showToast('已删除', 'ok');
    apiFetch('/api/users')
      .then(function (j) {
        if (j && Number(j.code) === 200) {
          var items = j.data && j.data.items || [];
          cachePersonnelUsers(items);
          buildPersonnelFilterOptions(items);
          renderPersonnelTable(items);
        }
      })
      .catch(function () {});
  } catch (e) {
    showToast(e.message || '删除失败', 'error');
  }
}

// ─── 门店/角色下拉 ───────────────────────────────────────────
// 编辑员工弹窗：归属门店 / 员工角色 面板开闭过渡（内联样式，避免 Tailwind CDN 未扫描 app.js 内类名）

var _EDIT_DD_MS = 200;

function _editListboxTriggerId(listboxId) {
  if (listboxId === 'edit-store-listbox') return 'edit-store-trigger';
  if (listboxId === 'edit-role-listbox') return 'edit-role-trigger';
  if (listboxId === 'edit-mentor-listbox') return 'edit-mentor-trigger';
  return null;
}

function _setEditDropdownTriggerOpen(triggerId, open) {
  if (!triggerId) return;
  var tr = document.getElementById(triggerId);
  if (!tr) return;
  tr.setAttribute('aria-expanded', open ? 'true' : 'false');
  tr.setAttribute('data-state', open ? 'open' : 'closed');
  var chev = tr.querySelector('svg');
  if (chev) {
    chev.style.transition = 'transform ' + _EDIT_DD_MS + 'ms ease-out';
    chev.style.transform = open ? 'rotate(180deg)' : '';
  }
}

function personnelEditDropdownForceReset(lb) {
  if (!lb) return;
  try {
    clearTimeout(lb._editDdT);
  } catch (e) {}
  lb._editDdT = null;
  if (lb.id !== 'edit-store-listbox' && lb.id !== 'edit-role-listbox' && lb.id !== 'edit-mentor-listbox') return;
  _setEditDropdownTriggerOpen(_editListboxTriggerId(lb.id), false);
  lb.classList.add('hidden');
  lb.style.cssText = '';
}

function personnelEditDropdownClose(lb) {
  if (!lb) return;
  if (lb.id !== 'edit-store-listbox' && lb.id !== 'edit-role-listbox' && lb.id !== 'edit-mentor-listbox') {
    lb.classList.add('hidden');
    return;
  }
  var tid = _editListboxTriggerId(lb.id);
  _setEditDropdownTriggerOpen(tid, false);
  try {
    clearTimeout(lb._editDdT);
  } catch (e) {}
  if (lb.classList.contains('hidden')) return;
  lb.style.transition = 'opacity ' + _EDIT_DD_MS + 'ms ease-out, transform ' + _EDIT_DD_MS + 'ms ease-out';
  lb.style.opacity = '0';
  lb.style.transform = 'scale(0.98) translateY(-4px)';
  lb.style.pointerEvents = 'none';
  lb._editDdT = setTimeout(function () {
    lb.classList.add('hidden');
    lb.style.opacity = '';
    lb.style.transform = '';
    lb.style.transition = '';
    lb.style.pointerEvents = '';
    lb._editDdT = null;
  }, _EDIT_DD_MS + 20);
}

function personnelEditDropdownOpen(lb, triggerId) {
  if (!lb) return;
  if (lb.id !== 'edit-store-listbox' && lb.id !== 'edit-role-listbox' && lb.id !== 'edit-mentor-listbox') {
    lb.classList.remove('hidden');
    return;
  }
  try {
    clearTimeout(lb._editDdT);
  } catch (e) {}
  lb._editDdT = null;
  var tid = triggerId || _editListboxTriggerId(lb.id);
  lb.style.position = 'absolute';
  lb.style.left = '0';
  lb.style.right = '0';
  lb.style.top = '100%';
  lb.style.marginTop = '0.375rem';
  lb.style.transformOrigin = '50% 0';
  lb.style.zIndex = '50';
  lb.style.maxHeight = '14rem';
  lb.style.overflowY = 'auto';
  lb.style.transition = 'opacity ' + _EDIT_DD_MS + 'ms ease-out, transform ' + _EDIT_DD_MS + 'ms ease-out';
  lb.classList.remove('hidden');
  lb.style.opacity = '0';
  lb.style.transform = 'scale(0.98) translateY(-4px)';
  lb.style.pointerEvents = 'none';
  _setEditDropdownTriggerOpen(tid, true);
  requestAnimationFrame(function () {
    requestAnimationFrame(function () {
      lb.style.opacity = '1';
      lb.style.transform = 'scale(1) translateY(0)';
      lb.style.pointerEvents = '';
    });
  });
}

function _closeOtherPersonnelDropdownsExcept(keepLb) {
  var allLbs = document.querySelectorAll('[id$="-store-listbox"], [id$="-role-listbox"], [id$="-mentor-listbox"]');
  for (var i = 0; i < allLbs.length; i++) {
    var lb = allLbs[i];
    if (lb === keepLb) continue;
    if (lb.id === 'edit-store-listbox' || lb.id === 'edit-role-listbox' || lb.id === 'edit-mentor-listbox') {
      personnelEditDropdownClose(lb);
    } else if (!lb.classList.contains('hidden')) {
      iosDropdownClose(lb);
    }
  }
}

var _userStoreCache = null;
var _userRoleCache = null;

function _buildListboxItem(text, value, selected) {
  return (
    '<button type="button" class="w-full px-4 py-2.5 text-left text-sm text-gray-700 hover:bg-blue-50 transition-colors ' +
    (selected ? 'bg-blue-50 text-blue-600 font-medium' : '') +
    '" data-value="' +
    escapeHtml(value) +
    '" data-label="' +
    escapeHtml(text) +
    '">' +
    escapeHtml(text) +
    '</button>'
  );
}

function ensureUserStoresLoaded() {
  if (_userStoreCache) return Promise.resolve();
  return apiFetch('/api/stores').then(function (j) {
    if (j && Number(j.code) === 200) {
      _userStoreCache = (j.data && j.data.items) || [];
    } else {
      _userStoreCache = [];
    }
  });
}

function ensureUserRolesLoaded() {
  if (_userRoleCache) return Promise.resolve();
  return apiFetch('/api/role-settings?for_assign=0').then(function (j) {
    if (j && Number(j.code) === 200) {
      _userRoleCache = (j.data && j.data.items) || [];
    } else {
      _userRoleCache = [];
    }
  });
}

function buildUserStoreListbox(suffix) {
  var lb = document.getElementById('new-store-listbox');
  if (!lb || suffix === 'edit') lb = document.getElementById('edit-store-listbox');
  if (!lb) return;
  var currentVal = (document.getElementById('new-store') || {}).value || '';
  if (suffix === 'edit') currentVal = (document.getElementById('edit-store') || {}).value || '';
  if (!_userStoreCache || !_userStoreCache.length) {
    lb.innerHTML = renderEmptyState('门店');
    return;
  }
  var html = '';
  for (var i = 0; i < _userStoreCache.length; i++) {
    var s = _userStoreCache[i];
    var sid = String(s.store_id || '').trim();
    var slab = String(s.store_name || s.label || sid || '').trim();
    html += _buildListboxItem(slab, sid, sid === currentVal);
  }
  lb.innerHTML = html;
}

function buildUserRoleListbox(suffix) {
  var lb = document.getElementById('new-role-listbox');
  if (!lb || suffix === 'edit') lb = document.getElementById('edit-role-listbox');
  if (!lb) return;
  var currentVal = (document.getElementById('new-role') || {}).value || 'trainee';
  if (suffix === 'edit') currentVal = (document.getElementById('edit-role') || {}).value || '';
  if (!_userRoleCache || !_userRoleCache.length) {
    lb.innerHTML = renderEmptyState('角色');
    return;
  }
  var html = '';
  for (var i = 0; i < _userRoleCache.length; i++) {
    var r = _userRoleCache[i];
    var rk = String(r.role_key || '').trim();
    var rlab = String(r.display_name || rk || '').trim();
    html += _buildListboxItem(rlab, rk, rk === currentVal);
  }
  lb.innerHTML = html;
}

function buildUserMentorListbox(suffix) {
  var controls = getPersonnelMentorControls(suffix);
  var selectEl = controls.selectEl;
  var lb = controls.listboxEl;
  if (!selectEl || !lb) return;
  if (selectEl.disabled) {
    lb.innerHTML = renderEmptyState('带教人');
    return;
  }
  var html = '';
  for (var i = 0; i < selectEl.options.length; i++) {
    var option = selectEl.options[i];
    html += _buildListboxItem(option.text, option.value, !!option.selected);
  }
  lb.innerHTML = html || renderEmptyState('带教人');
}

function toggleUserStoreDropdown(suffix) {
  var lb = document.getElementById('new-store-listbox');
  if (!lb || suffix === 'edit') lb = document.getElementById('edit-store-listbox');
  if (!lb) return;
  var wasHidden = lb.classList.contains('hidden');
  _closeOtherPersonnelDropdownsExcept(lb);
  if (wasHidden) {
    buildUserStoreListbox(suffix);
    if (suffix === 'edit') {
      personnelEditDropdownOpen(lb, 'edit-store-trigger');
    } else {
      iosDropdownOpen(lb, 'new-store-trigger');
    }
  } else {
    if (suffix === 'edit') {
      personnelEditDropdownClose(lb);
    } else {
      iosDropdownClose(lb);
    }
  }
}

function toggleUserRoleDropdown(suffix) {
  var lb = document.getElementById('new-role-listbox');
  if (!lb || suffix === 'edit') lb = document.getElementById('edit-role-listbox');
  if (!lb) return;
  var wasHidden = lb.classList.contains('hidden');
  _closeOtherPersonnelDropdownsExcept(lb);
  if (wasHidden) {
    buildUserRoleListbox(suffix);
    if (suffix === 'edit') {
      personnelEditDropdownOpen(lb, 'edit-role-trigger');
    } else {
      iosDropdownOpen(lb, 'new-role-trigger');
    }
  } else {
    if (suffix === 'edit') {
      personnelEditDropdownClose(lb);
    } else {
      iosDropdownClose(lb);
    }
  }
}

function toggleUserMentorDropdown(suffix) {
  var controls = getPersonnelMentorControls(suffix);
  var selectEl = controls.selectEl;
  var lb = controls.listboxEl;
  if (!selectEl || !lb || selectEl.disabled) return;
  var wasHidden = lb.classList.contains('hidden');
  _closeOtherPersonnelDropdownsExcept(lb);
  if (wasHidden) {
    buildUserMentorListbox(suffix);
    if (suffix === 'edit') {
      personnelEditDropdownOpen(lb, 'edit-mentor-trigger');
    } else {
      iosDropdownOpen(lb, 'new-mentor-trigger');
    }
  } else {
    if (suffix === 'edit') {
      personnelEditDropdownClose(lb);
    } else {
      iosDropdownClose(lb);
    }
  }
}

function selectUserStoreOption(suffix, storeId, storeLabel) {
  var hiddenEl = document.getElementById('new-store');
  var textEl = document.getElementById('new-store-text');
  if (!hiddenEl || !textEl || suffix === 'edit') {
    hiddenEl = document.getElementById('edit-store');
    textEl = document.getElementById('edit-store-text');
  }
  if (hiddenEl) hiddenEl.value = storeId;
  if (textEl) textEl.textContent = storeLabel || storeId;
  refreshPersonnelMentorSelect(suffix, {
    storeId: storeId,
    preserveCurrentIfMissing: false,
  });
  var lb = document.getElementById('new-store-listbox');
  if (!lb || suffix === 'edit') lb = document.getElementById('edit-store-listbox');
  if (lb) {
    if (lb.id === 'edit-store-listbox') {
      personnelEditDropdownClose(lb);
    } else {
      iosDropdownClose(lb);
    }
  }
}

function selectUserRoleOption(suffix, roleKey, roleLabel) {
  var hiddenEl = document.getElementById('new-role');
  var textEl = document.getElementById('new-role-text');
  if (!hiddenEl || !textEl || suffix === 'edit') {
    hiddenEl = document.getElementById('edit-role');
    textEl = document.getElementById('edit-role-text');
  }
  if (hiddenEl) hiddenEl.value = roleKey;
  if (textEl) textEl.textContent = roleLabel || roleKey;
  var lb = document.getElementById('new-role-listbox');
  if (!lb || suffix === 'edit') lb = document.getElementById('edit-role-listbox');
  if (lb) {
    if (lb.id === 'edit-role-listbox') {
      personnelEditDropdownClose(lb);
    } else {
      iosDropdownClose(lb);
    }
  }
}

function selectUserMentorOption(suffix, mentorName) {
  var controls = getPersonnelMentorControls(suffix);
  var selectEl = controls.selectEl;
  var lb = controls.listboxEl;
  if (!selectEl) return;
  selectEl.value = mentorName || '';
  if (suffix === 'edit') clearEditUserFormError();
  else clearNewUserFormError();
  syncPersonnelMentorTrigger(suffix);
  buildUserMentorListbox(suffix);
  if (lb) {
    if (lb.id === 'edit-mentor-listbox') {
      personnelEditDropdownClose(lb);
    } else {
      iosDropdownClose(lb);
    }
  }
}

/* iOS dropdown helpers for "new" suffix dropdowns */
var _iosDropdownOverlay = null;

function iosDropdownOpen(lb, triggerId) {
  if (!lb) return;
  // Close existing iOS dropdowns first
  iosDropdownCloseAll();
  // Build backdrop
  _iosDropdownOverlay = document.createElement('div');
  _iosDropdownOverlay.className = 'ios-dropdown-overlay';
  _iosDropdownOverlay.addEventListener('click', function () {
    iosDropdownClose(lb);
  });
  document.body.appendChild(_iosDropdownOverlay);
  // Position and animate the listbox
  lb.classList.remove('hidden');
  lb.classList.remove('closing');
  lb.classList.add('ios-dropdown-panel');
  // Auto-close on outside click via document listener
}

function iosDropdownClose(lb) {
  if (!lb) return;
  if (!lb.classList.contains('ios-dropdown-panel')) {
    lb.classList.add('hidden');
    iosDropdownRemoveOverlay();
    return;
  }
  lb.classList.add('closing');
  lb.addEventListener('animationend', function handler(e) {
    if (e.target !== lb) return;
    lb.removeEventListener('animationend', handler);
    lb.classList.add('hidden');
    lb.classList.remove('closing', 'ios-dropdown-panel');
    iosDropdownRemoveOverlay();
  });
}

function iosDropdownCloseAll() {
  var allLbs = document.querySelectorAll('[id$="-store-listbox"], [id$="-role-listbox"], [id$="-mentor-listbox"]');
  for (var i = 0; i < allLbs.length; i++) {
    var lb = allLbs[i];
    if (lb.id === 'edit-store-listbox' || lb.id === 'edit-role-listbox' || lb.id === 'edit-mentor-listbox') {
      personnelEditDropdownClose(lb);
    } else if (!lb.classList.contains('hidden')) {
      iosDropdownClose(lb);
    }
  }
}

function iosDropdownRemoveOverlay() {
  if (_iosDropdownOverlay) {
    var overlay = _iosDropdownOverlay;
    overlay.classList.add('closing');
    overlay.addEventListener('animationend', function () {
      if (overlay.parentNode) overlay.parentNode.removeChild(overlay);
    });
    _iosDropdownOverlay = null;
  }
}

document.addEventListener('click', function (ev) {
  var el = ev.target;
  var isTrigger =
    el.closest('[id$="-store-trigger"]') || el.closest('[id$="-role-trigger"]') || el.closest('[id$="-mentor-trigger"]');
  var insideLb = el.closest('[id$="-store-listbox"], [id$="-role-listbox"], [id$="-mentor-listbox"]');
  if (!isTrigger && !insideLb) {
    iosDropdownCloseAll();
  }
});

// Use capture so clicks inside the edit-user modal are handled before the
// modal card's stopPropagation prevents document-level bubbling.
document.addEventListener('click', function (ev) {
  var el = ev.target;
  var storeLb = el.closest('[id$="-store-listbox"]');
  if (storeLb) {
    var btn = el.closest('[data-value]');
    if (btn) {
      var suffix = storeLb.id.indexOf('edit') >= 0 ? 'edit' : 'new';
      selectUserStoreOption(suffix, btn.dataset.value, btn.dataset.label);
      ev.stopPropagation();
    }
  }
  var roleLb = el.closest('[id$="-role-listbox"]');
  if (roleLb) {
    var rbtn = el.closest('[data-value]');
    if (rbtn) {
      var suffix = roleLb.id.indexOf('edit') >= 0 ? 'edit' : 'new';
      selectUserRoleOption(suffix, rbtn.dataset.value, rbtn.dataset.label);
      ev.stopPropagation();
    }
  }
  var mentorLb = el.closest('[id$="-mentor-listbox"]');
  if (mentorLb) {
    var mbtn = el.closest('[data-value]');
    if (mbtn) {
      var suffix = mentorLb.id.indexOf('edit') >= 0 ? 'edit' : 'new';
      selectUserMentorOption(suffix, mbtn.dataset.value);
      ev.stopPropagation();
    }
  }
}, true);

