var _prRoles = []; // cached roles for personnel roles modal
var _prEditingKey = null; // null = adding new, string = editing existing

function openPersonnelRolesModal() {
  _prRoles = [];
  _prEditingKey = null;
  var body = document.getElementById('personnel-roles-modal-body');
  if (body) {
    body.innerHTML = '<div class="space-y-3">' +
      '<div class="pr-skeleton h-12 w-full rounded-lg"></div>' +
      '<div class="pr-skeleton h-12 w-full rounded-lg"></div>' +
      '<div class="pr-skeleton h-12 w-full rounded-lg"></div>' +
      '</div>';
  }
  var errEl = document.getElementById('personnel-roles-modal-error');
  if (errEl) { errEl.classList.add('hidden'); errEl.textContent = ''; }
  // 与 styles.css 中 #personnel-roles-editor-wrap:not(.is-open){display:none} 一致，须用 .is-open 控制展开，仅用 .hidden 无效
  var editor = document.getElementById('personnel-roles-editor-wrap');
  if (editor) {
    editor.classList.remove('is-open');
    editor.classList.remove('hidden');
  }
  var addBtn = document.getElementById('personnel-roles-btn-add');
  if (addBtn) addBtn.classList.add('hidden');
  openModal('modal-personnel-roles');
  apiFetch('/api/role-settings')
    .then(function (j) {
      if (!j || Number(j.code) !== 200) throw new Error((j && j.message) || '加载角色失败');
      _prRoles = (j.data && j.data.items) || [];
      renderPersonnelRolesBody();
      var isAdm = normalizeRole(localStorage.getItem('role') || '') === 'admin';
      if (addBtn && isAdm) addBtn.classList.remove('hidden');
    })
    .catch(function (e) {
      var body2 = document.getElementById('personnel-roles-modal-body');
      if (body2) body2.innerHTML = '<p class="pr-list-msg pr-list-msg--error">' + escapeHtml(e.message) + '</p>';
    });
}

function renderPersonnelRolesBody() {
  var body = document.getElementById('personnel-roles-modal-body');
  if (!body) return;
  if (!_prRoles.length) {
    body.innerHTML = '<p class="pr-list-msg">暂无角色</p>';
    return;
  }
  var isAdm = normalizeRole(localStorage.getItem('role') || '') === 'admin';
  var html = '<div class="border border-gray-200 rounded-lg overflow-hidden" id="pr-roles-list">';
  for (var i = 0; i < _prRoles.length; i++) {
    var r = _prRoles[i];
    var rk = escapeHtml(r.role_key || '');
    var rlab = escapeHtml(r.display_name || rk);
    var desc = escapeHtml(r.description || '');
    var cnt = Number(r.user_count) || 0;
    var isSys = !!r.is_system;
    var isEnabled = !!r.is_enabled;
    var rowState = isEnabled ? '' : ' pr-role-row--disabled';
    var disabledTag = isEnabled ? '' : '<span class="pr-role-row-meta pr-role-status-off">已禁用</span>';
    var actionsHtml = '';
    if (isAdm) {
      if (!isSys) {
        actionsHtml +=
          '<button type="button" data-action="toggle-role" data-key="' +
          rk.replace(/"/g, '&quot;') +
          '" data-val="' + (isEnabled ? '0' : '1') +
          '" title="' + (isEnabled ? '点击禁用' : '点击启用') +
          '" class="pr-role-switch ' +
          (isEnabled ? 'pr-role-switch--on' : 'pr-role-switch--off') +
          '"><span class="pr-role-switch-knob"></span></button>';
      }
      actionsHtml +=
        '<button type="button" data-action="edit-role" data-key="' +
        rk.replace(/"/g, '&quot;') +
        '" class="pr-role-link">编辑</button>';
      if (!isSys) {
        actionsHtml +=
          '<button type="button" data-action="delete-role" data-key="' +
          rk.replace(/"/g, '&quot;') +
          '" class="pr-role-link pr-role-link--danger">删除</button>';
      }
    }
    if (isSys && !actionsHtml) {
      actionsHtml = '<span class="pr-role-badge">系统角色</span>';
    }
    // 每行动画延迟，让列表逐行动画入场
    var delay = i * 50;
    html +=
      '<div class="pr-role-row' + rowState + '" data-role-key="' + rk.replace(/"/g, '&quot;') + '" style="animation-delay:' + delay + 'ms">' +
      '<div class="pr-role-row-main">' +
      '<div class="pr-role-row-line1">' +
      '<span class="pr-role-row-name">' + rlab + '</span>' +
      '<span class="pr-role-row-meta pr-role-row-meta-mono">' + rk + '</span>' +
      disabledTag +
      '</div>' +
      (desc ? '<div class="pr-role-row-desc">' + desc + '</div>' : '') +
      '<div class="pr-role-row-count">' + cnt + ' 名员工</div>' +
      '</div>' +
      '<div class="pr-role-row-actions">' + actionsHtml + '</div>' +
      '</div>';
  }
  html += '</div>';
  body.innerHTML = html;
}

// Event delegation for role list actions (edit, delete, toggle)
// 使用捕获阶段：#modal-personnel-roles 内层卡片有 onclick stopPropagation，冒泡到 document 会被截断，导致「编辑」等无效
document.addEventListener(
  'click',
  function (ev) {
    var rawT = ev.target;
    var el = rawT && rawT.nodeType === 1 ? rawT : rawT && rawT.parentElement;
    if (!el || !el.closest) return;
    var delBtn = el.closest('[data-action="delete-personnel-user"]');
    if (delBtn) {
      var puid = delBtn.getAttribute('data-user-id');
      if (puid) deletePersonnelUserById(puid);
      return;
    }
    var roleAct = el.closest('[data-action="edit-role"], [data-action="delete-role"], [data-action="toggle-role"]');
    if (!roleAct) return;
    var action = roleAct.getAttribute('data-action');
    var key = roleAct.getAttribute('data-key');
    if (!action || !key) return;
    if (action === 'edit-role') {
      ev.preventDefault();
      personnelRolesEditRole(key);
    } else if (action === 'delete-role') {
      ev.preventDefault();
      personnelRolesDeleteRole(key);
    } else if (action === 'toggle-role') {
      ev.preventDefault();
      toggleRoleEnabled(key, roleAct.getAttribute('data-val'));
    }
  },
  true
);

function personnelRolesToggleAddForm(editKey) {
  _prEditingKey = editKey || null;
  var editor = document.getElementById('personnel-roles-editor-wrap');
  var title = document.getElementById('personnel-roles-editor-title');
  var errEl = document.getElementById('personnel-roles-modal-error');
  if (errEl) { errEl.classList.add('hidden'); errEl.textContent = ''; }
  if (editor) {
    // 重新触发动画：先移除再添加
    editor.classList.remove('is-open');
    editor.classList.remove('hidden');
    requestAnimationFrame(function() {
      editor.classList.add('is-open');
    });
  }
  if (title) title.textContent = editKey ? '编辑角色' : '新增角色';
  // reset form
  var fields = ['personnel-roles-e-key', 'personnel-roles-e-name', 'personnel-roles-e-desc', 'personnel-roles-e-sort'];
  for (var f = 0; f < fields.length; f++) {
    var el = document.getElementById(fields[f]);
    if (el) el.value = '';
  }
  var mgrChk = document.getElementById('personnel-roles-e-mgr');
  if (mgrChk) mgrChk.checked = true;
  var keyEl = document.getElementById('personnel-roles-e-key');
  if (editKey) {
    // populate with existing data
    var role = null;
    for (var i = 0; i < _prRoles.length; i++) {
      if ((_prRoles[i].role_key || '').trim() === editKey) { role = _prRoles[i]; break; }
    }
    if (role) {
      if (keyEl) { keyEl.value = role.role_key || ''; keyEl.readOnly = true; }
      var nameEl = document.getElementById('personnel-roles-e-name');
      if (nameEl) nameEl.value = role.display_name || '';
      var descEl = document.getElementById('personnel-roles-e-desc');
      if (descEl) descEl.value = role.description || '';
      var sortEl = document.getElementById('personnel-roles-e-sort');
      if (sortEl) sortEl.value = String(role.sort_order || '0');
      var mgrEl = document.getElementById('personnel-roles-e-mgr');
      if (mgrEl) mgrEl.checked = !!role.assignable_by_manager;
    }
  } else {
    if (keyEl) { keyEl.readOnly = false; }
  }
}

function personnelRolesCancelEditor() {
  var editor = document.getElementById('personnel-roles-editor-wrap');
  if (editor) {
    editor.classList.remove('is-open');
    editor.classList.remove('hidden');
  }
  _prEditingKey = null;
}

function invalidatePersonnelRoleAssignCache() {
  _userRoleCache = null;
}

/** 与后端 personnel._ROLE_KEY_RE 一致：小写字母开头，仅小写、数字、下划线，总长 2～48 */
function isValidNewRoleKey(key) {
  return /^[a-z][a-z0-9_]{1,47}$/.test(String(key || '').trim());
}

function personnelRolesSubmitEditor() {
  var errEl = document.getElementById('personnel-roles-modal-error');
  if (errEl) { errEl.classList.add('hidden'); errEl.textContent = ''; }
  var keyEl = document.getElementById('personnel-roles-e-key');
  var nameEl = document.getElementById('personnel-roles-e-name');
  var descEl = document.getElementById('personnel-roles-e-desc');
  var sortEl = document.getElementById('personnel-roles-e-sort');
  var mgrEl = document.getElementById('personnel-roles-e-mgr');
  var roleKeyRaw = (keyEl && !_prEditingKey ? (keyEl.value || '').trim().toLowerCase() : (_prEditingKey || '').trim().toLowerCase()) || '';
  var displayName = (nameEl && nameEl.value || '').trim();
  if (!displayName) {
    if (errEl) { errEl.textContent = '请填写展示名称'; errEl.classList.remove('hidden'); }
    return;
  }
  if (!_prEditingKey && !isValidNewRoleKey(roleKeyRaw)) {
    if (errEl) {
      errEl.textContent = '角色标识须为 2～48 位：小写字母开头，仅小写字母、数字、下划线';
      errEl.classList.remove('hidden');
    }
    return;
  }
  var sortOrder = parseInt((sortEl && sortEl.value) || '0', 10);
  if (!isFinite(sortOrder)) sortOrder = 0;
  var mgrFlag = mgrEl && mgrEl.checked ? 1 : 0;
  var payload = {
    display_name: displayName,
    description: (descEl && descEl.value || '').trim(),
    sort_order: sortOrder,
    assignable_by_manager: mgrFlag,
  };
  if (!_prEditingKey) {
    payload.role_key = roleKeyRaw;
  }
  var method = _prEditingKey ? 'PATCH' : 'POST';
  var url = '/api/role-settings' + (_prEditingKey ? '/' + encodeURIComponent(_prEditingKey) : '');
  apiFetch(url, { method: method, headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) })
    .then(function (j) {
      if (!j || Number(j.code) !== 200) throw new Error((j && j.message) || (_prEditingKey ? '更新失败' : '创建失败'));
      showToast(_prEditingKey ? '已更新' : '已创建', 'ok');
      personnelRolesCancelEditor();
      invalidatePersonnelRoleAssignCache();
      return apiFetch('/api/role-settings');
    })
    .then(function (j) {
      _prRoles = (j && j.data && j.data.items) || [];
      renderPersonnelRolesBody();
    })
    .catch(function (e) {
      if (errEl) { errEl.textContent = e.message || '操作失败'; errEl.classList.remove('hidden'); }
    });
}

function personnelRolesSubmitEditorWrapper() {
  personnelRolesSubmitEditor();
}

function personnelRolesEditRole(roleKey) {
  personnelRolesToggleAddForm(roleKey);
}

function personnelRolesDeleteRole(roleKey) {
  if (!confirm('确定删除「' + roleKey + '」？')) return;
  apiFetch('/api/role-settings/' + encodeURIComponent(roleKey), { method: 'DELETE' })
    .then(function (j) {
      if (!j || Number(j.code) !== 200) throw new Error((j && j.message) || '删除失败');
      showToast('已删除', 'ok');
      invalidatePersonnelRoleAssignCache();
      return apiFetch('/api/role-settings');
    })
    .then(function (j) {
      _prRoles = (j && j.data && j.data.items) || [];
      renderPersonnelRolesBody();
    })
    .catch(function (e) {
      showToast(e.message || '删除失败', 'error');
    });
}

function toggleRoleEnabled(roleKey, newVal) {
  var en = parseInt(String(newVal), 10);
  if (en !== 0 && en !== 1) en = 1;
  // 找到开关元素并添加脉冲动画
  var switches = document.querySelectorAll('[data-action="toggle-role"][data-key="' + roleKey.replace(/"/g, '&quot;') + '"]');
  for (var s = 0; s < switches.length; s++) {
    switches[s].classList.add('pr-role-switch--toggling');
  }
  apiFetch('/api/role-settings/' + encodeURIComponent(roleKey), {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ is_enabled: en }),
  })
    .then(function (j) {
      if (!j || Number(j.code) !== 200) throw new Error((j && j.message) || '操作失败');
      showToast(en ? '已启用' : '已禁用', 'ok');
      invalidatePersonnelRoleAssignCache();
      return apiFetch('/api/role-settings');
    })
    .then(function (j) {
      _prRoles = (j && j.data && j.data.items) || [];
      renderPersonnelRolesBody();
    })
    .catch(function (e) {
      showToast(e.message || '操作失败', 'error');
    });
}

