window.loadQuickQueryConversation = loadQuickQueryConversation;
window.deleteQuickQueryConversation = deleteQuickQueryConversation;

// -------- 一句话查询结果页：折叠面板 / 模板交互 --------
function qqToggleDetail(btn) {
  var panel = btn.parentElement;
  var body = panel.querySelector('.qq-detail-body');
  var arrow = btn.querySelector('.qq-detail-arrow');
  var text = btn.querySelector('.qq-detail-toggle-text');
  if (!body) return;
  var isHidden = body.classList.contains('hidden');
  if (isHidden) {
    body.classList.remove('hidden');
    body.style.maxHeight = '0';
    body.style.opacity = '0';
    requestAnimationFrame(function () {
      requestAnimationFrame(function () {
        body.style.maxHeight = body.scrollHeight + 'px';
        body.style.opacity = '1';
      });
    });
    if (arrow) arrow.style.transform = 'rotate(180deg)';
    if (text) text.textContent = '收起查询解析详情';
  } else {
    body.style.maxHeight = '0';
    body.style.opacity = '0';
    if (arrow) arrow.style.transform = 'rotate(0deg)';
    if (text) text.textContent = '查看查询解析详情';
    var onEnd = function () {
      body.classList.add('hidden');
      body.removeEventListener('transitionend', onEnd);
    };
    body.addEventListener('transitionend', onEnd);
    setTimeout(function () {
      body.classList.add('hidden');
      body.removeEventListener('transitionend', onEnd);
    }, 400);
  }
}

function qqToggleTemplates(btn) {
  var panel = btn.parentElement.querySelector('.qq-template-panel');
  if (!panel) return;
  var isHidden = panel.classList.contains('hidden');
  if (isHidden) {
    panel.classList.remove('hidden');
    panel.style.maxHeight = panel.scrollHeight + 'px';
    panel.style.opacity = '1';
    btn.textContent = '收起查询模板';
  } else {
    panel.style.maxHeight = '0';
    panel.style.opacity = '0';
    btn.textContent = '查看全部支持的查询模板';
    setTimeout(function () { panel.classList.add('hidden'); }, 200);
  }
}

function qqToggleTable(btn) {
  var wrap = btn.parentElement;
  var panel = wrap ? wrap.querySelector('.qq-answer-table-body') : null;
  var arrow = btn.querySelector('.qq-detail-arrow');
  var text = btn.querySelector('.qq-answer-table-toggle-text');
  var collapsedLabel = btn.getAttribute('data-collapsed-label') || '查看全部结果';
  if (!panel) return;
  var isHidden = panel.classList.contains('hidden');
  if (isHidden) {
    panel.classList.remove('hidden');
    panel.style.maxHeight = '0';
    panel.style.opacity = '0';
    requestAnimationFrame(function () {
      requestAnimationFrame(function () {
        panel.style.maxHeight = panel.scrollHeight + 'px';
        panel.style.opacity = '1';
      });
    });
    if (arrow) arrow.style.transform = 'rotate(180deg)';
    if (text) text.textContent = '收起完整结果';
  } else {
    panel.style.maxHeight = '0';
    panel.style.opacity = '0';
    if (arrow) arrow.style.transform = 'rotate(0deg)';
    if (text) text.textContent = collapsedLabel;
    setTimeout(function () { panel.classList.add('hidden'); }, 280);
  }
}

function qqFillTemplate(btn) {
  var text = btn.getAttribute('data-template') || '';
  var input = document.getElementById('query-text');
  if (input && text) {
    input.value = text;
    moduleState.query.query_text = text;
    input.focus();
    input.setSelectionRange(text.length, text.length);
    // 自动提交查询
    setTimeout(function () { submitQuickQuerySend(); }, 50);
  }
}

window.qqToggleDetail = qqToggleDetail;
window.qqToggleTemplates = qqToggleTemplates;
window.qqToggleTable = qqToggleTable;
window.qqFillTemplate = qqFillTemplate;

enhanceIosSelects(document.getElementById('view-dashboard'));
checkAuth();
